window.__D("text/shaarei-teshuva/c001",{"p":[[2500660141,"מג\"ע דעשי' ליציר' ומיציר' לבריאה (שזהו ענין ג' פעמי' הבו ג' עליות דמלאכי' ונשמות דעשי' עולים ביצי' וז\"ש הבו לה' בני אלי' ומלאכי' ונשמו' דיצי' בבריאה וז\"ש הבו לה' כבוד כו' ומלאכי' ונשמות דבריאה באצי' וז\"ש הבו לה' כבוד שמו כו' בבחי' השתחוואה ממש כמ\"ש והי' מדי חדש כו') והוא הנק' ג\"כ רצוא ושוב אך אינו שב לאחור ממש אלא כפריחת עוף בב' כנפים שא' עולה וא' יורד שירידת האחד בשביל עליו' עוד דוקא (ומ\"ש בעמדם תרפנ\"ה כנפיהם עמידה זו היא בחי' ביטול לגמרי למעלה מבחי' רו\"ש וכמו עמידה דש\"ע שהוא תכלית הביטול היותר אחרון שלפני הקירוב היותר עליון כו') וכמשל החניי' שהוא רק בשביל הנסיעה עוד כנ\"ל והיינו ממש ענין מ\"ב מסעות כו' (וכן ענין אנא בכח שבק\"ש שעל המטה שהוא בשביל עליי' הנשמ' שתעל' למקור חוצבה כמ\"ש בידך אפקיד רוחי ר\"ת בא\"ר כמ\"ש עלי בא\"ר כו' א\"א שתעלה כ\"א ע\"י אנא בכח שהוא שם מ\"ב כו') וכך הוא בענין עליות דמרכבה שנושאות את הכסא כו' בחניי' ונסיעה ג\"כ כמ\"ש בזוהר נטלין ושראן כו' כנ\"ל כי כך ענין כללות בחי' המל' שלפעמי' עולה ולפעמים יורדת וירידה זו לצורך עלי' דוקא וד\"ל. אך הנה ענין ובחי' ההילוך השני הנ\"ל הוא שהולך ושב לאחור וחוזר והולך דלכאור' עומד במקום א' כנ\"ל הנה ענין שוב הזה לאחור יובן ממה שמצינו בשעת מתן תורה דכתי' וירא העם וינועו ויעמדו מרחוק דוקא והרי מצד האהבה והדביקות הי' ראוי להיות להיפך להתקרב בקירוב אחר קירוב כו' אלא מצד היראה הגדולה שנפלה עליהם נסוגו ממילא לאחור למרחוק הרבה ולא יכלו לגשת ולעמוד מקרוב שהיו מתבטלים ממציאותם וכמ\"ש וירא העם וינועו שהיו מתבטלי' לגמרי וע\"כ נרתעו ונסוגו ויעמדו מרחוק כו' ויש להבין בזה דהלא יראה זו היא באה מצד שפלות העצומ' בודאי כמו שעני ודל מצד שפלותו העצום ירא לגשת ולעמוד בקרוב לשר ומלך כו' וכה\"ג והרי מבואר למעלה דכל"],[2500660142,"שפלות והכנעה עצומה ביותר גורמת בחי' הקירוב והדביקות בעלוי יותר וא\"כ היה מהראוי להיות להיפך שהיו מתקרבי' לעמוד ולא ליסוג ולעמוד מרחוק כו' אלא מוכרח לומר שיש הפרש בין שפלות והכנעה הנ\"ל שגורם הקירוב לבחי' היראה שגורמת הריחוק דוקא. אך הענין יובן עפ\"י הנ\"ל (באות א') דשמאל דוחה יש בו ב' מדרגות הא' שמאל דוחה דמשפיע במקבל וז\"ש שמאלו תחת לראשי כו' והב' שמאל דוחה דמקבל שמשפיל א\"ע וז\"ש שמאלו תחת ראשי כו'. והנה בחי' שמאל דוחה דמקבל שמשפיל א\"ע היינו ענין בחי' עוצם השפלות וההכנעה שמשפיל א\"ע לפני כל עלי' וקירוב כמו ענין מה תשתוחחי נפשי ומה תהמי כו' מתי אבוא כו' מה שמשפיל ותשוחח נפשו אינו רק מתי אבוא ואראה פני כו' שהוא הקירוב האמיתי יותר וזהו היפך וינועו ויעמדו מרחוק שהוא שב לאחור ואינו רוצה לעמוד בקירוב כלל וכלל כו' וכן ענין ואתנפל לפני ה' כו' וכמו ותפול לפני רגליו שזהו ענין שפיכת נפש והשתחוא' דש\"ע הכל בחי' השפלות בשביל הקירוב שעושה בחי' שמאל דוחה בעצמו כדי לבוא לבחי' הקירוב יותר כחניה שבשביל נסיעה כנ\"ל והנה אין שפלות זאת יכולה להיות בעודנו עומד בקירוב והוא בעודנו שמח ומתענג על ה' כו' שהיא עילוי הנפש ודביקותה בתענוג אלקי רק צריך להשפיל א\"ע מן התענוג הזה לגמרי ולאמר לנפשו מי אנכי כי אראה פני אלקי' בעונג עליון ומזכיר עוצם פחיתת ערכו השפל בחומר גסו' גופו כו' עד שנבזה בעיניו נמאס ומתעורר בבכי' למאוס בחיי הבלו הגס מאוד (הנק' צו בראכני קייט בבחי' עצמו' ממש כנ\"ל) וזהו שעושה בחי' ביטול וריחוק בנפשו כמו שפיכת הנפש והשתוחחות כו' אבל אינו ריחוק אמיתי שהרי בהיותו בשפלות זו קרוב הוא לפני ה' ממש כי אין נק' ריחוק באמת רק כאשר חוזר ומתקשר בעצמו' חומר גופו היפך הביטול כו' אבל הבטול והכנעת עצמו בתכלית הוא עצמו הקירוב כנ\"ל בענין העתקה והזזה ממקומו בגופו שהוא עצמו הקירוב כו' והיינו בהיותו בשפלות העצומה"],[2500660143,"שבזה דוקא עיקר ההזזה וההעתקה ממקומו כו' (כנראה לכל טועם טעם קירוב אלקי שבהכרח לפי ערך קרבתו יש בו השפלות שהוא השלכת חיי הבלו במ\"ש הטבעי יותר המבואר בקונטרס הנ\"ל) וז\"ש דוד אתהלך לפני ה' גם כשמתהלך בבחי' שפלות הזאת שנראה כנסוג אחור ואינו מקורב ועומד בתענוג אדרבה משפיל עצמו בבכי' היפך החדוה האלקי' גם בזה הריחוק הוא לפני ה' ממש כמ\"ש במ\"א וכל זה בבחי' שפלות שמשפיל א\"ע שנק' שמאל דוחה שבמקבל שאין הריחוק רק בשביל הקירוב עד שגם הריחוק נק' קירוב כנ\"ל אבל הנה בחי' שמאל דוחה שבמשפיע למקבל היינו ענין ובחי' השפלות שבאה במקבל לא מצד עצמו כלל וכלל כי לא השפיל א\"ע כלל רק מצד המשפיע בלבד והוא בהיות כאשר המשפיע מראה עוז גדולתו ורוממותו בתכלית הרוממות וההתנשאו' כמו במ\"ת בהגלות נגלות רוממו' אור עצמות א\"ס ב\"ה בגילוי קולות וברקי' וענן כבד כו' דכתי' וכל העם רואי' את הקולות כו' וירא העם וינועו כו' שנפל חרדה גדולה עליהם עד שלא יוכלו לעמוד בקרוב ולא יוכלו להתאפק מלבקש על נפשם למשה לומר דבר אתה עמנו ואל ידבר עמנו אלקי' פן נמות כי תאכלנו האש כו' וכמ\"ש במ\"א בענין ובמורא גדול זו גילוי שכינה שבחי' יראה ל' נקב' היא הבאה רק מחמת הכנ' דמקבל כמו ויירא ויאמר מה נורא המקום כו' והיראה שנופלת מצד אימה ששולח ושופע מי שמתייראי' הימנו הנק' נורא בעצם הוא הנק' מורא לשון זכר וד\"ל. עד\"מ הידוע כאשר אדם מכין א\"ע ליכנס למלך שמפני רוממות המלך מתחיל להכיר ערך שפלותו עד שנרתע ומפחד ליכנס וכל זה שמאל דוחה שמשפיל א\"ע לפי ערך השגת עצמו לגבי רוממות המלך כו' וגם שנרתע מפחד הכל במדה ושיעור ערך מה שיוכל לעשות בעצמו בלבד שאינו רק כפי הקיצור בכלי השגתו ברוממו' המלך ואין שפלות וירא' זו בא' מהשפעת המלך כלל אבל כאשר כבר בא ונכנס ועומד בקרוב למלך מתבטל ומתפחד בפחד וביטול שאינו מצד הכנת"],[2500660144,"עצמו לזה כלל וכלל רק מצד אימתו של מלך מפני שהמלך כמו שהוא ברוממותו כשהוא נגלה בעין הרואה עליו תפול אימתו על הרואהו ומתפחד הרואהו דוקא כפי ערך רוממותו בעצם שנק' נורא שהוא למעלה הרבה מערך הפחד שעשה בעצמו טרם כניסתו שהי' רק לפי השגתו ברוממות המלך ולא עצמות רוממותו כו' וד\"ל. ומזה המשל יובן כללות הענין של הנמשל בבחי' מורא גדול בחי' דבר שהיא אור שפע הירא' שנמשך מעצמו' רוממו' אא\"ס ב\"ה כמו במ\"ת דכתי' וירד ה' כו' כנ\"ל וד\"ל.\n(כ) <b>ומעתה</b> יובן שזהו ענין הילוך השני הנ\"ל שהוא הולך ושב לאחור שריחוק זה ריחוק אמיתי ולא בשביל הקירוב כלל אדרבה אינו חפץ בקירוב ע\"כ בורח לעמוד מרחוק דוקא כמו וירא כו' ויעמדו מרחוק דוקא להיות שריחוק זה שהוא אינו מצד עצמו לבוא לבחי' הקירוב כנ\"ל אלא אדרבה רוצה לעמוד מרחוק הגם שבא מצד השפלות בעצמו לומר מי אנכי לבוא לגשת כו' שהוא רק מפני עוצם רוממות ה' נופל בלבו שפלות עצומ' לעמוד מרחוק כידוע וא\"כ הי' מהראוי לגרום הקירוב בעילוי יותר כנ\"ל אבל הענין הוא דאין השפלות גורם הקירוב רק בשפלות שמשפיל א\"ע דוקא כמו שמבואר למעלה בבחי' שמאל דוחה דמקבל שגורם עלי' וקירוב וגם הוא עצמו קירוב ולא ריחוק כלל אבל בחי' שפלת כזאת שבאה רק מצד המשפיע שדוחה ומשפילו למרחוק מצד ששולח עליו אימתו ופחדו כמו שהוא מצד עוצם רוממותו כו' כנ\"ל הנה אדרבה אינו בחי' קירוב כלל וכלל אלא דוקא עומד מרחוק ולא יוכל לעמוד בקרוב כלל מגודל האימה כו' והיינו ענין הילוך השני הנ\"ל ששב לאחור ממש וכמ\"ש בס\"י אם רץ לבך שוב כו' שזהו בחי' השוב שאחר הרצוא והקירוב כאשר המשפיע מפיל פחדו על המקבל עד שיעמוד מרחוק ביותר וד\"ל. אך מעתה יש להבין דלכאור' בחי' שוב זה מאחר שנסוג אחור הרי הוא בא בבחי' עצמותו היפך הביטול וההפשטה מעצמותו שע\"כ נק' ריחוק באמת למה מדרגתו יותר"],[2500660145,"עליון מבחי' הרצוא כידוע שביטול אימה זאת שמחמתו מתרחק גבוה הרבה גם מבחי' הקירוב שבא אחרי השפלות העצומה שמשפיל א\"ע בבחי' שמאל דוחה דמקבל הנ\"ל וגם יש להבין ענין הילוך זה למה נק' הילוך אחר ששב לאחור שנמצא עומד במקום א' כנ\"ל. והנה יש להקדי' לזה מרז\"ל במ\"ש וגילו ברעדה במקום גילה שם תהא רעדה שר\"ל שלא יהי' ב' דברי' גילה תחלה ואח\"כ רעדה אלא במקום גילה עצמה שם דוקא תהא רעדה וזה ב' הפכי' בנושא א' לכאורה איך יגיל וירעד כא' ממש. אך הנה ידוע דהגילה שהוא החדו' באה מצד האהבה והקירוב והרעדה באה מצד היראה העצומה עד שירעד וינוע וארכבותיו דא לדא נקשן כו'. והנה באברהם נאמ' אברה' אוהבי שהי' מדרגתו בבחי' האהבה והקירוב שהוא בחי' הגילוי וחדוות ה' כו' ובוודאי לא הי' חסר ממדרג' הירא' רק שהי' באהבתו כלולה היראה בהעלם וביצחק שהי' בבחי' הפחד אלקים וכמ\"ש ופחד יצחק וכו' הי' כלול בו בחי' אהבה וקירוב דאברהם בהעלם והיינו ע\"ד וגילו ברעדה שבגילה כלול הרעדה ופחד בהעלם ובפחד ורעדה כלול הגילה וחדוה בהעלם שזהו עיקר ההפרש בין אברהם ליצחק ויובן זה בעבודת ה' בתפלה עד\"מ כמו השרים היושבים בשמחת הסעודה של המלך ביום חתונתו או בשמחת לבו כשעושה משתה לשריו ועבדיו כאשר באה לו בשורה טובה מניצוח לשונאו וכה\"ג והנה לפי שהמלך שמה יתפעלו השרים בשמחתו וישמחו גם הם עמו ויבואו לבחי' קירוב בתכלית אך בעוצם הקירוב והחדוה עמו יאיר אור אימתו ופחדו בתוך לבבם בהעלם עד שבמקום גילה עצמה תהא אז רעדה ופחד גדול בהעלם וכן להיפך גם במקם רעדה ופחד בגילוי שם תהא גילה וחדוה מצד עוצם האהבה והקירוב בהעלם וכל העלם נקרא התכללות דבר בהיפוכו כהתכללות הגילה ברעדה או רעדה בגילה כו' אבל שיהיו שניהם כא' ממש א\"א להיות כ\"א באופן שהם דבר א' ממש ולא דבר והיפוכו כלל וזהו ענין ההפרש בין שני מיני התכללות הללו דהיינו בין התכללות"],[2500660146,"דבר בהיפוכו בהעלם שהם דבר והיפוכו עכ\"פ רק שמתכלל א' במנגדו ולא יסתור לו אבל לא שהיה כמוהו ממש ובין התכללות ב' מנגדים להיות כא' ממש והוא שיהיה הגילה עצמה בחי' רעדה ופחד והפחד עצמו הוא הגילה שזה א\"א בהיותו בבחי' התפשטות המציאות כשהוא מציא' יש ודבר מה בפ\"ע רק כאשר הוא בטל מכל עצמותו ולא נשאר בו רק בחי' עצמיותו לבד אז יוכלל בו ב' הפכים כא' ממש וזה אנו מוצאים בבחי' התכללות חו\"ג שבנפש שבבחי' יחידה התכללותם כא' ממש משא\"כ מבחי' יחידה ולמטה כמו ברצון ותענוג ושכל ומדות שמתחלקים חו\"ג ביותר רק שנכללים זע\"ז ע\"ד הנ\"ל בגילה ורעדה כו' וכמו שידוע בענין שיר פשוט ושיר כפול ושיר מרובע כו' שהשיר הוא בחי' התפעלות עצמות הנפש בעלותה מכל עצמותה כו' וכאשר השיר וניגון בא בבחי' התפשטות רצון ותענוג שמתפשט מעצם הנפש ממש כלול חו\"ג כמו קול התנועה של הניגון בחדוה בפ\"ע וקול של ניגון שבבחי' מרירות בפ\"ע נקרא חו\"ג מחולקים וכשהן מתכללים בתנועות קול א' ממוזג מאמצעות שניהם כא' לפי אופן התענוג כשכלול מדבר והיפוכו לא ניכר התחלקות ב' הפכים כלל אבל עכ\"פ יש דבר והיפוכו כמו בהתפעלות התענוג להתענג על ה' בתפלה שחדוה באה בתענוג זה מגילוי אלקים חיים בהארה וחיות והיפוכו בתנועות מרירות מריחוקו מאור גילוי אור עליון כשמשפיל א\"ע כנ\"ל והגם שהוא עצמו הקירוב שהרי מצד עוצם תשוקתו ותענוג שלו יתמרמר בהיפוכו כו' (ונקרא גבורה שבחסד שבתענוג כו') מ\"מ יש דבר והיפוכו חדוה ומרירות רק שהמרירות מכח החדוה והעונג באה וכלולה בו בהעלם בשעת גילוי העונג ולהיפך בגילוי המרירות יש העונג וחדוה בהעלם ע\"ד הנ\"ל בגילה ורעדה כו' והוא הנקרא שיר כפול מב' מדרגות דחו\"ג בעליה וירידה קירוב וריחוק כלולים זע\"ז בתנועה א' ממוזגת מאמצעות כח שניהם דוקא (כידוע לכל טועם טעם עונג האלקי בתפלה שדוקא כח העונג כלול מתנועות המרירות כאילו הוא מתענג ממש בתנועה"],[2500660147,"זו דמרירות ואינה נבדלת כלל וכלל מתנועות העונג שבחדוה כי כח א' להם וממקור א' יוצאים שניהם כא' כו' ולפ\"ז יובן מה שימצא בחי' ההשפלה העצומה הנ\"ל (באות י\"ח) שנק' (בל\"א צו בראכנקייט טיף זייער כו') הוא בא רק מכח עומק העונג שיש בנפשו בחדות ה' כו' והכל א' ומתכללים לפעמים בתנועה א' כנ\"ל ולפעמים יתחלקו להיות בזא\"ז כו') ועכ\"ז נראים כדבר והיפוכו רק שבאמת כח א' הוא ממש בבחי' יחידה עצמה והוא הנק' שיר פשוט בבחי' התפעלות עצמיות ממש הנ\"ל (באות י\"ח) שאינם נראים כדבר והיפוכו כלל רק מתאחדים בעצם ומהות א' ממש הנקרא התכללות עצמיות שאינם דבר והיפוכו כלל והיינו שיר עצמי מעצמות כל הנפש הפשוטה שחו\"ג שבעצמיות א' הוא ממש כו' (ולפ\"ז בחי' ההשפלה העצמיות הנ\"ל עם התענוג וחדוה העצמית א' הוא ממש וכנ\"ל בענין שפיכת נפש שזהו עצמו תכלית הקירוב העצמי כו') (ושיר מרובע הוא התכללות דבר והיפוכו ממש כשחו\"ג דחדוה ומרירות מתחלק עפ\"י החו\"ג דמוחי' דחו\"ב כמו בכונה שבמוח בניגון שנחלק ע\"י הדעת כו' שנעשו ד' מוחין שנקרא מרובע) וז\"ש דר\"מ היה מנגן בצלותא בכל מיני ניגון להורות על בחי' התכללות חו\"ג בכל התחלקות שלהם ברצון ומוחי' ע\"י בחי' התפעלות עצמיות דיחידה שנקרא שיר פשוט כו' ועד\"ז יוכל להיות גם ענין גילה ורעדה כא' ממש כנ\"ל והוא בהיותו בבחי' ביטול והפשטה מעצמותו ולא בהיותו בבחי' התפשטות דבר מה כמו ברצון תענוג ושכל וכו' כנ\"ל בענין שיר פשוט וד\"ל.\n(כא) <b>ואחר</b> כל זה יובן בבחי' השוב שאחרי הרצוא הנ\"ל שמעלתו יותר עליון גם מבחי' הקירוב העצמי שאחר השפלות העצומה הנ\"ל בשמאל דוחה דמקבל כו' כי הנה הגם שמבואר למעלה דמה שיוכל להיות גילה ורעדה או חדוה ומרירות כא' ממש הוא בא דוקא בבחי' התפעלות עצמות הנפש שאין למעלה מזו מכל מקום אין זה רק בבחי' הכנה דמקבל ואע\"פ שיוכל להפשיט מכל עצמותו כמו בבחי' שיר פשוט הנ\"ל (וכמו דוד שהיה"],[2500660148,"מפזז כו' בבחי' ביטול עצמותו מכל וכל כו' גילה ורעדה כא' ממש וכה\"ג) אבל אין כ\"ז ערך כלל לגבי בחי' ביטול והפשטת העצמות דמקבל כשנעשה רק מצד הארת המשפיע עליו כמו כשמתבטל מפחדו ואימתו עד שנסוג אחור ועומד למרחוק שבחי' ריחוק זה שמתרחק ביותר מפני שאינו יכול לעמוד כלל הרי זה ביטול העצמות ממש שלמעלה הרבה מבחי' התפעלות העצמיות שיש מי שמתפעל עכ\"פ כו' כמו ענין מה תשתוחחי נפשי כו' שנקרא שפיכות הנפש בהשפלה עצומה מבחי' כל העצמיות שבזה עצמו הקירוב העצמי בראותו פני אלקים ה\"ז דוקא כפי מה שיש כח התפעלות עצמיותו להכיל הקירוב כו' מה שא\"כ בחי' ביטול העצמות לגמרי עד שא\"י לעמוד כלל לא יש בכח העצמיות להכיל הקירוב והדיבוק כו' וא\"כ זהו יותר עליון הרבה ואין זה רק מכח עצם הרוממות של המשפיע בהגלות נגלות למקבל כמו שהוא בעצמו ממש שלא יכיל אז כל מהותו לעמוד במעמדו ומצבו בבחי' מהות דבר כו' ע\"כ יברח לנפשו ויעמוד מרחוק כדי שיוכל להשאר במהותו כמו וינועו ויעמדו מרחוק שזה רק מצד מורא גדול של עצמות המלך (כנ\"ל באות י\"ט) א\"כ הרי בחי' אור העצמות ממש האיר עליו ע\"כ לא יכול לעמוד כלל אשר לא יהיה כזה גם בקירוב היותר עליון מאחר שגם בקירוב היותר עליון יכול שאת בנפשו ולא יתבטל לגמרי בהכרח שאין האור שמקבל מעיקר העצמות של המשפיע שאם הי' מקבל בחי' רוממות העצמית ממש הי' מתבטל (וכמ\"ש במ\"א בענין הושיט אצבעו קטנה ביניהם ושרפן כו') לגמרי כו' והוא ענין יתרון המעלה דבחי' שמאל דוחה דמשפיע על בחי' שמאל דוחה דמקבל כו' וזהו ענין הילוך השני דהריחוק הוא ריחוק באמת ואינו בשביל הקירוב אלא אדרבה לא יכול לעמוד בקרוב ע\"כ בורח לעמוד מרחוק כו' והגם שבא אל עצמותו שהוא ההיפוך מבחי' הביטול והפשטת עצמו בקירוב כו' מ\"מ הוא למעלה הימנו הרבה כי מה שבטל מעצמותו בקירובו אינו רק ביטול ההתפשטות של עצמותו אבל בחי' עצמותו נשאר רק שהוא בבחי' התפעלות עצמיות"],[2500660149,"שלו ויש מי שמתפעל עכ\"פ כנ\"ל משא\"כ בחי' שוב לאחור שבא מכח המשפיע הרי מתבטל מכל עצמותו ואין בו כח גם להתפעל בבחי' עצמיות ע\"כ אדרבה מה שבורח יותר יותר מתבטל מפנימי' כל עצמותו ע\"כ בורח למרחוק יותר עד שכל פסיעה ופסיעה בפרט שנסוג אחור מורה ביטול העצמות ביותר שנמצא מובן דמה שנשאר אח\"כ עומד הוא רק כדי מה שיוכל לעמוד בהיותו בריחוק גדול מאוד במציאותו שזהו מפני תכלית העדר תפיסת איזה מקום לעצמותו לגמרי מצד עוצם האימה עד שנשפל בעצמו עד קצה האחרון למצוא לנפשו מקום לעמוד רק בקצה היותר אחרון וכ\"ז רק מכחו של שמאל דוחה כמו באימת המלך שהוא דוקא המשפילו למרחוק כ\"כ ולא מצד עצמו נמצא שלפי ערך הגדלת כח של המשפיע על המקבל כך יגדל ערך השפלת והתבטלו' דשמאל דוחה דמשפיע במקבל על השפלת שמאל דוחה דמקבל מצד עצמו כו' ולפ\"ז יובן ממילא שמה שנאמר בס\"י אם רץ לבך שוב כו' שוב זה הבא מצד השפלת אימת אור העצמות ממש הוא הילוך פנימי יותר מהילוך שבקירוב היותר עליון ברץ לבך כו' וד\"ל. ומעתה יתורץ הכל דמה שהשפלות גורם הקירוב הוא מצד עצמו אבל השפלות לעמוד מרחוק שמצד המשפיע הוא למעלה מן הקירוב להיותו בריחוק זה מכחו של העצמות ממש שאין לך קירוב יותר מזה וכו' ומה שחוזר והולך אחר ביטול העצמות דשוב הרי הוא בא ונכלל בבחי' העצמות ממש כענין לאשתאבא בגופא דמלכא שלמעלה מכל קירוב שאינו ביטול במציאות ממש כידוע (ולפ\"ז הרי לא ימצא שיהיה רק בחי' שוב פ\"א כי מיד בהילוכו אחר השוב יתבטל כו' אבל הענין הוא דשוב זה מבחי' ביטול העצמות הוא בא אבל עדיין לא נתבטל לגמרי ע\"כ יוכל להיות רצוא אחר שוב זה וחוזר ושוב כו') וד\"ל.\n(כב) <b>ובכל</b> הנ\"ל יובן כללות ענין ההפרש בין מ\"ש אחרי ה' תלכו ובין ואותו תיראו שהוא ענין ההפרש בין ב' מיני הילוך הנ\"ל הילוך הראשון כמו בנסיעה וחנייה שהוא בחי' ריחוק וקירוב כנ\"ל"],[2500660150,"באריכות בבחי' שמאל דוחה דמקבל כו' הוא נכלל הכל במ\"ש אחרי ה' תלכו הליכה זו בבחי' קירוב וריחוק עליה וירידה וחוזר ועולה כו' והיינו בפסד\"ז בסידור שבחי' כו' בהשגות אלקות בביטול עלול לגבי העילה עד רום המעלות שהחיצוניות עולה ונכלל בבחי' הפנימי' עד בחי' העצמות ממש כמ\"ש אליו ולא למדותיו כו' כנ\"ל (באות ט\"ז) ויש בזה בחי' ירידה שלצורך עלייה בלבד והוא שיורד מלמעלה למטה כמ\"ש למעלה (באות י\"ח) בענין השפלת עצמו שהוא עצמו הקירוב כו' שכ\"ז רק אחר ה' כו' שאינו מגיע בבחי' פנימי' והעצמות ממש וגם בבחי' שפיכת נפש דש\"ע שבא אל הקירוב לבקש את פני ה' ממש כמ\"ש מה תשתוחחי נפשי כו' כנ\"ל שם מ\"מ אין זה בבחי' פנימי' והעצמות כמו שהוא מצד עצמו רק שלגבי המקבל נק' בחי' פנימי' האור כמו יאר ה' פניו אליך בלבד לפי ערך המקבל נק' פנים כו' אבל לא לגבי עצמותו ממש משא\"כ בחי' הילוך השני הנ\"ל שהוא בחי' השוב שאחר הרצוא כו' הוא מ\"ש ואותו תיראו שזה בא מצד המשכת היראה מן המשפיע בבחי' שמאל דוחה שלו שנק' מורא גדול כנ\"ל עד שאינו יכול לעמוד מקרוב כלל רק מרחוק הרבה כנ\"ל הרי זה בא מבחי' פנימית ועצמות רוממות דאא\"ס כמו שהוא בעצמו דוקא שלמעלה הרבה מבחי' הארת פנים למקבלים כו' וזהו ואותו תיראו אותו כמו שהוא בעצמו דוקא שמזה נמשך בחי' שוב הנ\"ל כנ\"ל (באות כ\"א) באריכות וד\"ל. אך הנה עדיין י\"ל מ\"ש תיראו שזהו ענין היראה שעושה המקבל מצד כח עצמו והוא בחי' שמאל דוחה דמקבל לומר מי אנכי לגשת מקרוב כו' והיינו ענין השפלת עצמו שעושה הקירוב הנ\"ל וא\"כ היינו הך דאחרי ה' תלכו בפסד\"ז וק\"ש וש\"ע כו' ואם ר\"ל תיראו בחי' מורא גדול שנמשכת רק מצד המשפיע האימה כנ\"ל א\"כ לא יתכן בזה ענין ובחי' ציווי לומר אותו תיראו דמשמע שיש בחירה בזה שלא יהיה להם יראה זאת ע\"כ מצוה שיראו אותו ובאמת בבחי' יראה שנמשכת מצד עצמות אלקות לא יתכן בזה בחירה כלל שממילא"],[2500660151,"נופל עליו היראה בלבו בלי יוכל להמלט או לבטלה בלבו כלל (וכמ\"ש במ\"א בענין לא הספיק בצקת של אבותינו להחמיץ כו' מצד מורא גדול כו') ואמנם הנה להבין זה יש להקדים תחילה ענין ובחי' הילוך אחרי ה' באופן השני שהולך מלמעלה למטה דוקא הנז' למעלה (באות ט\"ז) והוא פי' השני בענין הליכות עולם לו והן מעשה המצות שנק' ארחות ה' ודרכי נתיבותיו שהוא עצמו הולך בהן מלמעלה מעצמותו למטה באבי\"ע כו' וכשהוא עצמו הולך מלמעלה הרי פניו בראש כו' וז\"ש אביטה אורחותיך אביטה לפני אלקים ממש כשהולך באורחותיו כו' שזהו למעלה ממדרגת ההולך אחר המלך ואינו רואה פניו כלל כנ\"ל שם באריכות שמה שלא יוכל לבוא לקירוב אמיתי זה דראי' פני אלקים כ\"א ע\"י שתשתוחח נפשי כו' כמ\"ש מה תשתוחחי כו' מתי אבוא ואראה פני אלקים וגם בחי' פני אלקים זה רק לפי ערך המקבלים לבד אבל בהילוך האדם בדרכי ה' ואורחותיו במצות מעשיות יראה פני ה' ממש שהוא מבחי' הפנימיות והעצמיות שלו ממש עד\"מ פני המלך כשהולך בעצמו כו' וזהו ג\"כ ענין ואותו תיראו שהוא ע\"י ענין מעשה המצות שאחרי הקירוב בתפילה לילך בדרכי ה' בבחי' ראי' פניו ממש כמ\"ש אביטה אורחותיך (ויראה אותיות ראיה ותיראו לשון ראיה והבטה ג\"כ) והוא עיקר בחי' השוב שאחרי הרצוא שבתפילה כידוע שזהו יותר נעלה הרבה מבחי' אחרי ה' תלכו שבתפילה והוא מטעם הנ\"ל (באות ט\"ז ושזהו המאמר דהדבק במדותיו דוקא כו') ובזה יתכן בחי' הבחירה לבחור במעשה הטוב דמצות אם לאו לכך מצוה לומר ואותו תיראו להדבק בדרכיו ואורחותיו כו' וד\"ל.\n(כג) <b>ואמנם</b> הנה עדיין לא מתישב היטב ענין זה דאותו תיראו שהרי מטעם הנ\"ל בבחי' שוב זה שאחר הרצוא דתפלה הרי הוא מורה בחי' ביטול העצמות לגמרי ורק מצד אור המשפיע שגדול הרבה מכח הפשטת עצמו שבא מכח המקבל כו' א\"כ הדרא קושיא לדוכתה איך יתכן בזה בחי' בחירה וגם"],[2500660152,"שהכונה הוא בהולך בדרכי המצות שיש בהן בחי' בחירה היא גופא יש להבין מאחר שהולך באורחות ה' ומביט ורואה פני המלך ממש כנ\"ל הרי בא לבחי' ביטול העצמו' ממילא לבלתי יוכל להפרד כו' וכמ\"ש תהי' יראת ה' על פניכם לבלתי תחטאו כו' א\"כ מה זה שהוצרך לציווי דאותו תיראו כו' וכן א' ועתה מה ה' שואל מעמך כ\"א ליראה הרי תלויה בבחיר' שצריך לשאול שירא את ה' כו' ואינה יראה עצמית ולכאור' מ\"ש ואותו לשון העלם דקאי על בחי' עצמותו ממש הרי הירא' ממיל' נופלת מהארת רוממו' העצמו' דוק' ולא מצד עצמו וא\"כ למה אמר תיראו דמשמע מצד עצמיכם כו' אך הנה להבין זה יש להקדי' מאמ' דריב\"ק במשנה למה קדמ' פ' שמע לפ' והיה אם שמוע כדי שיקבל עליו עומ\"ש תחילה ואח\"כ יקבל עליו עול מצות ויש להבין מהו ההפרש בין עומ\"ש בין עול מצות הלא גם עול מצות אינו רק מצד עומ\"ש בלבד כו'. אך הנה ידוע בענין המצות שיש בהן ב' מדרגות הא' שרש המצות כמו שהן למעלה מעלה בחי' רצונותיו ית' הפנימים ועצמיים שנק' אורחות הוי' (והוא בחי' ארחין דגלגלתא דא\"א כו' וי\"ג חוורתא בחי' פנימי' התענוג שברצון כו' כידוע) שזהו בחי' הילוך באופן הב' הנ\"ל (באות ט\"ז) שע\"ז אמ' אביטה אורחותיך שהוא בחי' פנימי' הרצון העליון כמו שהוא למעל' בעצמות אא\"ס שזהו נק' אורחין ושבילין שעצמותו ממש הולך בהן מלמעלה למטה עד\"מ מרצונותיו של אדם התחתון הפנימי' שנמשך כל עצמותו בהן כו' ונק' מצותי וחוקותי (כמו שכתוב במקום אחר בענין הקב\"ה מניח תפילין ומתעטף בציצית וכהאי גוונא כו' וגם האבות קיימו כל המצות ברוחניות כמו שהן בשרשן למעלה באצי' כו') והמדרגה הב' במצות הוא אשר ירד אור רצון העליון להתלבש למטה בפ\"מ גשמית בציצית ותפילין ולמטה (וגם למעלה הוא בחי' התלבשות האור בכלי כתפלין דמארי עלמא וכה\"ג) וכאשר הרצון בא בבחי' מעשה ודאי אין לו ערוך לגבי עצם אור הרצון שבמצוה זו עצמה כמו שהיא למעלה"],[2500660153,"ועכ\"ז נק' דרכי ה' כשאדם הולך בדרכי המצות מעשיות להיותן בשרשן למעלה בחי' אורחות הוי' ממש כידוע והוא ענין הילוך באופן הג' הנ\"ל שזהו כמו ההולך בדרך המלך שהוא רגיל לילך ואינו הולך עכשיו ואינו רואהו גם מאחוריו כו' רק אעפ\"כ נק' הולך בדרכיו וכמו בן ההולך בדרך שהיה אביו הולך בה שהוא דרכי מדותיו ורצונותיו הטובים והישרים כו' וכך הוא במצות מעשיות שנק' דרכי ה' הישרים כמו שא' כי ישרים דרכי ה' צדיקים ילכו בם כו' דאע\"פ שהמצוה שעושה למטה מלובשת בענין גשמי מ\"מ נק' דרכי ה' מצד שרשן למעלה שנק' דרך הוי' ממש וכנ\"ל בענין הליכות עולם כו' ואע\"פ שאינו רואה פני המלך מ\"מ הולך בדרך שהוא הולך כו'. ובכלל זה ענין המאמ' וכי אפשר לידבק בשכינה אלא הדבק במדותיו מה הוא רחום כו' שזהו מצות הצדקה הכוללת כל המצות כמ\"ש וצדקה תהיה לנו כו' להחיות רוח שפלים ע\"י מדת הרחמים בגשמיות שבזה דבוק במדותיו שהוא ממש כמו שדבוק בעצמות מדת רחום וחנון שבעצמות אא\"ס שהוא בבחי' א\"ס ממש להיותה דרך הוי' ממש כו' וד\"ל. וזהו ענין ההפרש בין קבל' עמ\"ש בפ' שמע ישראל כשמוסר נפשו באחד שמקבל עליו עומ\"ש דלעילא שהוא כמו שעלה ברצונו הפשוט במצותיו ממש שנק' מצו' המלך כמו שהוא בעצמו ובפ' והיה א\"ש מקבל עליו עול מצות מעשיו' שהוא הרצון הבא למטה בבחי' כלי המעשה בגשמיו' הגם שרחוק מאור פני מלך חיים כמו שהרצון הזה בבחי' עצמותו מ\"מ מקבל עליו עול מצות המלך המרומם לבדו כו' גם בהתלבשותו במעשה גשמי' למטה וזהו פי' והי' אם שמוע אל מצותי כו' להביאם למעש' שזהו נק' עבודה כמ\"ש ולעבדו כו' אבל בפ' שמע נא' ואהבת שקבלת עמ\"ש בא רק מסיבת ביטול רצון המקבל בתכלית כמ\"ש בטל רצונך מפני רצונו כו' וכמ\"ש הקים על כו' והוא בא מצד בחי' מס\"נ שבקירוב האמיתי שמשפיל א\"ע בתכלית הביטול לרצונו (וכנ\"ל באות כ\"א דשניהם כא' באין בהתפעלות עצמיות הנפש) אמנם עיקר"],[2500660154,"קבלת עול מ\"ש בא מבחי' ההשפלה בתכלי' לבטל א\"ע (כמשי\"ת) והנה הגם שבמצו' מעשיות ירד האור בהתלבשות גשמיות מ\"מ יש לעול מצות בפ\"מ שרש עליון יותר מעול מ\"ש שבלב הבא מצד הקירוב בפ' שמע וכמ\"ש הקי' על כמ\"ש סוף דבר כו' ואת מצותיו שמור בפ\"מ דוקא כידוע והוא להיו' האור בא בכלי דוקא שיוכל להתפס שם ולעמוד שזהו בחי' שוב שאחר הרצוא הנ\"ל דהנה הגם שמבחי' שמאל דוחה דאימת עול מ\"ש מצד עצם רוממותו לא יוכל לעמוד וישוב אחור ולמרחוק אבל עכ\"פ למרחוק הרבה יוכל לעמוד ולקבל אור העצמות המרומם ומתנשא כו' וכך הוא בענין מעשה המצו' להיותה רחוקה מאור פני מלך חיי' מכמו שהרצון בשרשו בעצמו' כי מלובשת בדבר גשמי יכול לעמוד ולקבל מצות המלך המרומם כו' והוא עיקר בחי' שוב שאחר הרצוא שענינו בחי' התישבו' האור בכלי דוקא היפך הביטול וההתכללו' כו' וזהו פי' האמיתי דמאמ' אם רץ לבך שוב כו' דהיינו לומר שאין עיקר הכונה גם בקירוב היותר עליון דרצוא רק בהגלות נגלות אור העצמו' שמחמתו נדחה למרחוק מגודל התפשטו' האימה שמצד העצמו' שהוא יותר נעלה מפנימי' הקירוב אמנם אין לזה בחי' תפיס' בכלי אדרבה נסוג אחור כו' אך כאשר למרחוק עכ\"פ יעמוד ויקבל הרי מקבל בזה בחי' אור עצם הרצון ממש כמו שהוא בעצמו' הרוממו' ממש רק שלא היה יכול לעמוד מקרוב לקבל מקבל מרחוק אבל הרי הוא אותו עצם הרצון ממש בלי שינוי מהות כלל וכלל רק שבא דרך התלבשו' למרחוק כו' (ולפ\"ז יתפרש עומ\"ש בפ' שמע שמקבל אימת הרוממו' שמצד הארת והמשכ' העצמו' רק שהוא מקבל עול אימת מ\"ש אבל אינו בא מכח המקבל כלל כנ\"ל וזהו בבחי' שוב שאחר הרצוא דמס\"נ דאחד ג\"כ רק כאשר הוא עדיין בשרשו שאינו יכול לעמוד מקרוב ולקבל ולא נתפס בבחי' כלי רק נסוג אחור ומקבל כמו וינועו ויעמדו כו' ובפ' והי' אם שמוע מקבל עול מצות זה בבחי' כלי כמו לאחר שיעמדו מרחוק כו'. וד\"ל)."],[2500660155,"<b>ובזה</b> מתורץ ענין ואותו תיראו ואותו קאי על בחי' העצמות ועכ\"ז תיראו מצד עצמיכם להביא במעשה בפו\"מ שתלוי בבחירה ושרשו הוא בבחי' השוב שאחר הרצוא שהוא ביטול העצמות לגמרי ושניהם אמת ולא קשיא מידי וד\"ל (אך גם מצד עצמיכם ממש יוכל להיות תיראו בעול מצות בפו\"מ והוא מצד ההשפלה בתכלית (בל\"א צו בראכנקייט צום ביין כו') שזה הגורם דוקא בחי' המעשה ולא החדוה בעונג האלקי שיוכל למלאות נפשו בחדוה ושמחה זו עצמה ולא יתחזק כ\"כ בקיום המצות וכידוע לכל עוסק באמונה שהתנועה ההפכית דוקא מן העונג שבא דוקא מצד תוקף הכח של העונג (הנקרא בל\"א קועל) כנ\"ל באות כ\"א) הוא עיקר כח של ההסכם החזק שנעשה לכל היום בסור מרע ועשה טוב בפועל ממש דוקא המבואר בקונטרס ההתפעלות וד\"ל).\n(כד) <b>ובקולו</b> תשמעו הנה אחרי ההילוך אחרי ה' בפסד\"ז והעבוד' בעומ\"ש ועול מצות שהוא בחי' שוב שאחר הרצוא כנ\"ל שזהו מ\"ש ואותו תיראו כנ\"ל. אח\"כ אמר ובקולו תשמעו שזהו במצות ת\"ת שכנגד כל המצות כמ\"ש ז\"ל ות\"ת כנגד כולן וגם נמנו וגמרו דתלמוד גדול מפני שמביא לידי מעשה כו' דא\"א לומר בפירוש ובקולו תשמעו כפשוטו בלבד שיקיימו קול דבריו במעשה בלבד אחר שכבר אמ' ואותו תיראו בקיום המצות אלא קול זה הוא קול דתורה שנק' קול ודבר ה' כמ\"ש ואשי' דברי כו' וזהו מצות ת\"ת בקול תורה להיות שומעי' בקולו קול דבר ה' זו הלכה או מקרא כמ\"ש והיו הדברי' כו' ודברת בם כו' אך אין זה מובן לכאורה דלמה א' קולו דוקא הרי מצות ת\"ת בקול דבר ה' שאדם שונה וקורא בקול עצמו כו'. ולהבין זה יש להקדי' תחלה בשרש ענין מצות ק\"ש מה היא בהיות שבאמת במצות קריאת פ' ק\"ש נכלל כל עיקר מצות ת\"ת באמרו והיו הדברי' האלה כו' ודברת בם כו' (ולכך יצא ידי חובת ת\"ת בק\"ש שחרית וערבית לחד מ\"ד בגמ') רק מפני שמצות ת\"ת כנגד כולן ותלמוד גדול שמביא לידי מעשה בפרט כך פ' ק\"ש יש בה קבלת עול מצות בכלל אבל עיקרה הוא"],[2500660156,"במצות ת\"ת שע\"ז אמר ובקולו תשמעו כנ\"ל ולזה הטעם גזרו אומר במצות קריאת ק\"ש דוקא באמרם ז\"ל בפי' שמע ישראל השמע לאזניך מה שאתה מוציא בפיך שזהו ממש כענין מצות ת\"ת בכלל כמשית' והיינו ממש פי' ובקולו תשמעו כו'. והנה יש להבין תחלה בשורש סדר שתקנו אנשי כנסת הגדולה למצות קריאת ק\"ש בין פסד\"ז ותפלה דוקא דלכאורה לפי מ\"ש ז\"ל יסדר אדם שבחו של מקום ואח\"כ יתפלל היה ראוי להיות התפלה סמוך לפסד\"ז דוקא ומה ענין ק\"ש וברכותיה שתים לפניה כו' באמצע והלא מצות ק\"ש מצוה בפ\"ע היא והתפלה מדרבנן כו' ויש להקדים לזה ביאור הפסוק דאת ה' האמרת היום כו' דקאי במצות ת\"ת כידוע להיות ידוע ביאור ענין על שלשה דברים העולם עומד תורה ועבודה וגמ\"ח שהן בחי' שלשה קוין ימין ושמאל ואמצע עבודה דקרבנות וכה\"ג בבחי' הגבורות דקו שמאל בג\"ה וגמ\"ח בקו הימין חח\"נ ותורה בקו האמצע דת\"י כו' וג' קוין בכלל נקרא אמ\"ר אש מים רוח כו' בחי' העלאות דקרבנות באש שלמעלה וכה\"ג להיות בבחי' קו השמאל דוחה דואותו תיראו ומים מבחי' החסד שיורדין מגבוה לנמוך כמצות הצדקה וגמ\"ח בבחי' קו הימין ותורה בבחי' קול ודבור ובחי' רוח הבל הדיבור ממוצע כלול מאש ומים כו' וכמ\"ש ואשים דברי כו' והיינו ג\"כ דרך כלל בג' מצות הללו אחרי הוי' תלכו בבחי' רצוא באהבה וקירוב בפסד\"ז וכו' כנ\"ל בקו השמאל דאותו תיראו ומצותיו תשמרו בבחי' שוב בקו הימין דמצות מעשיות הכלולים במצות צדקה כו' ובקולו תשמעו בקו האמצעי בחי' קול דתורה שמצות ת\"ת כוללת בחי' רו\"ש שבב' הקוין וזהו את ה' האמרת היום כו' במצות ת\"ת שכולל אש ומים כו' וכמ\"ש מימינו אש דת למו כו' כידוע. ותחלה יש לבאר ענין ב' פ' דק\"ש שמע והיה אם שמוע דרך פרט יותר דהנה ענין שתים לפניה הרי ברכת יוצר אור לנגד פ' שמע וברכה שניה דאה\"ע אהבתנו כו' לנגד פ' והיה אם שמוע להיות שאנו רואים ההפרש בכלל בין ברכת יוצר אור לברכה שניה רק כמו ענין ההפרש שבין המלאכים והנשמות שהמלאכים שרשם רק"],[2500660157,"בבחי' אותיות הדיבור דהיינו בבחי' מל' בחיצוניות העולמות וכמ\"ש וממליכים את שם האל המלך כו' וכל ברכת יוצר מדבר בשירות ותשבחות של המלאכים בחי' ביטול היש לאין כו' וברכה שנייה דאהבה רבה ואהבת עולם מדבר רק בנשמות ישראל האיך שמקושרים בעצמות אא\"ס באה\"ר ואה\"ע ורחמים וחמלה גדולה כו' שהוא בחי' אה\"ר דעצמיות שנמשך מעצמו' אא\"ס לנש\"י וכמו שמסיים הבוחר בעמו ישראל באהבה וע\"כ מזכיר את האבות באמרו בעבור אבותינו שבטחו בך ותלמדם חוקי חיים כו' וכמו שבברכת יוצר מדבר בעליית המלאכים וחיצוניות כך בפ' שמע מדבר בעליית הנשמות במס\"נ באחד בכל נפשך ובכל מאודך כו' וכמו שבמלאכים נאמר שש כנפים לאחד כו' שעלייתם ע\"י שם מ\"ב דוקא כנ\"ל כך בעלית הנשמות בפ' שמע הוא ע\"י בחי' שם מ\"ב שבפרשה זו שהן מ\"ב תיבות שמן ואהבת עד ובשעריך כידוע וברכת אה\"ר שמדבר באהבה העליונה של עצמות אא\"ס לכנ\"י מלמעלה למטה כך בפ' והיה אם שמוע מדבר באהבת כנ\"י להמשיך אא\"ס בקיום המצות מלמעלה למטה כנ\"ל בפי' הליכות עולם לו כו' והוא מ\"ש לאהבה את ה' פועל יוצא שיהא שם שמים מתאהב מלמעלה למטה ע\"י הליכות עולם לו בדרכיו שבמעשה המצות וזהו ולעבדו ולא הזכיר בכל מאודכם כמו בפ' שמע (וכמ\"ש במ\"א שלזה א' בפ' והיה א\"ש ואספת דגנך שזהו כשאין עושין רש\"מ מפני שלא הזכיר בכל מאודך כו') וזהו שהקדים בברכת אה\"ר לומר והאר עינינו בתורתך ודבק לבנו במצותיך כו' כי האבות קיימו כל המצות ברוחניות כמו שהמצות הן בשרשן למעלה באצי' ולפני האצי' כמו יעקב במקלות קיים מצות תפילין וכמ\"ש במ\"א וזהו שאו' ותלמדם חוקי חיים כל המצות כמארז\"ל קיים אאע\"ה אפילו ע\"ת כו' ואח\"כ יש לבניהם אחריהם כח ועוז לקבלת התו\"מ בגשמיות וז\"ש והאר עינינו כו' והוא ענין להיות התשוקה דכנ\"י להיות גילוי אא\"ס מלמעלה למטה בתו\"מ שיעשו וכמ\"ש ודבק לבנו במצותיך וכך בפ' והיה א\"ש אחר מס\"נ מלמטה למעלה דואהבת שבפ\"א מדבר"],[2500660158,"בבחי' ההמשכה דאא\"ס מלמעלה למטה באמרו והיה א\"ש וכידוע דיש ע\"ב תיבות מוהיה א\"ש עד ושמתם את כו' ובחי' שם ע\"ב דחסד כו':\n(כה) <b>והנה</b> להבין זה בתוס' ביאור הנה מובן ע\"פ המבואר במ\"א בשורש ענין ב' פרשיות דק\"ש שזהו בחי' התכללו' חו\"ג דאוה\"ח מתלבש בכלי הגבורה ואור הגבור' מתלבש בכלי החסד כו' והיינו ענין שם מ\"ב דפ' שמע שהוא בחי' כלי הגבורה שכל עלייה הבאה מלמטה למעלה הוא בבחי' שם מ\"ב דאנא בכח שאומרים לעליית הנשמה בק\"ש שעל המטה כנ\"ל וסמוך לקבל' שבת כנ\"ל וכך ע\"י מ\"ב תיבות הללו דואהבת עד בשעריך מתעלה הנשמה האלקית בשרשה באח\"פ כו' וידוע דכל אותיות ושם הוא בבחי' כלי להכיל האור שבו ובחי' האור שבפ' זו דשמע הוא פסוק ראשון דשמע ישראל כו' שית תיבין דיח\"ע שהוא בבחי' מדות שבחכמ' עילאה שכללותם אור האהב' שהוא מ\"ש ואהבת בקירוב ודיבוק כו' כטבע מי החסדים לדבק ולקרב היפך היראה שטבעה לרחק כטבע האש כו' ונמצא מתלבש דבר בהיפוכו המנגדו ממש שהוא אור האהבה דבחי' החסד בכלי הגבורה בחי' שם מ\"ב דמלובש במ\"ב תיבות הללו דמן ואהבת עד בשעריך כו' ובפ' והיה א\"ש הוא להיפוך דאור הגבורה מתלבש בכלי החסד שהרי עיקר ענין המצות הן רק המשכות עליונות מעצמות אור א\"ס מלמעלה למט' דהיינו שיומשך רצונו העליון שבעצמותו לבוא בבחי' הסתר ולבוש דכלי המעשה שבמצות מעשיות ממש כנ\"ל בפי' הליכות עולם לו כו' וארחות ה' כו' נמצא זהו בבחי' כלי החסד דוקא וכידוע דכללות רמ\"ח מ\"ע הן בבחי' ה\"ח ואור הגבורה מלובש בה שהוא בחי' עול מצות ששרשה רק מבחי' היראה מצד בחי' שמאל דוחה (כנ\"ל בבחי' שוב שאחר רצוא דעומד מרחוק דוקא לקבל כו') (והגם שבפ' שמע מקבל עליו עומ\"ש באימה אבל כמו שהוא למעלה שנסוג אחור כנ\"ל בלי כלי כלל כנ\"ל אבל בפ' והיה הרי האור נתפס בכלי כנ\"ל והוא בחי' גבורה שבחסד כמשית' אבל ואהבת שבפ' שמע הוא חסד"],[2500660159,"שבגבורה דשם מ\"ב שהוא בכל מאודך בלא כלי כלל כו' וד\"ל) והנה ידוע דשם ע\"ב היינו ע\"ב גשרים דגם שחסד גימטריא ע\"ב אבל בחי' התחלקות של חסד זה לע\"ב חלקים היינו מצד בחי' גבורה שבחסד דוקא כמו גבורות גשמים דהגשמים בעצם ברכה של חסד הוא ונק' גשם נדבות רק שיורדין בגבורה פי' בגבורה בהתחלקות טיפין טיפין דוקא כדי שירוה הארץ ותוליד ותצמיח כי בשטף הי' מבול כו' והיינו בגבורה שבחסד וכך בע\"ב תיבות דוהיה א\"ש עד ושמתם כו' הן בחי' התחלקות גילוי אור חסדים דרמ\"ח מ\"ע כמשל המים שהמה מתחלקים בחללי החדרים רבים שבגשר כדי שלא יצאו בשטף כו' וכמ\"ש במ\"א והתחלקות כלי החסד דע\"ב זה הוא ע\"י בחי' אור הגבורה שמלובש בו שזהו בחי' עול מצות שמצד היראה דוקא (כמ\"ש במ\"א דב' פ' דק\"ש ואמת ויציב היינו לנגד ראובן שמעון ולוי פ\"א רא\"ו ב\"ן בחי' ראיה דח\"ע שבו' תיבין דשמע מוליד בן אהבה דואהבת כו' ובחי' שמיעה דבינה לבא בפ' והיה א\"ש מוליד יראה כמו שמעתי שמעך יראתי כו' כידוע דמוח דחכ' קר ולח ונמשך בחלל ימיני ומוח בינה חם ויבש ונמשך בחלל השמאלי כו' והוא שמעון כי שמע ה' כי שנואה אנכי כו' בחי' שמאל דוחה דמשפיע במקבל מבחי' הגבורות דבינה במחשבה שהיא בחי' לאה דינא קשיא כו' ואמת ויציב הוא בחי' לוי הפעם ילוה אישי אלי שזהו בחי' התדבקות רוחא ברוחא בבחי' הרצון דמשפיע ורצון דמקבל ונק' היכל הרצון כמ\"ש במ\"א בענין ט\"ו ווין דאמת ויציב וסמיכת גאולה לתפלה בבחי' יחוד דת\"ת ומל' בהיכל ק\"ק הוא בחי' יהודה הפעם אודה את ה' כו' בחי' הודאה דש\"ע כשזוקף בשם כו') ואמנם הנה אנו רואים שבכל פ' יש העלאה והמשכה בפ' שמע עד בכל מאודך בחי' העלאה והיו הדברים כו' בחי' המשכה וכן בפ' והיה א\"ש עד ובכל נפשכם כו' העלאה עד ושמתם את דברי כו' שהוא בחי' המשכה והכל בחי' המשכה דתורה דווקא לפי ששרש התורה הוא בבחי' קו האמצעי דת\"י כנ\"ל ונק' רוח הממוצע מאש ומים דחו\"ג ומזה ראי' גמורה"],[2500660160,"שכל עיקר מצות ק\"ש הוא בת\"ת דוקא בפ' שמע והיו הדברים ודברת כו' ובפ' והיה ושמתם כו' לפי שבחי' קו האמצעי דתורה דוקא יכול לעשות בחי' ההתכללות חו\"ג דב' פ' הללו במה שבפ' שמע נכלל אור החסד בכלי הגבורה היפוכו כנ\"ל ובפ' והיה נכלל אור הגבורה בכלי החסד היפוכו כנ\"ל דוודאי מה שיוכל האור להחליף להאיר בכלי היפוכו המנגדו ומה שיוכל הכלי להכיל אור המנגדו אין זה רק מצד התכללות חו\"ג בעצם והוא כמו התכללות דחסד שבגבורה עם גבורה שבחסד כו' שהן ב' פ' הללו כנ\"ל והיינו עיקר ענין התורה דכתיב בה מימינו א\"ש ד\"ת למו בחי' אמ\"ר כמ\"ש את ה' האמרת כו' ולזה נזכר בכל פ' בחי' המשכה דתורה דוקא כי זהו עיקר מצות ק\"ש כנ\"ל וד\"ל (ובזה יובן ג\"כ טעם סמיכת סיום הבוחר כו' באהבה לואהבת דק\"ש הגם שברכה שנייה שייך לפ' והיה כנ\"ל משום דמתכללים זע\"ז ע\"י התורה אמנם מאהבה עליונ' לכנ\"י נעשה כלי החסד דע\"ב כו' בפ' והי' ומיראת דמלאכים שבברכת יוצר נעשה כלי הגבורה דמ\"ב בפ' שמע ולכאורה הוא להיפוך דאור החסד שבפ' שמע מקבל מאה\"ר דברכה שניה ואור הגבורה דפ' והיה בעול מצות המלך מקבל מיראת עול מ\"ש דמלאכים שכולם מקבלים עליהם עומ\"ש באימה כו' והיינו ענין ההתכללות בפרטות בק\"ש ושתים לפניה וד\"ל):\n(כו) <b>ובכ\"ז</b> יובן הטעם שאנשי כנה\"ג סידרו לפ' ק\"ש וברכותיה בין פסד\"ז ותפילת ש\"ע להיות שבפסד\"ז הוא בחי' ההעלאה כנ\"ל ותפלת ש\"ע הוא בחי' ההמשכה בח\"י ברכאן כידוע ובחי' מצו' ת\"ת שבק\"ש הוא בחי' הממוצע המחבר להיות בחי' ההתכללות דחו\"ג בב' פרשיות הללו כנ\"ל שזהו בקולו תשמעו שאחר מ\"ש אחרי ה' תלכו כו' כנ\"ל (ועיקר ההתכללות בפ' ציצית ואמת ויציב כי פ' ציצית שקולה כנגד כל המצות כמ\"ש וראיתם כו' וזכרתם את כל כו' וציצית גימ' תרי\"ג כי כלול רמ\"ח מ\"ע ושס\"ה ל\"ת ה\"ח וה\"ג והיינו וזכרתם כו' ועשיתם אותם ולא תתורו כו' והוא לפי שהטלית וציצית הוא בבחי' מקיפים דחו\"ב"],[2500660161,"שהן ב' פרשיות דק\"ש וכולל חו\"ג שבהן ל\"ב חוטין הן ל\"ב נ\"ח בבחי' מקיפים דוקא כידוע וגם אמת ויציב בט\"ו ווין הן ט\"ו יסודות שבה' פרצופים שכל א' כלול מחב\"ד חג\"ת נה\"י כו') ומעתה יש להבין בגוף ענין מצות ק\"ש שזהו מ\"ש את ה' האמרת היום כנ\"ל דהנה ארז\"ל במצות קריא' דק\"ש בפי' שמע ישראל השמע לאזנך מה שאתה מוציא בפיך וזהו ממש כמו מצות ת\"ת שעיקר ענינה הקריאה בדיבור בפה וכמ\"ש ודברת בם כו' כך פ' ק\"ש ישמיע לאזנו מה שהוא מוציא בפיו וזהו ענין ובקולו תשמעו שישמיע לאזניו מה שמוציא בפיו קול ודבר ה' כמ\"ש ואשים דברי בפיך כו' וכתיב למען תהיה תורת ה' בפיך כו'. והנה עיקר ענין הזה דהשמע לאזניך כו' מורה על היות שאין דיבור זה שהוא מדבר דברי עצמו כלל רק דבר ה' הוא והוא המאיר בכלי הדיבור של אדם המדבר דבר ה' ונמצא שאין הדיבור של אדם רק בחי' כלי בעלמא להכיל דבר ה' וכמו רוח ה' דיבר בי בנביאי' שהיה רק דבר ה' ולא דברי הנביא עצמו רק שכלי הדבור מכיל לדבר ה' הדוב' בפי הנביא וכך אמרו שכינה מדברת מתוך גרונו של משה בדברו דבר ה' זו תורה צוה לנו משה כמו שא' בכל פ' ויאמר ה' אל משה לאמר לבנ\"י כו' וזהו את ה' האמרת היום האמרת פועל יוצא שגורמת לו לבא בבחי' אמירה שיאמר גם הוא אמרותיו הנק' אמרות ה' ודבר ה' כמו דברי כו' כי הנה ארז\"ל בכל יושב ושונה שהקב\"ה יושב ושונה כנגדו דהיינו שיושב ושונה אותה ההלכה עצמה שהאדם שונה כמ\"ש ה' צלך כו' וכמבואר במ\"א שזהו מפני שממשיך גילוי עצמות אא\"ס שבחכמה זו שבאה בהתלבשות בהלכה זו באמרו דבר ה' זה והיינו יושב ושונה ממש כי בדבר האדם דבר ה' הרי ה' הוא המדבר דבר הלכה זו ממש מאחר שאין זה דברי עצמו כנ\"ל וכמו שאנו או' ודבריו חיים וקימים וכן ודבר אלקינו יקום לעולם כו' שדיבורו נצחי כמו שהוא בעצמו נצחי כו' רק שבלתי קריאת האדם בכלי הדיבור שלו הרי דבר ה' זה גנוז ונעלם היה בעצמות חכמתו הקדומה ומיד כשמדבר הרי מביא"],[2500660162,"דבר ה' לידי גילוי מעצמותו כאילו יושב ושונה כנגדו בדיבור עצמו וז\"ש האמרת שיאמר גם הוא דיבורו והוא דבר ה' שבפי האדם היושב ושונה וא\"צ האדם רק להטות אזניו ולשמוע לקול דבר ה' המלובש בפיו כששונה ההלכה (לפי ששונה דברו כנגדו דוקא מלמעלה למטה כמ\"ש ה' צלך בבחי' מקיף כמ\"ש במ\"א) וכך הוא במצות קריאה דפ' שמע השמע לאזניך כו' א\"צ רק להטות אזניו ולשמוע מה שאתה מוציא בפיך דבר ה' לפי שמצות ק\"ש הוא במצות ת\"ת שעיקר ענינה הוא רק כמ\"ש את ה' האמרת כנ\"ל וד\"ל. אך עדיין אין זה מובן לכאורה דהלא גם במצות ת\"ת יש ב' מדרגות מצות קריאה ומצות עיון (תורה שבכתב ותורה שבע\"פ) בתורה שבכתב מצות קריאה בדיבור דוקא כמ\"ש ודברת בם כו' ובתורה שבע\"פ מצות עיון והגיון (וגם בתשב\"כ אמר והגית בו וגם לא ימוש מפיך כו' ועכ\"פ מצות קריאה גם בלא כוונה להשמיע לאזניו יצא י\"ח מצות קריאה כידוע בעולין לקריאת התורה דגם ע\"ה שאינו יודע מה שמדבר עולה ומברך כו') ובפ' ק\"ש אמרו השמע לאזניך שצריך להשמיע לאזניו ולכוון מה שמוציא בפיו ולמה יחמיר בק\"ש יותר משאר ד\"ת דק\"ש ודאי ד\"ת הוא (ואפשר לומר דהשמע לאזניך אינו ענין הכונה להבין ולהשיג מה שאומר כי גם שאינו משיג רק שישמע באזניו מה שמדבר עכ\"פ אופן הצירופי אותיות ותיבות גם שאינו יודע פירושן כלל וכך במצות קריאה דתושב\"כ אפשר צריך להשמיע לאזניו אופן הצירופים וכשאינו שומע באזניו כלל רק קורא בפה בלבד לא יצא י\"ח ואינו כן כידוע ואמנם גם בק\"ש אם לא השמיע לאזניו יצא בדיעבד כידוע) אך הענין הוא דמה שאמר מה שאתה מוציא בפיך הוא מ\"ש ואתה מחיה את כולם שהן כ\"ב אותיות שמא' עד תי\"ו וה' מוצאו' הפה שנק' אתה שמחיה כל העולמות מאין ליש וכמ\"ש בס\"י וקבען בפה כו' וכידוע וע\"ז א' מה שאתה זה הוא המוציא בפיך צריך להשמיע לאזניו בק\"ש דוקא וזהו ג\"כ ענין ובקולו תשמעו ע\"ד הפשוט היינו לקול דבר ה' שבק\"ש תשמעו"],[2500660163,"להטות אזניכם דוא כמו שאמרו השמע לאזניך מה שאתה כו' אך יש להבין למה דוקא בק\"ש צריך להשמיע לאזניו כו' ומה שייכות זה לבחי' אתה דוקא והנה באמת זהו עיקר ההפרש בין פ' שמע לוהיה אם שמוע שבפ' שמע עיקר המצוה למצות ת\"ת כמ\"ש והיו הדברים כו' ונכלל הכל בקריאת פ' זו דוקא כידוע ובפ' והיה עיקר הענין לקיום המצות והוא מ\"ש והיה א\"ש תשמעו אל מצותי בפ\"מ ובפ' שמע עיקר השמיעה בקולו קול תורה דוקא כמ\"ש ז\"ל השמע לאזניך כו' וד\"ל:\n(כז) <b>ולהבין</b> כ\"ז צריך להקדים תחלה בתוס' ביאור ענין מאמר דריב\"ק הנ\"ל למה קדמה פ' שמע לוהיה כו' שיקבל עליו עול מלכות שמים תחילה ואח\"כ עול מצות מהו עיקר ההפרש ביניהם ושצריך להקדים עומ\"ש תחלה דוקא דהנה מבואר למעלה בענין המצות (באות כ\"ג) שיש בהן ב' מדרגות הא' כמו שהן בשרשן בבחי' עצם הרצון העליון כמו שהוא בעצמותו וזהו ענין קבלת עומ\"ש מלכות שמים דלעילא שהוא כמו שעלה במחשבה ורצונו הפשוט אנא אמלוך בחי' מל' דא\"ס וע\"ז נאמר מלכותך מלכות כל עולמים כידוע וקבלת מ\"ש זה כמ\"ש שום תשים עליך מלך הוא עד\"מ קבלת מלכות ב\"ו לעשות רצונו וגזירתו שזהו טרם שמקיים דבר גזירותו רק שמקבל עליו עול מלכות בלבד ועיקר מלכותו הוא ההשתררות לבטל כל רצון נגד רצונו ועיקר העול מלכות הוא רק ביטול הרצון מפני רצונו כידוע ולמעלה היינו רק לעשות נח\"ר שאמר ונעשה רצונו שהוא רק ביטול הרצון כדי לעשות רצונו וזהו עיקר קבלת מ\"ש דלעילא שהוא בחי' מל' דא\"ס בקבלת עול מלכות זה לעשות רצונו העליון שבכל מצותיו העליונים ולמטה הוא גם בעשותו המצוה עיקר המכוון רק עול מלכות שבציווי זה והוא שמבטל רצונו כדי לעשות רצון זה שבמצוה שאין העיקר הציווי עצמו רק מה שמבטל רצונו לבד כמו מלך שגוזר ואין כוונתו בשביל עצם הציווי והגזירה רק לנסות העם איך הוא כח ביטול רצונם בקבלת עול מלכות לבד שזהו עיקר התענוג"],[2500660164,"שבמדת המלוכה וז\"ש נח\"ר לפניו שאמר ונעשה רצונו בחי' נח\"ר זה היינו עיקר התענוג שבמלוכה שהוא כל מה שיאמר יעשו בביטול רצון מאוד אבל מצד שנעשה הדבר כרצונו הרי קבלת התענוג אינו מן העול וביטול רצון רק מעצם קיום הדבר שרצה בו והוא מצד חפצו ורצונו בעצם כשנתקיים גם שיהיה בלא ביטול רצון אין זה עיקר התענוג במלוכה רק שמסתעף ממילא כי גם בקיום רצונו יתענג ממה שנשלם רצונו כי כשאדם רוצה דבר ואינו מתקיים יש לו צער כפי ערך העונג שברצון זה ואם מתקיים נשלם העונג שברצון הרי שלימות אותו העונג והרצון אינו אלא כאשר בא לידי סוף מעשה דוקא וכך גם במדת המלוכה בסוף מעשה דקיום רצונו וגזירתו הגם שאינו רק הסתעפות מעול מלכות שהוא ביטול רצון כנ\"ל מ\"מ עיקר שלימות העונג והרצון שבמדת המלוכה שהוא להיות מלך על עם בביטול כל רצון לנגד רצונו אינו נשלם אלא כאשר בא לידי סוף מעשה בקיום דבר מלך שלטון בפו\"מ דוקא וכל זמן שלא נשלם במעשה לא נשלם עיקר ומקור התענוג שבמדת המלכות וד\"ל. וכך יובן בבחי' מלכות שמים דלעילא שבחי' רצון העליון כשבא לידי סוף מעשה דוקא שהן מצות מעשיות בפ\"מ מדריגה הב' דמצות הנ\"ל שנק' עול מצות הוא שמסתעף מעול מ\"ש דביטול רצון הנ\"ל ממיל' כי כאשר קיבל עליו עומ\"ש כמ\"ש שום תשים עליך מלך כנ\"ל ממילא יעשה רצונו ויש בכלל מאתים כו' אך מ\"מ יש יתרון מעלה בסוף מעשה שבזה נשלם יותר עיקר המקור של התענוג שברצונו הפשוט דאנא אמלוך הנ\"ל כאשר נתקיי' רצונו והגם שמצד עצם קיום רצונו כמשל אדם שנתקיים רצונו אין בזה רק שלימות העונג שברצון זה כנ\"ל אבל במדת המלוכה וההתנשאו' בזה דוקא נשלם כל עיקר התענוג שבמלוכה ולא מצד עצם חפצו ברצון זה שיתקיים בלבד כו' והיינו ג\"כ פי' שאמר ונעשה רצונו מקבל נח\"ר מקיום רצונו בפ\"מ דוקא במה שנעשה רצונו אך לא מצד עצם הרצון בלבד רק מצד שנשלם בקיום רצון בפ\"מ דוק' בחי' עיקר התענוג שבמדת"],[2500660165,"המל' כנ\"ל כי סוף מעשה עלה במח' תחילה כשהוא תחילת המח' ורצונו הפשוט דאנא אמלוך הנ\"ל וד\"ל. ונמצא שיש בחי' התכללות בעומ\"ש ועול מצות מבלי ימצא מי הראש ומי הסוף כי לפי בחי' ההתגלו' הרי עיקר התענוג בכתר מלכות רק שישתרר להיות בחי' ביטול כל רצון בתכלית העול כו' כנ\"ל והוא הראש במדרגה זו דמדת המל' וסוף מדרגתה הוא כאשר נתקיים גזירת ורצון המלך שנק' עול מצות בפ\"מ ויש בכלל ר' מנה ונכלל הסוף בראש ובאמת העיק' לתחלת התענוג שבמלוכ' אינו רק שלימותו בסוף מעשה בקיום כל רצונו אלא שא\"א להיות כ\"א ע\"י בחי' ביטול רצון א\"כ הביטול רצון הוא הטפל לגבי העיקר שהוא קיום רצונו הבא מצד עוז תוקף מלכותו ואימתו כו' דהיינו שבקיום גזירתו שם הוא ממש עוז תקפו של מלכותו כמו שהוא ובחי' ביטול רצון שבקיום זה הוא רק בחי' הסתעפות מעצם תקפו של מלכותו כסוף שנכלל בראש כו' מאחר שסוף מעשה בקיום הרצון עלה תחלה למחשבה ורצון זה דהשתררות לביטול כל רצון כו' וד\"ל. ודוגמא לכ\"ז הוא מה שמצינו במ\"ת שאמרו נעשה ונשמע ואמר מי גילה לבני רז זה שהקדימו נעשה לנשמע כי נעש' זה הוא כח הקיום בפ\"מ שנקרא עול מצות שמסתעף מעול מ\"ש שהוא השמיע' לרצונו בבחי' ביטול רצון כנ\"ל ומצד שסוף מעשה עלה במח' כנ\"ל ע\"כ הקדימו נעשה לנשמע (ושרש הענין לפי שביטול רצון אינו מגיע לבעל הרצון עצמו שמשם מקור כל רצון רק לרצון העליון כמו בטל רצונך מפני רצונו דוקא ולא מפני עצמותו ממש אבל נעשה הוא הקיום לכל רצון ולא מצד עצם הרצון רק שצריך לקיים רצונו בפ\"מ שבזה הוא מבחי' בעל הרצון שממנו תחילת המחשבה כו' וכשאמרו נעשה ה\"ז בא ג\"כ בעצמות הנפש הנקרא בחי' יחידה להיות מוכן לקיום כל רצון בפ\"מ דוקא ואח\"כ נשמע בבחי' ביטול רצון כו' מטעם הנ\"ל וד\"ל):\n(כח) <b>אך</b> הנה לפ\"ז סותר ענין המאמר דריב\"ק שיקבל עליו עומ\"ש בתחלה ואח\"כ עול מצות ובמ\"ת הי' להיפך"],[2500660166,"שהקדימו נעשה לנשמע מטעם הנ\"ל והנה התירוץ לזה ידוע להיו' מה שבחי' סוף מעשה עלה במח\"ת היינו כמו שאמרו במי נמלך בנשמתן של צדיקי' פי' במי נמלך אם להיו' לו רצון ותענוג באנא אמלוך הנ\"ל בנשמות של צדיקי' שיהיו בגופי' דוקא שזהו בבחי' סוף מעשה לקיום המצות בפ\"מ כו' וע\"כ לפי ששרש כנ\"י עלה במחשבה שהן נשמות הצדיקי' אשר נמלך בהן כו' לכך ממילא אמרו כנ\"י נעשה ואח\"כ נשמע דסוף מעשה הוא תחלת המחשבה דאנא אמלוך כו' (וכידוע דכל ישראל בני מלכים הם ששרש' מבחי' מל' דא\"ס וכמ\"ש ותרועת מלך בו כו') ובחי' המעשה עיקר התענוג ורצון שבמלוכה כנ\"ל והנה בשעת קבלת התורה הי' צריך להיות בחי' העלא' מ\"נ מלמטה למעלה מתחלה שהוא בחי' או\"ח ובבחי' ע\"ס דא\"ח בחי' המל' נק' כתר ונק' כתר מלכות כו' שהיא בחי' סוף מעשה שהקדימו לנשמע כנ\"ל אבל אח\"כ כשנתנה התורה לכנ\"י ה\"ז בחי' ההמשכה שאחר ההעלא' שהוא בא בבחי' א\"י וכידוע דשרש התורה בבחי' היושר כו' וע\"ס דאור ישר מלמעלה למטה בחי' המל' שהוא סוף מעשה בא באחרונה וכידוע בד' אותיו' דהוי' יוד כתר וחכמה ה' בינה ו' מידות ה' אחרונה סוף מעשה כו' וד\"ל) וזהו ג\"כ הטעם שבק\"ש צריך להקדי' עומ\"ש תחלה שהוא בחי' ביטול רצון בקבלת עול מלכות בלבד כנ\"ל ואח\"כ עול מצות בקיום בפ\"מ שסוף מעשה בא באחרונ' בבחי' א\"י דתיקון כו' לפי שהק\"ש שרש' במצו' ת\"ת שהוא בחי' קו האמצעי דת\"י כנ\"ל (ופי' שמוע תשמעו אל מצותי שמיעה זו בקיום בפ\"מ ולא שמיעה באוזן לבד משא\"כ פי' ונשמע דמ\"ת) (ושרש הענין לפי שהתורה נק' אמת ראש תוך סוף דא' מ\"ם תי\"ו וכידוע ועיקר מידתו של אמת הוא כאשר סופו כתחלתו דוקא משא\"כ כשאין סופו כתחלתו נק' כזב כנהר שיכזב מימיו שנפסק כו' וכמ\"ש למעלה (באות ג' וד\"ל) בפי' שפת אמת תכון לעד כו' וא\"כ הגם שסוף מעשה עלה במחש' שהוא התכללות הסוף בראש באופן שהסוף הוא הראש דלכך"],[2500660167,"עולה תחלת הרצון כו' כנ\"ל מ\"מ עדיין לא בא סוף זה לידי קיום בפ\"מ רק עדיין הוא בתחלת המחשבה בלבד דהיינו מה שתחלת מחשבתו רק בשביל סוף מעשה שסמ\"ע זה אינו רק בתחלת המח' וא\"כ אין לו שלימו' להקרא ראש ומקור לתחלת המחשבה כ\"א כאשר סופו כתחלתו בתחלת המחשבה והוא כאשר בא לידי גילוי מעשה דוקא בפ\"מ שאז דוקא נשלם בחי' סוף מעשה שעלה בתחלת המחשבה כו' וד\"ל וזהו הנק' אמת כאשר סופו כתחלתו והוא בנתינת התורה שהרצון יבוא לידי מעש' דוק' שזהו סומ\"ע שעלה במח\"ת בא לידי גילוי בפ\"מ וא\"כ מ\"ש נעשה ונשמע הגם שזהו מצד בחי' סומ\"ע שעבמח\"ת כנ\"ל אין זה אמת עדיין רק כאשר סופו כתחלתו והוא כאשר קיבלו התורה להביא הרצון בפ\"מ כמ\"ש היום לעשותם כו' שאז נשלם סוף מעשה שעלה במחשב' כנ\"ל וזהו שצריך לקבל עליו עומ\"ש בתחלה ואח\"כ עול מצות להביא בפ\"מ שיהי' סופו כתחלתו שהוא בחי' אמת דתורה וד\"ל) ולפ\"ז יוכל לפרש בחי' עומ\"ש בתחלה כענין נעשה ונשמע שקודם מ\"ת שזהו בחי' סומ\"ע כמו שהוא במח' תחל' כנ\"ל ואח\"כ עול מצות בקיו' הרצון במעש' בבחי' קבל' התור' שנקרא אמת בבחי' אור ישר דראש תוך סוף שהמעש' בא באחרונ' ובפ' שמע הוא בבחי' א\"ח דבכל מאודך שבחי' המעשה קודם למחשב' ורצון כנ\"ל בענין נעשה ונשמע כו' וכמו שבלא נעשה ונשמע דא\"ח לא היה קבלת התורה בבחי' א\"י כך בלא א\"ח דקבלת עומ\"ש בפ' שמע א\"א להיות בחי' ההמשכה דא\"י בקיום המצות בפ' והיה א\"ש דהא בהא תליא וד\"ל ולפ\"ז עולה בסגנון א' עם ענין הנ\"ל (באות כ\"ה) בבחי' התכללות חו\"ג דב' פרשיות שבפ' שמע הוא בחי' א\"ח דשם מ\"ב ובפ' והיה בחי' שם ע\"ב כו' שהוא בחי' א\"י כו' וע\"י התורה נכללים זע\"ז עד שיוכל להיות אור החסד בכלי הגבורה כו' כמ\"ש שם באריכות ואמנם משם נראה שבחי' אמת דתורה היינו בחי' הממוצע דלכך נק' בריח התיכון אמת משני טעמים א' שמחבר ימין ושמאל ולא ימצא בחי' אמת לא בימין שנפסק כחו מצד השמאל הסותרו ולא בשמאל"],[2500660168,"שנפסק כחו מצד הימין כו' אבל בקו האמצעי לא נפסק כחו כי הוא ממוצע כו' כמו שכתוב במ\"א בפי' הזוהר ונתתם לי אות אמת דא וי\"ו כו'. והטעם הב' שמבריח מן הקצה לקצה שאין כן בב' הקווין ימין ושמאל כלל לפי שמתחלת המח' שנקרא קצה העליון עד קצה התחתון בסוף מעשה שנקרא מעלה ומטה הרי המחבר לתחלה וסוף זה הוא קו האמצעי שנקרא בריח התיכון שמבריח מן הקצה כו' וכמו בכאן בסוף מעשה במחשבה תחלה שבקצה העליון שיוכל לבוא לידי מעשה בפ\"מ בקצה התחתון אין זה אלא ע\"י התורה שנקרא אמת וז\"ש לכל אשר יקראוהו באמת שיהיה סופו כתחלתו כנ\"ל ולזה ב\"פ דק\"ש שהן בחי' א\"י וא\"ח קצה העליון ותחתון ג\"כ מתכללים ע\"י התורה להיות אור התחלה בסוף והסוף בתחלה מבלי ימצא בבירור מי הראש ומי הסוף מאחר שמחבר לב' קצוות בשוה כו' וזהו ענין אמת ויציב שמאמת לאמת דפ' ק\"ש (וכמ\"ש במ\"א בענין ט\"ו ווי\"ן ויציב ומתוקן ומקובל כו' שזהו ממש כמו בקבלת התורה שמתוקן ומקובל הדבר הזה כי דבריו חיים וקיימים ולזה אמר השמע לאזניך כו' בק\"ש דוקא כמשי\"ת וד\"ל :\n(כט) <b>ומעתה</b> יובן ענין מאמרם ז\"ל בק\"ש דוקא השמע לאזניך כו' להיות כי המצוה הזאת דפ' ק\"ש כולל כל המצות כמ\"ש וזאת המצוה כו' וסמיך ליה פ' שמע כו' כי הנה מבואר למעלה בענין השמע לאזניך כו' שהוא כענין הקב\"ה יושב ושונה כנגדו שזהו פי' האמרת היום כו' ובאמת כנגדו זה אין לו הבנה מהו כנגדו דוקא אך לפי הנ\"ל היינו להיות שרש המשכה דתורה היא בבחי' א\"י שהוא היפוך בחי' א\"ח ע\"כ נקרא כנגדו שהוא א\"י הבא מלמעלה למטה לנגד בחי' א\"ח שעולה מלמטה למעלה והוא ע\"י דבר ה' זו הלכה שאדם יושב ושונה למטה אותה ההלכה עצמה יושב ה' ושונה כנגדו כמ\"ש ה' צלך צל דמקיף דא\"י כו' וענין או\"ח הוא רק בחי' קבלת עול מלכות שמים כשמדבר דבר ה' שעושה עצמו רק בחי' כלי להכיל דבר ה' בפיו כנ\"ל הרי מצמצם כל רצונו ומחשבתו"],[2500660169,"ודיבורו רק לדבר ה' הזה וכמו שרבה יתיב באימתא ופתח בשמעתתא וכמו בשעת קבלת התורה שעל כל דיבור כו' והרי אמרו היום בכל יום ויום יהיו בעיניך כחדשים כי דבריו חיים וקיימים ומתחדשים בכל יום כאלו היום שומע בהר סיני וז\"ש אשר אנכי מצוך היום ממש ולכך אמרו השמע לאזניך מה שאתה מוציא בפיך פי' מה שאתה מוציא בפיך הוא מא' עד תי\"ו בחי' כ\"ב אותיות דאורייתא שנקר' קול ה' שהיה במתן תורה ממש כמו שכתוב וירד ה' כו' וידבר כו' ודבריו חיים כו' ובחי' אתה זה הוא המוציא בפיך דבר ה' זה כנ\"ל והשמע לאזניך הוא ע\"י קבלת עול מלכות שמים לשמוע באזניו אל דבר ה' שאתה זה מוציא בפיך כמו אוזן ששמעה בהר סיני מפי הגבורה י' הדברות ממש (ופי' השמע ולא אמר שמע הוא מה שמכין לאזניו שישמע כו' וכמו שאמר עשה אזניך כאפרכסת כו' וכדי שיהיה אוזן שומעת הוא הנקרא השמע לאזניך ל' מפעיל שזהו ממש ענין נעשה ונשמע שהיה בחי' הכנה לעשות השמיעה אח\"כ במ\"ש נעשה וממילא נשמע כנ\"ל והוא בחי' קבלת עומ\"ש הנ\"ל שעושה את השמיעה וזהו השמע לאזניך על ידי קבלת עול מלכות שמים שבפ' שמע ואח\"כ ישמע מה שאתה מוציא בפיו שהוא כמו בשעת קבלת התורה כנ\"ל) וזהו את ה' האמרת היום וכמארז\"ל מה להלן באימה ויראה כו' ולכאורה איך יתכן לומר שיהיה אימה עכשיו כמו בשעת מ\"ת דכל העם רואים כו' אך לפי שהוא יושב ושונה כנגדו ממש כמו במ\"ת ע\"כ מה להלן כו' וד\"ל וזהו את ה' האמרת היום כמו במתן תורה ממש וזהו עיקר מצות ק\"ש באומרו והיו הדברים האלה כו' מצוך היום להיות בעיניך כחדשי' וע\"כ מצות ק\"ש כוללת לכל המצות כמ\"ש וזאת המצוה כו' לפי שמצות ת\"ת כנגד כולן ועיקר מצות ק\"ש הוא בשביל מצות ת\"ת דהיינו להיות הקב\"ה יושב ושונה כנגדו בכל אשר ילמוד כמ\"ש את ה' האמרת היום כו' היינו ע\"י מצות ק\"ש דוקא (ולכך יצא י\"ח מצות ת\"ת בק\"ש דד\"ת היא והיא פנימית ומקור למצות ת\"ת וגם שנחלקו לב' מצות עשה מצות ק\"ש מצות ת\"ת היינו מטעם"],[2500660170,"מצות היחוד בפסוק ראשון דק\"ש שהוא מצות כונה שבק\"ש ומכאן ואילך מצות קריאה שהוא מעל לבבך ואילך לחד מ\"ד דהיינו בפסוק ושננתם כו' או מטעם קבלת עול מלכות שמים שהוא בפסוק ראשון בלבד כמ\"ש בר\"י הנשיא שהיה מעביר ידיו כו' וד\"ל). ובכ\"ז יתורץ ענין השמע לאזניך כו' מה שמחמיר להשמיע לאזניו בק\"ש דוקא לפי דמ\"ש מה שאתה מוציא בפיך היינו כמו אתה לנוכח שאומרים אתה עשית השמים וכה\"ג כשאו' אתה בכל מקום דקאי על בחי' עצמות אלקות דוקא וגם כאן מה שאתה מוציא כו' היא א\"ת כ\"ב אתוון דאורייתא שבהן נבראו כל העולמות כמ\"ש ואתה מחיה את כולם וכידוע די' מאמרות מקבלים מי' הדברות. וכמ\"ש אם לא בריתי כו' וכתיב ואשים דברי בפיך לנטוע שמים וליסוד ארץ וכמרז\"ל אין העולם מתקיים אלא בהבל תינוקת שב\"ר משום דבחכמ' שבתורה יסד ארץ וכמ\"ש בראשית בשביל התורה שנק' ראשית דרכו כמ\"ש ואהיה אצלו אמון וכידוע בזוהר דאסתכל באורייתא וברא עלמא כו' ולזה צריך להשמיע לאזניו מה שאתה מוציא דבר ה' זה בפיך כמו בשעת קבלת התורה ממש דמה להלן באימה כו' כך מצות ק\"ש צריך לקרות באימה מאחר ששומע באזניו לדבר ה' שאתה מוציא בפיו והוא אינו רק בחי' כלי להכיל דבר ה' כנ\"ל וגם שמצות כוונה רק בפסוק ראשון היינו לכוון לבו אבל להשמיע לאזניו מה שקורא בלי כוונה בלב די במצות קריאה שבק\"ש והוא למעלה ממצות קריאה בתורה גם שהוא דבר ה' ג\"כ אך בק\"ש ע\"י קעומ\"ש צריך להשמיע לאזניו כמו שצריך לשמוע באזניו גזירת מלך בעצמו כשקוראה בפיו כידוע ואין זה עיקר רק בפ' שמע שמקבל עליו עומ\"ש שהוא ביטול רצון כנ\"ל משא\"כ בפ' והיה אם שמוע שמקבל עול מצות שלכך נאמ' בה וקשרתם ואח\"כ ולמדתם להורות שהמעשה גדול ובפ' שמע נא' ודברת בם ואח\"כ וקשרתם שתלמוד גדול וכידוע דהוקשו כל המצות לתפלין כו' לפי שעיקר מצות ת\"ת הכולל כל המצות בפ' שמע שזהו שנמנו וגמרו דתלמוד גדול מפני שמביא לידי מעשה רק"],[2500660171,"בפ' והיה א\"ש מדבר לעתיד שיקיימו כל המצות ויבורר הכל ואז ושמתם את דברי כו' לע\"ל שתהיה א\"ח עט\"ב יהיה המעשה גדול דזיל בתר טעמא למה תלמוד גדול מפני שמביא לידי מעשה א\"כ המעשה עיקר וכמ\"ש במ\"א באריכות וד\"ל :\n(ל) <b>וזהו</b> ובקולו תשמעו דהנה אחר מ\"ש על פסוד\"ז אחרי ה' תלכו כנ\"ל ואותו תיראו בפ' ק\"ש שמקבל עליו עול מ\"ש ועול מצות באימה כמו במ\"ת שאמרו נעשה כו' אח\"כ אמר ובקולו תשמעו וקאי על מצות ת\"ת שמסתעף ממצות ק\"ש בקבל' עמ\"ש דוקא וכנ\"ל בענין השמע לאזניך כו' כך א' במצות הקריאה בת\"ת ובקולו תשמעו פי' בקולו קול ה' הוא ממש אשר הי' בשעת מ\"ת הוא מלובש בקול זה שאדם שונה דבר ה' זו הלכה שע\"ז א' הליכות עולם לו שהקב\"ה יושב ושונה אותה ההלכה עצמה כנגדו בבחי' א\"י מלמעלה למטה ומאחר שקולו ממש הוא וקול הדבו' של אדם אינו רק בחי' כלי לדבר וקול ה' וכמ\"ש ודברי אשר שמתי בפיך כנ\"ל א\"כ צריך לשמוע באזנו לקול ה' זה שמדבר בפיו כענין הנ\"ל בק\"ש השמע לאזניך מה שאתה מוציא כו' וכך ממש במצות ת\"ת א' ובקולו המלובש בדיבור שלכם בד\"ת תשמעו להטות אזניכם באימה ויראה כמו להלן באימה כו'. כי דבריו חיים וקיימים ומתחדשים בכל יום כאילו היום הוא מדבר וכמ\"ש את ה' האמרת היום ממש וכנ\"ל באריכות וד\"ל:\n<b>אך</b> הנה עדיין יש להבין מ\"ש תשמעו בקולו שפשט הענין מורה ענין שמיעה זו לא שמיעה באוזן בלבד אלא תשמעו במעשה לקיים קול דברו בפ\"מ דוקא ובכל שמיעה שבכתוב שאינו רק הקיום במעשה כמו תשמעו אל מצותי לקיימם וכה\"ג רבות ובהעדר הקיום בפ\"מ א' והיה אם לא תשמעון כו' אעפ\"י ששמעו באוזן כי עיקר שמיעה באוזן הוא הקיום במעשה כידוע אך במצות ת\"ת העיקר רק בחי' שמיעה באוזן לקול ד\"ת ומצות ת\"ת מצוה בפ\"ע גם בד\"ת שאינן למעשה כלל וע\"ז יוכל לומר ובקולו תשמעו באזן גם שאינו למעשה כנ\"ל אבל באמת פי' בקולו תשמעו לקיום המעשה דוק'"],[2500660172,"שאין מקרא יוצא מידי פשוטו כידוע. אמנם הנה שניה' אמת דקול דתורה כאשר במצות ת\"ת הגם שבאה בשמיעת האזן בלבד אבל ע\"ד הנ\"ל דוקא בענין השמע לאזניך כו' בק\"ש בקבלת עמ\"ש בבחי' ביטול גדול כו' אז הוא עצמו הגורם להביא לידי מעשה בפ\"מ כל מצות ה' שלומד בתור' בדיבור שהרי הלומד שלא ע\"מ לעשות כו' וגם אמרו שלא המדרש עיקר אלא המעשה והרי אעפ\"כ נמנו וגמרו דתלמוד גדול מפני שמביא לידי מעשה א\"כ מזה הטעם מ\"ש תשמעו למעשה כפשוטו תלוי בשמיעה שבאזן לקול ה' שמדבר בד\"ת וחדא מילתא היא דהא בהא תליא והיו לאחדים ממש וד\"ל ולהבין שרש הדברים הללו הנה באמת יש להבין תחלה בטעם שגזרו אומר דתלמוד גדול אם מפני שהוא מביא לידי המעשה הרי מזה הטעם עצמו מוכרח שהמעשה עיקר אלא צריך לומר ששניהם אמת וכמ\"ש במ\"א (ומבואר למעלה באות כ\"ז) דסוף מעשה בקיום בפ\"מ עלה במ\"ת שקדם לרצון וחכמה שבתורה כו' ולזה המעש' עיקר מצד שרשה בלבד אבל כמו שיצא אור ההמשכה כסדר מתחלת הרצון הרי סוף מעשה הוא אחרון ואדרבה התורה שהיא החכמה והטעם לרצון העליון הוא בחי' הפנימי' והמקור לכל מעשה המצות עד שאין להן בחי' אור וחיות כלל בלא הארת אור החכמה שבתורה וכמ\"ש כי נר מצוה ותורה אור שהתורה נקרא אור לנר מצוה שהיא רק בחי' כלי להכיל האור ולכך מצות ת\"ת כנגד כל המצות כידוע וזהו שגזרו אומר דתלמוד גדול מפני שמביא אור וחיות לכל מעשה המצות בפ\"מ וד\"ל. ולהבין זה בתוס' ביאור יש להקדים ענין הידוע מה שבק\"ש יש רמ\"ח תיבין והוא לנגד רמ\"ח מ\"ע רמ\"ח פיקודין רמ\"ח אברים דמלכא כידוע לפי שעל מצות ק\"ש נא' וזאת המצוה כו' שכל המצות רמ\"ח כלולי' בה ע\"כ יש בה רמ\"ח תיבין ולהיו' שמצו' ת\"ת הוא במצות ק\"ש ע\"כ מצות ת\"ת כנגד כולן ותלמוד גדול כו' כנ\"ל. וביאור זה הנה יובן עפ\"י המבואר במ\"א בענין רמ\"ח פקודין רמ\"ח אברים דמלכא שזהו עד\"מ איברים החיצונים שבאדם שיש לכל אבר פעולה מיוחדת ואור וחיות ממוזג לפי אופן פעולתו"],[2500660173,"כו' וכך כל רמ\"ח מ\"ע הן בחי' כלים מכלים שונים כמו איברים כו' שכל מצוה היא בחי' כלי ואבר מיוחד לבחי' גילוי אור אלקות שבה כמו במצות צדקה נמשך גילוי אלקות בבחי' חסד שהוא למעלה חסד דרועא ימינא דקוב\"ה כו' וזהו שארז\"ל ועשיתם אתם כאילו עשאוני ברמ\"ח מ\"ע ברמ\"ח איברים בציור אדם כי מצד עצמות אא\"ס נאמר כי לא אדם הוא וכמ\"ש דלאו מכל אינון מידות כלל כו' וכמ\"ש במ\"א (ומבואר למעלה בפר' כג) דמצותי היינו מצות הוי' ממש שהקב\"ה מקיי' בעצמו כמו הקב\"ה עוסק בתורה ג\"ש ראשונות ביום כו' ומניח תפילין ומתעטף בציצית ומתפלל כו' כידוע וד\"ל:\n(לא) <b>והנה</b> בחי' רמ\"ח איברים דמלכא דרמ\"ח מ\"ע הנה המה עד\"מ באדם התחתון שיש ב' מדרגות באברי' א' אברי' החיצונים כיד ורגל וראש כו' שבזה דוקא יש מספר רמ\"ח כמו שאמרו ל' בפיסת היד כו' עד תשעה בראש כו' והב' בחי' איברים הפנימי' כמו לב וריאה קנה ושט וכה\"ג שלא נמנו במנין מספר רמ\"ח כלל להיותם מקורי' פנימים לכל האברים החיצונים שמהם יושלח אור שפע החיות בדם שבגידין ועורקים המתפשטים באיברים וכללותם הן מוח ולב וכבד ג' אברי' פנימים הכוללי' לכללות השפע וחיות של כל האיברים כידוע אך הנה דרך פרט יותר יש הפרש גדול באיברים פנימים ג\"כ בין איברי הנשימה לאברי המזון כמו לב וריאה קנה ושט כו' שהקול ודיבור ובחי' המוחין נמשכים בהם וחצר הכבד מבדיל בין אברי הנשימה לאברי המזון כקיבה וכליות כו' שהם לעיכול המזון לשלוח להם חיות גשמי שבדם הוא הנפש בלבד אבל רוח החיים שבלב שמקבל מן הנשמה שבמוח וגם הבל הקול ודיבור שבקנה כו' שנמשך מן הריאה שמקבלת אויר דרך הקנה ממוח ולב יחד כו' ובא הקול בה' מוצאות כו' זהו הכל עיקר פנימי' החיות של האדם בבחי' חיות רוחני המקור לחיות גשמי שבדם הנמשך באיברים החיצונים כו' (וכמ\"ש במ\"א) שזהו הנקר' אדם פנימי כי נפש הטבעית בדם כל חי שבאברים חיצוני' בגידים ובשר ועצמות נקרא אדם חיצוני"],[2500660174,"ובחי' המוחין שבראש שמתפשטים בקנה ושט ובלב נק' אדם פנימי ובתחלת יצירתו של אדם שכולל רמ\"ח איברים כו' הרי הוא כח ההיולי של כל רמ\"ח איברים החיצונים וכך במצות ע\"י ה\"ח המגדילים נעשה רמ\"ח כידוע דכל ספי' כלול מט' וט' פעמים ט' עולה פ\"א ולנגד ג' כלים פנימי ואמצעי וחיצון עולה רמ\"ג שהוא ג' פעמים פ\"א ועם ה\"ח המגדילים עולה רמ\"ח כו' וכל גידול הזה הוא שרשו רק מבחי' המוחין דאדם זה ובכלל זה הוא הגידין שבמוח בלא דם שמתפשטים בכל האיברים החיצונים שזהו עיקר קיום אור חיותם והוא כונה שבמצוה כמ\"ש במ\"א בענין כונה ברכה מעשה שנכלל בג' מדרגות דבשר וגידים ועצמות כו' (ומ\"ש אדם כי ימות באוהל אהלה של תורה כי אדם פנימי דבחי' המוחין ע\"ז א' זאת תורת האדם בחי' מקור רוחני לאדם חיצוני דרמ\"ח אברי' דמ\"ע ואין לאדם חיצוני חיות רק מאדם פנימי דתורה שנק' תורת האדם כו') והנמשל מאברים שבאדם התחתון יובן למשכיל למעלה בשרש ענין התורה והמצות למעלה דמה שאמרו רבותינו ז\"ל ועשית' אתם כאלו עשאוני ברמ\"ח אברים היינו מצות מעשיות בפ\"מ שנקראים בחי' רמ\"ח אברים דמלכא החיצוני' שיש בהן מספר רמ\"ח דוקא כמו שלשים בפסת היד כו' עד גם בבחי' המוחין שהן שרש כל הכוונו' שבמצות מעשיות יש בזה מספר והן ט' בראש כמו ט' איברים גשמים בראש שהן כלים לבחי' המוחין שבראש כו' (והוא נמשך מן מצות ת\"ת דגם שעיקר המצוה דת\"ת הוא רק בלימוד החכמה דתורה אור הנ\"ל שהוא בבחי' המוחין עצמם שבראש שהוא ראש ומקור פנימי לכל האברים חיצונים אבל מ\"מ הרי בא לכלל מצוה בקריאה ודיבור גשמי שזה בחי' כלי עכ\"פ ע\"כ יוכל להיות מזה מקור לכל ראשי אלפי ישראל שנשמתם יש להם שרש במוחין שבראש דכנ\"י להיות להם בחי' כלים חיצונים למוחין שבראש והן ט' איברים חיצונים שבראש שבהם ועל ידם יומשך כוונות פרטיות לכל המצות מעשיות ולכך הן במספר ט' דוקא מפני שכוללים ג' מדרגות חב\"ד חג\"ת נה\"י שבכל מצוה שהן בחי' בשר גידים ועצמות שבכל אבר בפרט"],[2500660175,"כמ\"ש במ\"א וד\"ל) ולמעלה היינו מצותי (כמו הקב\"ה מניח תפילין ומתעטף בציצית כנ\"ל) אבל בחי' איברים פנימים כריאה ולב כו' לא נמנו במספר רמ\"ח כלל לפי שהוא מבחי' אדם פנימי שבבחי' המוחי' עצמם שבראש שהוא מקור פנימי לכל חיות אור רוחני שברמ\"ח איברים דמלכא למעלה והוא ענין שרש מצות ת\"ת בקול ודיבור דוקא וכמו למטה באדם התחתון כשיושב ושונה ד\"ת בקול ודיבור הרי הקול נמשך מן הקנה וריאה כו' שהוא נמשך מבחי' המוחי' עצמם שבראש שזהו שרש ומקור פנימי לכל אברים החיצוני' שלו וכך כשיושב הקב\"ה ושונה כנגדו ממש כנ\"ל הרי הקב\"ה הוא בחי' אדם העליון בחי' ז\"א דאצי' שעל הכסא יושב ושונה בקול ה' ודיבור העליון שנמשך מבחי' המוחין העליונים שבראש דאדם זה כמו ג\"ש הראשונות יושב הקב\"ה ועוסק בתורה כו' וכענין את ה' האמרת היום שהוא כענין אמירה באדם התחתון בדברו בד\"ת וא\"כ ע\"י מצות ת\"ת למטה שיושב הקב\"ה ושונה כנגדו יש בזה המשכות מוחי' פנימים המקוריים לכל רמ\"ח איברים דמלכא כמובן ממשל הנ\"ל באיברים פנימים שבאדם התחתון כו' ולכך מצות ת\"ת כנגד כל המצות לפי שבכל מצוה בפרט אינו רק יקב\"ה ושכינתיה (בחי' זו\"נ) בבחי' אבר חיצוני וכללותם נכלל במקורם הפנימי שהוא מצות ת\"ת בקול ודיבור מן המוחים עצמם כו' וזהו הנק' בחי' יחודא עילאה שנקרא בזוהר אתדבקות רוחא ברוחא חב\"ד בחב\"ד דהיינו בחי' מוחין חב\"ד דכנ\"י בדברם בד\"ת שיושב הקב\"ה ושונה כנגדו בחי' חב\"ד שבז\"א כו' ה\"ז התקשרות ויחוד חב\"ד בחב\"ד שזה רוחא ברוחא שזהו יותר עליון מיחוד גופני דבחי' רמ\"ח איברים החיצונים וכו' ולכך אמרו דתלמוד גדול מפני שמביא לידי מעשה מפני שהוא בחי' מקור פנימי לכל יחוד המצות מעשיות ברמ\"ח איברים החיצונים כנ\"ל וד\"ל. ובכל זה יובן ענין ובקולו תשמעו בשני הפירושים הנ\"ל שמיעה באוזן לקול ה' הוא בחי' מצות ת\"ת בקול ודיבור בלבד שמזה דוקא נמשך שרש ומקור בחי' המעשה בפ\"מ דרמ\"ח מ\"ע שנק' רמ\"ח איברים החיצונים"],[2500660176,"ולכך הא בהא תליא והיו לאחדים ממש (כי אדם חיצוני אין לו קיום חיות רק מבחי' אדם פנימי דאור תורה שנק' זאת תור' האד' כנ\"ל) וזהו הטעם ג\"כ אשר בק\"ש יש רמ\"ח תיבין לנגד רמ\"ח מ\"ע דוקא כי מצות ק\"ש כוללת רמ\"ח מ\"ע שבפ\"מ דוקא כמ\"ש וזאת המצוה כו' ומצות ק\"ש היא בחי' פנימי' ומקור לכל רמ\"ח מ\"ע ע\"י שהיא בחי' פנימית למצות ת\"ת בקריאה ודיבור וע\"כ רמ\"ח תיבין שבק\"ש המה בחי' פנימי' שרשים ומקוריי' לרמ\"ח איברים דמלכא שבמעשה המצוה (וזהו שההוא ינוקא הבין בריחא דלבושייהו שלא קראו ק\"ש כי הק\"ש היא בבחי' יח\"ע דחו\"ב שבראש ומקור ליחוד דזו\"נ שע\"י המצות מעשיות כמ\"ש במ\"א ואע\"פ שעסקו במצות הכנסת כלה זהו מצוה פרטי' ולא נשלם בה הכלל המקורי כו' אבל המה עשו עכ\"ז כהוגן במה שנפטרו מן הק\"ש כי מצות הכנסת כלה ביחוד גופני שרשו ביח\"ע דאו\"א כמ\"ש בעטרה שעטרה לו אמו ביום חתונתו שנמשך מהם מוחי' לזו\"נ להוליד והוא במקיף דחופה כו' כידוע וד\"ל):\n(לב) <b>ואותו</b> תעבודו הנה קודם ובקולו תשמעו הזכיר ואת מצותיו תשמרו שהוא בחי' המשכות אלקות מלמעלה למטה כמו במצות צדקה וגמ\"ח שכולל לכל המצות כי על ג' דברים העולם עומד על התורה ועבודה וגמ\"ח שהן ג' קווין כידוע ואחרי ה' תלכו ואותו תיראו בבחי' רו\"ש בבחי' העלאה ואת מצותיו תשמרו בבחי' המשכה ובקולו תשמעו בקול דתורה ממוצע מהעלאה והמשכה וא\"כ מ\"ש ואותו תעבודו א\"א לומר כמו עבודה דקרבנות שהן בחי' העלאה ממש שכבר אמר תלכו ותיראו אלא צריך לומר דקאי על בחי' עבודה שבלב זו תפלה בח\"י ברכאן כו' אך לכאורה הנה גם התפלה בבחי' העלאה שהרי התפלה במקום קרבן ממש תיקנו תפלה של שחר במקום תמיד של שחר כידוע א\"כ היינו הך ולכאורה מהו ההפרש בין העלאת הקרבן בהמה על גבי המזבח ליכלל באש של מעלה להעלאת נפש הבהמית דנוג\"ה בשעת התפלה בעבודה שבלב בהתלהבות אש ה' כו' (ע\"י"],[2500660177,"אדם בחי' מ\"ה דמברר לב\"ן כידוע בפי' אדם כי יקריב מן הבהמה וכמש\"כ אדם ובהמה תושיע כו' אדם גי' מ\"ה ובהמה גי' ב\"ן וכתיב וזרעתי את ב\"י זרע אדם שזרוע לצדיק עליון כמ\"ש אור זרוע לצדיק כו' שהוא נה\"א וזרע בהמה נפש דנוגה נה\"ב וכמ\"ש רוח האדם העולה כו' ורוח הבהמה היורדת למטה כו') והנה באמת יש להבין עוד מה שהתפלה מדרבנן ולא נמנה בכלל רמ\"ח מ\"ע דלכאורה היא העולה על כלנה מאחר שהתפלה היא עיקר דביקות הנפש באלקות כו' וגם יש להבין למה תקנו אנשי כנה\"ג לק\"ש וברכותיה בין פסד\"ז לתפלה ומה שייכות לתפלה עם ק\"ש שקדמה לה (כידוע בענין סמיכת גאולה לתפלה שהוא בבחי' היכל ק\"ק היכל הז' ובאמת ויציב בחי' היכל הרצון ובק\"ש בואהבת הוא היכל האהבה וסדר המדרגות תחלה בהיכל אהבה דק\"ש ואח\"כ בהיכל הרצון ואח\"כ בהיכל ק\"ק היכל הז' כו') אך הנה שרש הענין הוא להיות שמבואר למעלה בבחי' מדרגות חלוקות דתורה ומצות שהתורה בבחי' מוחין ואברי' הפנימי' שבאדם והמצות בבחי' רמ\"ח איברים החיצונים והן רמ\"ח תיבין שבק\"ש כו' כמ\"ש שם באריכות והנה שרש התפלה הוא בבחי' ח\"י חוליות שבשדרה והן בחי' ח\"י ברכאן דש\"ע שהן בחי' ח\"י חוליות דאדם העליון דאצי' וז\"ש ח\"י ח\"י הוא יודוך כו' ונק' צדיק ח\"י עלמין (ובל' הגמרא אמרו בליליא מה עביד קוב\"ה רוכב על כרוב קל שלו ושט בח\"י אלף עולמות שנא' רכב אלקי' רבותים כו') ולזה הטעם לא נמנה התפלה במנין רמ\"ח מ\"ע כי המצות הן בבחי' איברי' דמלכא אבל התפלה בח\"י חוליות הוא בחוט שבח\"י חוליות שבו ועל ידו עובר ההמשכה וחיבור אור וחיות מן המוחין שבראש בשביל קיום כללות כל הגוף לאיברים פנימי' וחיצוני' כי ע\"י החוט שמתחבר ע\"י ח\"י חוליות יש בחי' קיום והעמדה לכל הגוף מראש לרגל כא' כו' וד\"ל.\n<b>(וכמו</b> שכל המצות הן למעלה בבחי' אדם העליון דאצי' כמו שאמרו הקב\"ה מניח תפילין ומתעטף בציצית כו' כך גם בחי' התפלה הקב\"ה מתפלל וכורע בברוך בח\"י חוליות כו' ועד\"ז הוסדו ח\"י ברכאן"],[2500660178,"דצלותא באדם התחתון לכרוע בברוך כו' בח\"י חוליות שזהו שרש התפלה כדי להמשיך מבחי' עצמות מוחין דגלגלתא כו' עד רום המעלות מעצמות אא\"ס ממש וד\"ל). ולזה הטעם יש יתרון מעלה בשרש התפלה מכל המצות שנקראים רמ\"ח איברים דמלכא וגם למעלה משרש התורה שהיא רק במוחין והתפלה מאחר שמחבר המוחין עם כללות הגוף ביחד מראש לרגל בהכרח ששרשה בבחי' מקיף שמקיף ראש ורגל כא' והיינו שאמרו חז\"ל מניין שהקדוש ברוך הוא מתפלל שנאמר והביאותים כו'. וכתיב תפלה לאל חיי. פי' הקב\"ה הוא בחי' ז\"א ואל חיי הוא עצמות המאציל כו' ומשם נמשך לו בחי' מקיף מראש לרגל ע\"י ח\"י חוליות כו' (ואע\"פ שאין לו גוף ולא דמות הגוף דברה תורה כלשון בני אדם שבאמת נאמר כי לא אדם הוא כמ\"ש ולאו מכל אינון מדות כלל כו'). וזהו ואותו תעבודו להמשיך בחי' פנימי' ועצמות אא\"ס בח\"י ברכאן דצלותא כדוגמת ח\"י ברכאן דלעילא בתפלה שהקב\"ה מתפלל בבחי' האצי' כו' ולזה סמכו קודם לתפלה מצות ק\"ש וברכותיה שהן רמ\"ח תיבין דק\"ש בקבלת עומ\"ש להיות שרש לרמ\"ח פיקודין רמ\"ח איברים דמלכא ואח\"כ להמשיך פנימי' ועצמות המוחי' ע\"י ח\"י חוליות כו' בתפלה בח\"י ברכאן כו':\n(לג) <b>ולהבין</b> זה בתוס' ביאור הנה תחלה יש להבין שרש ענין התפלה איך שהיא במקום קרבן בהמה ע\"ג המזבח דכתיב בי' לחמי לאישי כו'. דהנה ידוע בענין הקרבנות שהן בחי' העלא' הבירורי' דרפ\"ח כו' להיות כי שרש הבהמה למעלה הוא מפני שור כו' וידוע דשרש דצ\"ח הוא מבחי' התוהו שלמעלה מבחי' אדם דתיקון ולזאת יש בכח הצומח וחי לזון לנפש האדם כמו ע\"י הלחם שיתחזק הלב והמוח כו' וכמ\"כ נא' בקרבנות לחמי לאישי כו' לחם אלקיך הוא מקריב כו' לפי שהעלא' הבהמה גשמי' ע\"ג המזבח עולה לשרשו בבחי' בהמה רבה שלפני אדם דתיקון ע\"כ נק' לחם ה' ועד\"מ לחם שאדם התחתון אוכל הנה תחלה נברר המאכל באצטומכא"],[2500660179,"והמובחר נעשה דם ושולח הכבד החיצוניות לאברים והפנימיות ללב ומן הלב עולה למוח ומחזק לאור החיות ההיולי שבכלי המוח והרי יש כאן ג' ברורים א' בהיפוך המאכל לדם בכבד ובירור שני מן הכבד אל הלב ובירור הג' שעולה ונברר מן הלב אל המוח והוא ג' כלים דמוחא ולבא וכבדא שמלובש בהן נר\"נ נפש בכבד ורוח בלב ונשמה במוח ועולה סדר הבירורים מלמטה למעלה מנפש שבדם שבכבד לרוח שבלב ומרוח שבלב לנשמה שבמוח וזהו בבחי' ההעלא' מלמטה למעלה ואח\"כ ע\"י בחי' העלא' זו דוקא נמשך בחי' המשכ' חדשה מלמעלה למטה דוקא והיינו אחר חיזוק המוח ממה שנברר חיות היותר רוחני בנשמה שבמוח ע\"י המאכל נמשך והולך אל רוח החיים שבלב לחזקו לרוח זה בבחי' חיות רוחני (והוא תוס' חיזוק החיות רוחני שבלב ואיברים אחר העיכול דוקא יותר מבשעת האכילה שאינו אלא סועד הלב שלא יפול בגרעון אור וחיות כו') בחלל הימיני ומשם לחלל השמאלי ונמשך לנפש שבדם שבכבד לחזק רוחניות דנפש שבדם שבאיברים כו' וכך יובן למעלה (הגם שאין לו גוף ולא דמות אדם דברה תורה כו') כשאמר לחמי לאישי כו' הרי עולה הקרבן מלמטה למעלה בג' מיני בירורי' זה למעלה מזה ע\"י ג' שליטין דלעילא בחי' מוחא ולבא וכבדא ג' כלים לנר\"נ דז\"א שנק' אדם דאצי' כידוע ועולה מלמטה למעל' תחלת הבירור בהעלא' הבהמה ע\"ג המזבח לבחי' נפש העליונה שבבחי' כבדא כו' ומשם עולה בבירור ב' לבחי' לבא בבחי' רוח ומשם לבחי' מוחא כו' ואח\"כ נמשך מלמעלה למטה ממוחא ללבא ומלבא לכבדא כמ\"ש בזוהר וכמו בקרבן נח דכתיב וירח ה' כו' ויאמר אל לבו לא אוסיף עוד להכות כו' וכמ\"ש במ\"א וד\"ל. וכך יובן בענין התפלה שכנגד קרבנות שהוא ג\"כ בחי' הבירורי' דב\"ן דנוג\"ה בחי' בהמה דנה\"ב שיש בזה ג\"כ בחי' התבררות טו\"ר ע\"י אש של מעלה בהתלהבות אש שלמעלה דנה\"א כו' ועולה המובחר והפסולת יורד כו' ובירור זה בבחי' נפש שבדם כו' להיות סור מרע בפ\"מ ואח\"כ בירור ב' בבחי' רוח שבלב"],[2500660180,"באוי\"ר כו' ובירור הג' בבחי' מוחא חב\"ד כו' וכ\"ז מלמטה למעלה מפסד\"ז עד ש\"ע בח\"י ברכאן חוזר ונמשך בחי' ההמשכה מלמעלה למטה ממוחא ללבא כו' והוא בחי' גילוי אלקות בנר\"נ בכלי' שלהם מוחא ולבא כו' באמרו ברוך אתה ה' כו' וע\"כ התפלה בלחש דוקא להיותה בחי' המשכת המוחין החדשים שנמשך ע\"י הברורים מלמעלה למטה (מז\"א לנוקבא ממ\"ה לבחי' ב\"ן כו') שצריך לבוא בחשאי בבחי' ביטול דשם מ\"ה (דבחכמה אתברירו מלמעלה למטה בבחי' ברורים דא\"י) משא\"כ בברורים דא\"ח מלמטה למעלה הוא בקול רם כמו בפסד\"ז וכה\"ג וכו' (וכמ\"ש במ\"א בענין משל לבת מלך שהריחה ציקי קדירה שהוא בחי' המל' שמבררת בירורים דב\"ן שנפלו למטה שהן בבחי' ריח ציקי קדירה ושרשם יותר עליון בבחי' התוהו כו' תאמר יש לה גנאי מצד יניקות החיצונים בנוג\"ה כו' לא תאמר יש לה צער מהעדר העונג שיש בבירורי' וכו' הביאו לה עבדי\"ה בחשאי שהוא בש\"ע ע\"י הצדיקים עובדי אלקים כו' שמבררים לבחי' ב\"ן וממשיכים למל' המשכות מוחין חדשים מהברורים שבציקי קדירה בח\"י ברכאן דצלותא בחשאי דוקא וד\"ל) וזהו שורש ענין התפלה ג\"כ בח\"י ברכאן שהן בבחי' ח\"י חוליות כנ\"ל להיות שעיקר הברכות בש\"ע הוא בכריעה והשתחוואה כשכורע בברוך שכריעה זו בראש הרי נמשך מלמעלה למטה בדוגמא לאדם העליון שהוא הקב\"ה כשמתפלל כו' ונמשך לבחי' שם הוי' זה בהשתחוואה זו מעצמות המאציל באמרו ברוך אתה להוי\"ה כו' וכידוע דלכל שם הוי\"ה שבכל ברכה יש כוונה מיוחדת כמו בשם הוי\"ה שבהשיבנו להמשיך התעוררות תשובה בניצוצות אלקות שבכל או\"א הוא בניקוד ציר\"י דוקא ובשם הוי\"ה בסליחת עונות ורפואה הוא בניקוד סגו\"ל שהוא בבחי' הת\"ת שהוא בחי' הרחמים כמ\"ש הסולח לכל עוניכי הרופא לכל תחלואיכי כו' דהא בהא תליא כידוע שהמתקת גבורות קשות דרע דנוג\"ה שבעונות הוא עצמו הרפואה לנה\"א כרפואה שנעשים מסממנים שנהפך לסם חיי' כו' וכך"],[2500660181,"בשם הוי\"ה דברך עלינו בחסד לפרנסה וכה\"ג בכל ח\"י ברכות לבד ג' ראשונות שהוא בחי' חג\"ת שבכתר שמשם נמשך שורש הברכות הללו בבחי' תוס' מוחין חדשים כו' והוא במ\"ש האל הגדול כו' וכמ\"ש במ\"א וכל המשכות הללו באין ונמשכים לחבר המוחין שבראש לכללות כל האברים שנאחזים במוחא ולבא וכבדא ע\"י ח\"י חוליות דוקא שמחברים הראש והרגל כא' אחר שהולך ונמשך ממוחא ללבא כו' (וזהו ענין כהנים אוכלין ובעלים מתכפרין כו' שאחר כפרת שבקרבן ע\"ג המזבח בהקרבת חלב ודם דהיינו גם לאחר ההמשכה דג' שליטים מוחא ולבא כו' מלמעלה למטה וכמ\"ש במ\"א באריכות בהפרש שבין בחי' אכילת אדם לאכילת מזבח כמ\"ש האכל יאכל בב' אכילות כו' וכמ\"ש ואכלתם אכול בירור אחר בירור כו' והוא ענין המשכות ח\"י חוליות אחר העלאה דקרבנות בבחי' לחמי לאישי כו') ונמצא דשניהם אמת דהתפלה במקום קרבן ושורשה בח\"י חוליות כדוגמא שהקב\"ה מתפלל כו' וד\"ל:\n(לד) <b>ובו</b> תדבקון הנה אחר ואותו תעבודו בח\"י ברכאן דצלותא אמר ובו תדבקון שהוא סוד נפילת אפים שאחר ש\"ע שהוא למעלה מבחי' הביטול במציאות דש\"ע וגם למעלה ממס\"נ שבק\"ש כי הנה בח\"י ברכות דש\"ע אין הנשמה אלקית רק בבחי' ביטול במציאות שהוא רק בחי' כלי מוכן ע\"י זה הביטול האמיתי להכיל ולקבל גילוי אור הוי\"ה דאדם העליון הנמשך בח\"י חוליות בבחי' השתחוואה שלו כענין הקב\"ה מתפלל כו' ובצלם אלקים עשה לאדם התחתון הנה בכריעתו מקבל בנפשו הארת אי\"ן דהוי\"ה אחר בירור נר\"נ שבמוחא ולבא בשני אופנים דא\"ח וא\"י כנ\"ל אבל אין זה דביקות והתכללות אמיתית לאשתאבא בגופא דמלכא ממש כמו בנפילת אפים שעל זה אמר ובו תדבקון ממש וכמ\"ש אליך ה' נפשי אשא ממש וכמ\"ש רשב\"י בחד קטירא אתקטרנא כו' וע\"כ היה פטור מן התפלה וכן כל מי שתורתו אומנתו כו' וד\"ל. ולהבין שורש ענין ההפרש בין דביקות האמיתי דנפ\"א ובין ש\"ע וק\"ש שהוא ג\"כ במס\"נ וביטול במציאות"],[2500660182,"ממש הנה יש להקדים מ\"ש במ\"א ע\"פ והאיש משתאה לה מחריש כו' דכפל לומר משתאה וגם מחריש שזהו ענין ש\"ע ונפ\"א משתאה בש\"ע ומחריש בנפ\"א כו' להיות כי הפי' דמשתאה ל' שממון כמו אשתומם כשעה חדא והוא בחי' ביטול במציאות ממש שהופשט לגמרי מכל וכל ממעמדו ומצבו הראשון ולא נשאר לגמרי בו בחי' מהות דבר מה כמו כאשר אשתומם בשכלו ודעתו שאין דעתו עליו לגמרי ולא יכול לכוין דבריו כלל וכלל מעוצם ההשתוממות כשממון במדבר שאין בו כלום אך עדיין אין זה רק ביטול עצמותו לגמרי אבל לא נתדבק עדיין במהות האור העליון הימנו רק שבטל מעצמותו לבד כמו עד\"מ הידוע מאיש בן כפר שלא ראה נימוסי הוד גדולת מלכות שכשרואה יוצא מדעתו ומתבלבל לגמרי עד שלא נשאר בו כח לעמוד ועכ\"ז אין זה רק ביטול עצמותו לגמרי עדיין אבל לא השיג מאומה ממש במהות ועצמות הנימוסי מלוכה ואוצרות כלי יקר וכל גדולת המלך כי רק מפני קטנותו בערך בעבודת האדמה בכלי המחרישה כו' דבר גדולה זאת עליון ביותר מערכו ולא יכילנו ע\"כ יתבטל ממציאותו הראשון אמנם אח\"כ דוקא ישוב אל דעתו להשיג במהות ועצמות מעלת וגדולת העושר והכבוד וכל הון יקר תפארת מלכות בכל פרטיהם אז כלה אור נפשו אליהם ויתדבק בדיבוק עצמו בלי יוכל להפרד נפשו ולא תשבע עינו כו' עד שכלתה נפשו ממש וכו' ונמצא יש ביטול שני אחר הראשון שביטול הראשון לא היה רק בבחי' הפשטת כל עצמותו ומקומו שניזוז ממנו לגמרי ועדיין לא קרב בנפשו בזה כלל למהות ועצם גדולת המלך רק אח\"כ כאשר תשוב רוחו אליו להתבונן במהותו יתבטל שם ביטול עצמו בדיבוק תמידי זהו עיקר הביטול שבטל ונכלל בעליון הימנו ממש והיו לאחדים בלי ימצא במהות בפ\"ע משא\"כ בביטול ראשון שנתבטל רק מעצמותו לא נכלל עדיין בעליון וממילא הוא בבחי' מהות נפרד רק שהוא בביטול כו' וד\"ל. ובאופן אחר יובן זה בדוגמא קרובה יותר והוא מהשתוממות השכל דמשפיע כשמקשה התלמיד וסותרו לגמרי כמו"],[2500660183,"אשתומם כשעה כו' הנזכר בגמרא שזהו ביטול עצמותו של שכל הראשון לגמרי ועדיין לא בא להמצאת אור שכל עליון יותר כלל רק שנתבטל מהשגת שכל הראשון בלבד אבל אח\"כ ישוב לו המשכה חדשה ממקור השכל ענין סברא ושכל עליון יותר ויבוטל בו ביטול ודיבוק אמיתי שלא כביטול הראשון שאינו רק ביטול השכל ולא ביטול ודיבוק בשכל עליון יותר כלל שנקרא ביטול והתכללות בעליון מלבד ביטול עצמו הראשון כו' וד\"ל. וכה\"ג ממש וכדוגמא זו בכל עלול שעולה לגבי עילתו יש ב' מיני ביטול הללו א' הפשטת עצמו בתחלה והב' ביטולו והתכללותו בעילתו ממש והיותר דמיון אמיתי לכ\"ז הוא כמו רקבון הגרעין דחטה בארץ שהופשט מגשמיותו דוקא עד שהיה לעפר ממש דהיינו ביטול כח הצומח שבו ואחר כך יעלה ויבטל בכח הצומח שבארץ ויוכלל בו ממש ואז יוכל להמשיך כח הצמיחה בו מחדש בתוס' מרובה כו' וד\"ל. והנה מג' משלים אלו מובן עכ\"פ שביטול הראשון מישות העלול הוא הגורם להיות ביטול הב' שהוא עלייתו והתכללותו בעילתו ממש וכך יובן בכל עליות העולמו' כמו הנשמות ומלאכים מידי חודש ושבת כידוע הנה אמר בס' הבהיר שיש עמוד בין ג\"ע התחתון לעליון שתחלה מתבטלים בעמוד זה בבחי' הפשטת ישותם שבג\"ע התחתון ואח\"כ עולי' בביטול והתכללות במדרגה דג\"ע העליון ואם לא העמוד שמתבטלים מעצמותם הראשון לא היו יכולים ליכלל ולהתכלל באור דג\"ע העליון כו' (וכך הוא גם בעלית הנשמות לגן עדן התחתון ע\"י נהר דינור שטובלין בו תחלה שמפשיט גשמיותם הראשון לגמרי מכל וכל כו' וכן מצינו במלאכי' שיורדי' למט' ועולין אח\"כ שצריכים לבוא תחלה בנהר דינור זה לבטל חיזו דהאי עלמא שנתלבשו בהגשמה וכן הנפש בעלותה לג\"ע תחלה תטבול בנה\"ד לבטל כל הרהורים דמח' ודבור כו' וכל אשר נתגשמה במדות ושכל ורצון בדברים גשמיי' ואז תוכל לעלות לג\"ע וליכלל באור זיו השכינה שבג\"ע כו' וכן גם המלאכי' שיוצאי' בשיר מכלי הגבלתם בחומר גופם"],[2500660184,"שהוא מרוח ואש ממוזג כו') ואח\"כ מתכללי' בשיר שני שהוא עלייתם והתכללותם במקור חוצבם ברוח אלקים ממש וכמ\"ש והיה מידי חודש כו' יבא כל בשר להשתחוות פי' השתחוואה זו היא בחי' ביטול במציאות מעצמות' הראשון בלבד ואח\"כ נכללים ומתאחדים ברוח אלקים מקור חוצבם כענין לאשתאבא בגופא דמלכא ממש שזהו מיכאל כה\"ג מקריב נשמות כו' וד\"ל:\n(לה) <b>ואחר</b> הקדמה זאת יובן ג\"כ בהפרש שבין נפ\"א לש\"ע שז\"ש משתאה לה מחריש כנ\"ל דבש\"ע הוא בחי' ההשתחוא' וביטול במציאות בכריעה כו' כמ\"ש אדני שפתי תפתח כו' וכמ\"ש אין מלה בלשוני רק שפתי אתה תפתח כאדם שבטל מעצמותו לגמרי ואין בו דעת לכוין דבריו כנ\"ל בפי' אשתומם כו' ובזה הביטול עצמותו בתכלית נעשה רק בחי' כלי להכיל בחי' אין האלקי דשם הוי' דאצילו' בנפשו בבחי' גילוי אור וזה עיקר ענין ח\"י ברכאן דח\"י חוליות כו' והוא ע\"י ענין הכריעות והשתחווא' בחי' ביטול עצמו לבד וכנ\"ל במשל ביטול בן כפר כו' וכמשל הב' בביטול השכל או כמשל הג' ברקבון הגרעין כו' שאין זה רק ביטול העלול מעצמותו טרם בואו להתכלל בעילתו ממש אבל ענין נפ\"א הוא בחי' ביטול הב' הנ\"ל שהוא בחי' ההתכללות באצי' ממש וכמ\"ש אליך ה' נפשי אשא אליך ממש דאשתאב בגופא וכענין מיכאל מקריב כו' שאחר ביטול הראשון מעצמו' בעליו' הנשמות דרך העמוד או בנהר דינור כו' כנ\"ל וד\"ל:\n<b>והנה</b> להבין זה בתוס' ביאור הנה לכאור' יש להבין מ\"ש יבוא כל בשר להשתחוו' לפני ה' מדי שבת כו' שזהו בחי' עלי' מבריא' באצי' ממש כידוע וכן בחי' השתחווא' שבש\"ע שהוא ג\"כ באצי' כידוע הרי זה בחי' התכללות באצי' ממש ולא ביטול עצמו בלבד אך הענין הוא דגם שבש\"ע וכן בק\"ש במס\"נ באחד הוא ג\"כ בחי' ביטול והתכללות באור אלקו' ממש לאשתאבא בגופא אבל אין זה רק לפי שעה בלבד והוא במה שנעשה ע\"י בחי' ביטול עצמו בתכלית בחי' כלי ממש לבחי' אי\"ן האלקי"],[2500660185,"באותה רגע (כדמיון אור הנבואה בכלי השגת הנביא בשעה שמתנבא בלבד) אבל הרי אנו רואי' שאין זה מתקיים בתמידית ונצחית כי כאשר התפלה חולפת ועוברת לא נשאר בנפשו רק בחי' רשימו בעלמ' מאור האלקי ממש והוא נעש' בבחי' בריאת יש ודבר מה עכ\"פ הרי גם הביטול עצמו לא היה רק לפי שעה ועוד זאת שגם בשעת התפל' הגם שנפשו בבחי' תכלית הביטול מעצמו עכ\"ז לא שנכללת במהות ועצמות אלקות ממש להיות בבחי' מהות אלקות ממש אלא היא במהות בריאה רק שהיא בתכלית הביטול (ונק' אין של היש שהוא רק בחי' כלי ליש של אין העצמי שמתלבש בו ע\"ד דוגמא מרקבון הגרעין שאי\"ן דכח הצמיחה רוחניות שבחטה נק' אין של גסות החטה שבו יורד אין דכח הצומח עצמו הרוחני ובא בהגשמה בכח הצמיחה זה שבחטה כו' וכן בדם היא הנפש בחי' רוחניות שבדם נעשה כלי לבחי' הגשמת הרוחניות שבנפש ועי\"ז יש להם חיבור וכך הוא בכל חיבור עו\"ע וכו') (ודוגמא לזה ויתהלך חנוך את האלקי' ואיננו פי' ואיננו בבחי' בריאה יש נפרד כי נתעלה גם גופו להיות בבחי' אי\"ן אבל לא שנתבטל שם ממציאותו לגמרי שהרי א' כי לקח אותו כו' וכן אליהו שעלה למרום בגופו כו' וכן משה בהר לחם לא אכל וכה\"ג רק שזהו בבחי' תמידי' כי גופו תמיד בבחי' אי\"ן וכן ר' שמעון ב\"י שא' בחד קטירא אתקטרנא שאינו נפרד לעולם כי בחד קטירא שנתקשרה נפשו קשורה תמיד בלי תפרד לעולם אבל יש ב' דברים עכ\"פ או כמו האבות הן המרכבה בתמידי' דוקא או כמו נוני ימא שהמים בחי' עצמיותם ולא כחיות נפשי שהוא מן האויר כו' וכמ\"ש במ\"א בענין נשמת רה\"מ סבא) אבל ענין נפ\"א יותר גבוה מזה ג\"כ והוא ענין הדביקות וההתכללות באופן שאינו נק' בחי' כלי שהוא בבחי' אי\"ן של היש בלבד אלא נכלל במהות ועצמו' אלקות להיות בבחי' אי\"ן האלקי ממש והי' כמוהו ומתאחד ומתדבק שם תכלית הדיבוק דהיינו לא לפי שעה כי מאחר שאינו מהות דבר מה בפ\"ע כלל אלא כגוף א' ממש וזהו כענין ביטול הב' הנ\"ל"],[2500660186,"בג' משלים שהוא התכללות העלול במהות עילתו והי' לגוף ומהות א' ממש בלי ניכר שהן ב' דברים כו' וזהו הנק' מס\"נ גמור שבנפ\"א שלמעלה מבחי' עמידה וביטול דש\"ע בהשתחואה כו' הגם שהשתחוואה זו באצי' ממש היינו רק ע\"ד הנ\"ל ככל בריאה שעולה באצי' להיות בבחי' כלי שם ולא שנתבטל שם לגמרי להיות בבחי' אור האצי' ממש אלא כחנוך ואליהו וכה\"ג וד\"ל. ובזה מתורץ ענין הנ\"ל בהשתחווא' שבעליו' הנשמות מבריאה באצי' בשבת שהוא ג\"כ כמו בש\"ע ע\"ד ביטול והתכללות דחנוך ואליהו וכה\"ג משא\"כ לאשתאבא בגופא דמלכא ממש שהוא נעשה במהות אלקות ממש והוא ענין נפ\"א דאליך ה' ממש נפשי אשא והיו לאחדים כמו דיבוק ב' דברים שנתדבקו להיות במהות וגוף א' ממש כנ\"ל וד\"ל:\n(לו) <b>ולהבין</b> כ\"ז בתוס' ביאור הנה ידוע שפי' האמיתי בענין הדביקות הוא כמו התדבקות גוף בגוף והיה לגוף אחד ממש כמו ותדבק נפשו כו' וכן ודבק באשתו והיו לבשר אחד שענינו ב' גופי' שנתדבקו באופן שא' בלא זולתו רק כחצי גוף כמו שאמרו אשתו כגופו דמיא מצד התולדה שמסתעף מאמצעות כח שניהם כידוע ועיקר ענינו הוא ב' דברים הא' הדיבוק באופן שנעשה גוף ומהות א' ממש בלי ניכר שהי' מעולם ב' דברים מחולקי' והוא מצד תכלית אמיתי' הדיבוק בכל חלקיו והב' מצד תמידות החיבור והיחוד להיותו עצמי כמו זאת הפעם עצם מעצמי ובשר מבשרי ע\"כ אמרו אשתו כגופו דמיא וענינו הוא בבחי' היחוד התמידי שלא נפרדו זה מזה לעולם ויש כאן ב' מעלות ולכך נק' דביקות כמו שקורין לדבר המדבק ב' דברים נפרדי' בשם דבק דהנה ידוע בתועלת זה הנק' דבק הוא ב' דברים הא' שבטבעו לדבק ב' דברים נפרדי' שיהיו מתאחדים ממש להיות כמו גוף א' ממש ולא יוכר כלל לב' גופי' מחולקי' והב' העיקר בתועלת הדבק הזה הוא להיות החיבור ואחדות זה תמידי דוקא שלא יפרדו זה מזה לעולם וזהו מעיקר מעלת הדבק"],[2500660187,"שאם אינו דבק טוב אין מתקיים בנצחיות כ\"כ ויוכלו להפרד במשך הזמן או מאיזה סיבה המפרדת וכו' וכ\"ז דמיון להבין לבחי' דבק ברוחניות כמו דיבוק ב' נפשות שמתאחדים ממש שיש בזה ב' מעלות הנ\"ל א' עצם הדיבוק שיהיו כמהות א' ממש כמו אהבת דוד ויהונתן דאהבת נפשו אהבו כו' והב' שלא יפרדו כמו שאול ויהונתן בחייהם ובמותם לא נפרדו כו' והא בהא תליא דאם עצם הדיבוק טוב לתכלית ההתאחדו' ממילא לא יפרדו לעולם כו' והדוגמא מזה יובן בדביקות דכנ\"י בעצמות אלקות דכתיב כאשר ידבק איש אזור במתניו כן כו' ומלמט' למעלה בבחי' דביקות דכנ\"י אמר ובו תדבקון שיש בזה ב' דברים הנ\"ל הדיבוק למהות א' ושלא יפרדו לעולם והענין הוא בבחי' מס\"נ דנפ\"א דוקא במ\"ש אליך ה' נפשי אשא שזהו אמיתית ההתכללות וההתבטלות בעצמות אלקות מבלי שיהי' במהות בפ\"ע כלל רק במהות אלקות ממש (וכמ\"ש במ\"א בפי' יפה את רעיתי כתרצה כו' שאינו כמו בטל רצונך מפני רצונו שאין ההתקשרות רק ברצון ולא בעצם וגם זאת ב' דברים הן אלא שמבטל רצונו כו' משא\"כ כתרצה שרצון א' להם ממש דמה שזה רוצה זה רוצה כאיש א' שרצונו א' ממש כו' והיינו לב א' לאביו שבשמים כו' וד\"ל) והוא מצד עוצם חוזק ההתדבקות כמשל הדבק הטוב הנ\"ל שמדבק בכי טוב עד שנעשה מהות א' כו' כנ\"ל ואמנם עיקר הוראה על טוב הדבק הוא מה שמתקיים החיבור לעולם ולא יפרד מכל סיבה כו' וגם כאן בדביקות דכנ\"י כמ\"ש ובו תדבקון כנ\"ל עיקר ההוראה והמופת על עצם הדיבוק הטוב כנ\"ל הוא במה שיתקיים היחוד וחיבור בתמידי' ונצחי' בלי יפרדו לעולם מכל סיבה שבעולם כו' והענין הוא מה שאנו מוצאים שגם אם יתפלל במס\"נ ותדבק נפש האדם באלקות בהתכללות אמיתי' לפרקים בכל עת מצוא יוכל להיות שבירידתו ונפילתו בהבלי עולם בהתקשרות עצמיות ג\"כ בכל עצם הדיבוק בהיפוך מן הקדושה אז ממילא ינתק חבלי עבותות דביקותו באלקו' ויפרד מעט מעט כו' מצד הרצון הזר שנקשר בו ג\"כ בתכלית הדיבוק כמו בהתקשרות כל"],[2500660188,"נפשו בפרנסתו או כבוד וגדולה ושארי חמדת עוה\"ז שנדבקה נפשו ממש בהן מפרידין אותו מעט מעט מעצם דביקות נפשו באלקות וזהו סימן גמור שלא היה דבק טוב בנפשו באלקו' שאם היה דבק טוב לא הי' מתפרד לעולם וראיה לזה ממה שמצינו שבדבק הטוב באלקות גם אם יעסוק במו\"מ ובטרדות עמוקות בפיזור כל נפשו בקירוב ודיבוק גדול לחיצוני' לא יפרידוהו כלל וכלל מעצם דביקות נפשו באלקו' אפי' כמלא נימא מפני שמתדבק בכי טוב שלא יוכל להפרד לעולם מכל סיבה המפריד וכמ\"ש גם כי אלך בגיא צלמות לא אירא רע כי אתה עמדי והוא כמו בחי' יחידה שבנפש שע\"ז אמר מיד כלב יחידתי דאע\"ג דאזיל הכא והכא בהיכלות דנוג\"ה כו' דיוקני אשתאר בך ממש בדבק עצמי כו' (וכמ\"ש במ\"א ביוסף שעשה מלאכתו בכתיבת חושבנא והיה מרכבה בבחי' האצי' ממש ולא היה נפרד כלל גם בעוסקו בתכלית עומק נפשו בכתיב' כו') משא\"כ בדביקות דש\"ע שאינו כל כך בבחי' התכללות אמיתות כנ\"ל ע\"כ בירידתו למטה אחר התפל' יפרד מעט מעט כו' וזהו יתרון מעלת בחי' נפילת אפים על ש\"ע וק\"ש שע\"ז אמר ובו תדבקון בו ממש וד\"ל:\n(לז) <b>אך</b> עדיין יש להבין בעיקר יתרון מעלת הדביקות דנפ\"א למה גבוה יותר ממס\"נ דק\"ש דבכל נפשך אפי' נוטל את נפשך ממש וכ\"ש בבכל מאודך כו' ומאחר שהוא מוסר לכל נפשו ממש באחד מהו ההפרש במס\"נ לחלק בה ביתרון מעלת הדביקות וההתכללות כו' וכן בש\"ע בביטול במציאות אחר שנתבטל מעצמו לגמרי ה\"ז כמס\"נ בפועל שלא יתכן לחלק בזה חילוקי מדרגות כו'. אך הנה הענין הוא כידוע שיש ב' מיני מס\"נ הא' מס\"נ בכח ולא בפו\"מ והב' מס\"נ בפ\"מ כי' הרוגי מלוכה וכה\"ג ולזה היה ר\"ע מצטער מתי יבוא לידי ואקיימנו. ובאור הדברים הנה לכאורה י\"ל מ\"ש ר\"ע מתי יבוא לידי כו' וכי היה מסופק בנפשו בענין מס\"נ על קדה\"ש דודאי היה בהשגתו באחד בעומק נפשו וכל לבבו במס\"נ באחדו' פשוט לתכלי' האמת בלי שום טעות בעצמו ואיך היה מסופק בזה עד"],[2500660189,"שהיה מצטער על זה ומצפה לבוא לאמיתית הדבר ע\"י הקיום בפ\"מ דוקא ובלא קיום בפ\"מ הגם שהכין כל נפשו במס\"נ באמרו בכל נפשך אפי' נוטל את נפשך לא היה מאמין בעצמו עדיין שהוא לתכלי' האמת כו' אך הענין שיש הפרש גדול בין מס\"נ בכח למס\"נ בפ\"מ וענין מס\"נ בכח יש בו ג\"כ ב' מדרגות הא' כאשר יתפעל בעומק נקודת הלב עד שתכלה נפשו ממש כמו כלתה נפשי כו' מעוצם תגבורת כח התענוג האלקי שבנפש עד כלותה ממש (כמ\"ש בס' אוה\"ח בחי' עריבות מתיקו' ידידו' עד כלו' נפשו וכו') כל זה הוא רק מצד הנפש האלקי' שתכלה למקור חוצבה כהתכללו' הנר בפני האבוקה וכה\"ג ואף ע\"פ שבואהבת מדבר במס\"נ הטבעי' ג\"כ כמ\"ש אפי' נוטל את נפשך היינו רק בכח דהיינו שבשעה זו שהנשמה האלקי' כלתה בעונג האלקי תתפעל גם הנה\"ט לצאת מנרתק חומר חיי הגוף ולמאוס ממש בחייו כו' אבל אין זה רק בכח והעלם ולא בבחי' פנימי' ותוך תוכה ממש שיוכל להיו' שאם היה באותה רגע ממש תובעים אותה להמיר וכה\"ג וא\"ל חרב בצוארו מיד אפשר היה מסתפק ומתיישב בדבר כי בא לידי מעשה הריגה בפ\"מ ועדיין לא עשה כ\"כ ההכנה בהתפעלו' הנה\"ט להיות מוסר גופו להריגה בפ\"מ וזהו ההפרש בין בכח לבפועל בכלל כידוע. אמנם יוכל להיות מדרגה ב' במס\"נ בכח דהיינו שעשה חוזק ועומק ההתפעלות דנה\"ט לצאת מחומר גופה עד שמוכן בנפשו ממש לבוא לידי הריגה בפ\"מ על קידוש השם כשיתבעוהו באות' רגע מ\"מ אין זה רק בכח עדיין שהרי עדיין אין תובעים אותו להריגה בפ\"מ רק שמשער בנפשו שאם היו תובעים אותו היו מוסר נפשו וגופו בפ\"מ וזהו שאמרו אפי' נוטל את נפשך שזהו השיעור שמשער בעצמו עדיין בכח מה שיהיה בפועל כשיטלו נפשו יהיה מוכן לזה וגם בזה עדיין היה ר\"ע מסופק בנפשו שגם שהכנה זו למס\"נ בפ\"מ אפשר אמת היא לשעתה אבל בבוא הדבר בפועל גמור דהיינו כאשר יתבעוהו וידונו למעשה אפשר היה בטל כח ההכנה הזאת"],[2500660190,"שבנפשו רק עיקר מס\"נ שהיא לפועל ממש אע\"פ שאינו נמסר להריגה ולשריפה עדיין הוא כמו חנניה מישאל ועזריה שאמרו לנבוכדנצר אלהנא יכול לשזבנא כו' והן לא ידיע להוי לך מלכא כו' הרי קבלו עליהם השריפה בפ\"מ גם שלא יצילם ה' זהו ההכנה בנפש שהיא אמיתית למס\"נ שבפ\"מ וה\"ז ממש כאלו מסרו נפשם בפ\"מ באופן שאם היה בטל הגזירה ולא היו משליכים אותו לכבשן האש קיימו בזאת ההכנה המוחלטת מצות קידוש השם בפ\"מ אחר שלא היה חסר רק המעשה בפ\"מ ומצידם לא היה שום מניעה וכו' אך באמת גם זה עדיין לא נק' מס\"נ בפ\"מ כמו כאשר כבר הוכנו גופם בפ\"מ כמו בכפיתת העבותים בידם ורגלם ונתינה ע\"ג עצי המערכה כעקידת יצחק זהו כמו מס\"נ בפ\"מ אע\"פ שהחזירם מיד קיימו מצות קידוש השם בהכנה בפ\"מ שבגופם וכעקידת יצחק שלא היה חסר רק המעשה ופרחה נשמתו מאימת מות בפ\"מ כו' אמנם ר\"ע שהיה מצטער ואמר מתי יבוא לידי ואקיימנו רצונו היה לקיום בפ\"מ דוקא שהוא שריפת או הריגת גופו בפ\"מ ולא ההכנה בגופו לבד שזהו פשט אמרו ואקיימנו ובהכנה בלי הריגה בפ\"מ שנשאר חי בגופו הרי לא נמסר גופו על קה\"ש בפ\"מ עכ\"פ ומה שחסר מעשה ההריגה בפ\"מ זהו חסרון העיקר במס\"נ שבגוף וכמ\"ש בזוהר בעשרה הרוגי מלוכה דגופהון אתמסר כו' ובזה דוקא עלו לתכלית העילוי בנשמותיהם עד שאין כל בריה כו' וכמ\"ש בע\"ח דמעלין מ\"ן בשביל כנ\"י עד משיח לפי שמסירת הגוף יותר נעלה ממסה\"נ ויש הפרש בין בכח לבפועל בין בנפש בין בגוף כמו מס\"נ בכח בק\"ש בבחי' כלתה נפשי כנ\"ל ובין בפועל כמיתת נשיקה דמשה ואהרן שכלתה נפשם בפ\"מ בתשוקה נפלאה באח\"פ כו' ויש הפרש בין בכח לבפועל בגוף כנ\"ל בב' מדרגות שבכח שמשער בכח גם על גופו להריגה בפ\"מ עד שמוכן בגופו ממש כשנגמר דינו ויוצא להריגה ומשליכים אותו ולא נשרף ונהרג כי מבטלין גזירתו כנ\"ל ובפועל כשנשרף ונהרג ממש שזהו עיקר מסירת הגוף עם הנפש יחד שאז דוקא נתאמת גם"],[2500660191,"מס\"נ שמצד עצמה גם בפועל ככליון הנשמה מצד התשוקה כו' וראיה לדבר זה שהרי מעלת מס\"נ על קדה\"ש בפ\"מ שנק' קדוש הוא למעלה גם מעליות והתכללות דחנוך ואליהו וכה\"ג הגם שהמה גם בגופם עלו למעלה אבל אין זה כליון הגוף רק הזדככותו בבחי' אין דאצי' אבל ישנו במציאות כו' ויו\"ד הרוגי מלוכה שמסרו גופם כח המעלה מ\"ן עד משיח והסתלקות דחנוך ואליהו הגם שנעשה גופם כמלאך אלקי אין זה כח המעלה מ\"ן כלל כי מטבע רצונם עלו מצד הזדככות וביטול גופם (כמו שאמר אליהו חי ה' אשר עמדתי לפניו דאשתהי בבטן הנוק' יב\"ח שנתקשר שם גם גופו באלקות בתכלית בחי' הביטול כמ\"ש במ\"א והיפוכו הן הנפלים שלא נקלטו ברחם הנוק' כו') ולזה היה ר\"ע מצטער שימסור גופו בפ\"מ על קדה\"ש שלא בהסכם הטבעית דוקא כמו במסרקות של ברזל שהיה קשה לגופו בודאי ביותר ועכ\"ז היה מאריך באחד וקיבל היסורים באהבה גדולה עד שיצאה נשמתו באחד עם גופו כא' דוקא שזהו למעלה הרבה מבחי' מיתת נשיקה דמשה וד\"ל:\n(לח) <b>וזהו</b> עיקר בחי' נפ\"א שע\"ז אמר ובו תדבקון ממש כנ\"ל שלמעלה גם ממס\"נ דבכל נפשך דק\"ש וביטול במציאות דש\"ע כנ\"ל לפי שאמר בזוהר בענין נפ\"א שיהא דמי לי' כמו דאתפטר מהאי עלמא ממש כו'. ובאמת יש להבין במאמר זה האיך יוכל לאמת אמיתית בחי' מס\"נ שבפ\"מ בהריגה ושריפה במה דדמי לי' כמו דאתפטר כו' דמיון זה אינו רק כמו שמשער בנפשו בכח שיהיה מוכן למס\"נ בפ\"מ ע\"כ דמי לי' כמו דאתפטר ממש ואין זה גם בדומה כלל לאמיתי' הפטירה בפ\"מ כנ\"ל שלזה היה ר\"ע מצטער מתי יבא לידי קיום בפ\"מ דוקא אמנם הנה באמת ענין זה דדמי כמו דאתפטר כו' לא קאי לענין לשער בעצמו שיהיה מוכן למס\"נ על קדה\"ש שבזה ודאי הקיום בפ\"מ הוא העיקר כנ\"ל אלא דדמי זה לא שיעור בעצמו הוא אלא דמי ממש כמו דאתפטר מהאי עלמא לגמרי כו' והענין הוא דודאי ע\"י ההשגה בעילוי עד בחי' כלות הנפש אינו רק"],[2500660192,"בנשמה האלקי' ועדיין כל חיות נה\"ט קיימת וגם אם תתפעל הנה\"ט עד כלותה אין זה כליון אמיתי בכל חושי גופו כו' רק כאלו הי' מוכן למסירת גופו כאשר יתבעוהו שאז גופו מוכן ממש ולא חסר רק המעשה כנ\"ל אמנם חושי גופו במהותם ממש הטבעי רק שמוכן לאבדם וזהו הוראה שעוד נפשו בגופו ממש וא\"א לומר בזה דאתפטר ממש ולא כמו דאתפטר כו' רק כאשר נפל עליו אימת מות שבפ\"מ כעקידת יצחק וכה\"ג כאשר כפות ומונח על העץ כו' שפרחה נשמתו ממש ואין נפשו בו כלל רק בחי' רשימו וקיסטא דחיות' בלבד במה שיוכל לחזור נפשו אליו מיד שיחזרוהו כו' כ\"ז וכיוצא בו יוכל להיות בהפשטת חיות חומר גופו מצד עצמו ורצונו הטבעי כאלו אתפטר ממש ולא נשאר בו רק רשימו וקיסטא דחיות' כו' ואין זה דמיון בכח המדמה בלבד אלא הוא אמיתי' בהיות שכאשר בחי' יחידה שבנפשו עולה למעלה כמ\"ש כי רוח האדם עולה כו' יש בכחה לעלות כל חלקי הנפש הטבעי' עד שלא ישאר רק בחי' רשימו כו' ולא נחשב כמת ממש אלא כנרדם בתכלי' התרדמה וכמו שסיפרו בצדיקי' המופלגי' שבדור כמו הבעש\"ט ז\"ל כשהיה לו עליית הנשמה כו' הי' מופשט מכל הגשמת חיי חומריות גופו כמו המתעלף ממש והוא בחי' תוקף התרדמה (וכמו ויפל כו' תרדמה כו') אשר לא ירגיש כל כאב והכאה שהרי לקח אחת מצלעותיו כו' ולא הרגיש כלל וזהו למעלה מהפשטת חומר גופם שבנביאים בשעת הנבואה שאין שם כליון כלל אלא אדרבה שלימים בכל חושי גופם רק בלתי נרגשים מפני שנזדככו לקבלת האור האלקי וממילא נתבטל חומר הגסות כו' וכמ\"ש ביד הנביאים אדמה (וכמ\"ש בשער הנבואה) ואין זה רק מצד בחי' יחידה שבנשמה שכלולה ודבוקה ממש בגופא דמלכא במהות האלקי ממש כנ\"ל (בפרק לו) בענין הדבק כו' ע\"כ יוכל להיות בנפ\"א בכל ניצוץ מישראל שיהיה בנפשו כאלו אתפטר מהאי עלמא ממש ולא נשאר בו רק רשימו כו' דהיינו כמו שהנשמה לאחר פטירתה שצרורה בצרור החיים ממש וגם שעוד נפשו בגופו יוכל להיות בעצמו כמו"],[2500660193,"דאתפטר כבר מהאי עלמא שלמעלה גם מהכנת הפטירה כשבאה לידי פ\"מ שמורגש עכ\"פ בחושיו ולמעלה ג\"כ מבחי' מיתת נשיקה שמצד הנשמה בלבד הגם שחושי גופו כלין בע\"כ כי אינה רק כהילוך הניצוץ אל השלהבת ולא כמו דכבר אתפטר כו' שנשמתו צרורה בצרור החיים במהו' א' ממש בלי חילוק ב' גופי' מחולקים כלל כנ\"ל וד\"ל. והנה כמו שמבואר למעלה (בפרק לו) בטעם יתרון מעלה שבדבק שלא יפרד לעולם גם בהיותו ברצון זר בגיא צלמות כו' דיוקני אשתאר בך כו' כך אמר בנפ\"א ובו תדבקון שכל חשך הקליפות דנוגה דעשיה אינם מסתירים לו כלל וכלל לפי שגם כח גופו הופשט ועלה עם הנשמה בבחי' הדביקות והתכללות הזאת האמיתית ואין חומר הגוף מסתיר אחר שגם הוא בהתכללות זאת ממש (שלמעלה מעליות הגופים דחנוך ואליהו שהם בבחי' מציאות בפ\"ע רק שנזדכך בבחי' אי\"ן כו' כנ\"ל) ובחי' ומדרגה כזו יהיה לע\"ל בבחי' אור ישר והוא בימות המשיח ותחיית המתים שיחיו הגופים החומריים מחיי אור האלקי ממש והיו לאחדים ממש כמאמ' עוה\"ב אין בו אכילה כו' אלא ניזונין בגופם מזיו השכינה ממש שהוא למעלה הרבה מאור האלקי בגופם דאליהו וחנוך למעלה שהן רק כמלאכי' כו' וזהו הטעם שאמרו בס' הקבלה שבשעת נפ\"א הוא זמן עיקר בירור והעלאת דרע דנוג\"ה שבגופו ובשרש כנ\"י למעלה הוא בחי' מל' דבנפ\"א מלקטא כו' עד שהוא כדוגמא דלע\"ל שיבוער הרע מכל וכל וז\"ש ובו תדבקון לשון עתיד דקאי בימות המשיח ועכשיו יש הארה מאין זה בכל נפ\"א שבכל א' וא' מישראל מצד שרש נשמתו למעלה שהוא הנק' בחי' יחידה מטעם הנ\"ל (והיינו ויט עד איש עדולמי כו' שהוא בחי' המל' שנק' יהודה הפעם אודה בבחי' ביטול ובנפ\"א הוא בהתכללות כמאן דאתפטר כו' שאז דווק' יורד למטה מטה לפי שאז דוקא עיקר הבירור גם מעומק היכלות דנוגה שנק' איש עדולמי כו' כמ\"ש בלק\"ת):\n(לט) <b>והנה</b> לכאורה יש להבין במ\"ש ובו תדבקון בנו\"ן פשוטה דוקא אשר בכל מה שהזכיר קודם כמו"],[2500660194,"תלכו ותיראו ותשמעו ותעבודו לא אמר בנו\"ן פשוטה לומר תלכון או תשמעון וכה\"ג רק בתדבקון א' בנו\"ן פשוטה ולמה שינה במצות הדביקות דוקא. אך הנה מבואר למעלה באות א' דיש ב' מיני שמאל אחד שמאלו תחת ראשי והב' שמאלו תחת לראשי והוא בחי' שמאל דוחה דמקבל ושמאל דוחה דמשפיע כנ\"ל וכמ\"כ יש ב' פעמים ימין ימינו תחבקני שלאחר שמאל דוחה דמקבל ובחי' ימינו תחבקני שלאחר שמאל דוחה דמשפיע שהוא מ\"ש שמאלו תחת לראשי וימינו כו' וזהו ענין ב\"פ ימין שנז' בפסוק ימינך ה' נאדרי בכח ימינך ה' תרעץ אויב ותרעץ להבא משמע כידוע. ויובן כל זה ע\"פ כל הנ\"ל בענין ההפרש שבין ש\"ע ונפ\"א בהיות שלכאורה יש להבין בכל הנ\"ל דבנפ\"א הוא עיקר הדביקות האמיתי ולא בש\"ע והלא ידוע דעיקר היחוד פב\"פ הוא דוקא בעמידה דש\"ע בח\"י ברכאן כו' וכמ\"ש בזוהר בטעם צלותא בלחש דלא לארמא קלא כיון דאתתא אתיהיבית בין תרין דרועין לא צריך לארמא כו' ולפי הנ\"ל אין בש\"ע רק בחי' השתחוואה שהוא רק בחי' כלי לקבל כו' ולא שנעשה מהות א' כמו בנפ\"א כו'. ואמנם הנה באמת דבש\"ע הוא בחי' היחוד שהוא החיבור ודביקות דמשפיע ומקבל והיה לאחדים והוא שילוב הוי' באדני כו' שאור שפע דהוי' דז\"א מאיר ומשפיע במל' בבחי' אור זרוע לצדיק ח\"י עלמין שהן ח\"י חוליות כו' והמל' היא כנ\"י בחי' מקבל השפע גילוי אור זה בתוך תוכם ע\"י בחי' הביטול והשתחוואה ובלחש דוקא וכמו ואתם הדבקים בה' אלהיכ' דבקים ממש וכמו רשב\"י שאמר בחד קטירא אתקטרנא כו' וע\"ז נאמר וימינו תחבקני בשעת הקירוב והיחוד שחיבוק זה הוא בחי' או\"מ בימין מקרבת להקיף לכנ\"י שלא יוכלו להפרד כאדם שחובק לחבירו שמחברו אליו ביד חזקה לבלתי יטה ויסוג אחור ממנו ויחוד וחיבוק זה הוכן בק\"ש ברמ\"ח תיבין שבה שהן שרש לרמ\"ח איברים דמלכא כנ\"ל וכידוע דבכל מצוה בפרט ג\"כ יש יחוד קוב\"ה ושכינתיה (שהוא יחוד זו\"נ כידוע) אבל אין זה רק לפי שעה בשעת היחוד בלבד ואח\"כ השיב ימינו אחור כו' ולא יש בחי' חיבוק"],[2500660195,"דאו\"מ בבנ\"י ויוכלו להפרד למטה כו' ועוד זאת שלא יוכל להיות בש\"ע בירור והעלאה דעצם גסות הרע דנוגה כי כדי שלא יפרידו בין הדבקים צריך להיות ביעור וגירוש שרש הקליפו' למטה כדי שלא יקבלו גם הם יניקה מהיחוד האלקי הזה (ולזה מכריזים קודם ש\"ע מאן בעי למחמי יקרא דמלכא כו' ואלקים אחרים לא יחפצו בזה כי לא יחפוץ כסיל בתבונה שהוא בחי' מוחין כו' רק בהתגלות לבו מבחי' חסדים המגולים שרש עה\"ד כו' כמ\"א במ\"ש) אלא צריך להיות בהפשטה בתכלית גם מכל דק שבדקות דרע עד שאו' סלח לנו כי גם מס\"נ דק\"ש כפירוד יחשב לגבי עצמות הרוממות כו' משא\"כ בנפ\"א הנ\"ל שהוא נדבק בדבק טוב בלי נחשב למהות בפ\"ע גם לא בבחי' מקבל וכנ\"ל בפי' דמי לי' כמה דאתפטר כבר מעלמא כו' דכנ\"י אתדבקת בעצמות אלקות להיות במהות א' כנ\"ל אז הוא למעלה מבחי' היחוד וחיבור דדכר ונוק' משפיע ומקבל כו' וע\"כ א' תדבקון בנו\"ן פשוטה דוקא כי בחי' נו\"ן פשוט' מורה בחי' התפשטו' לירידות האור עד למטה מטה ביות' וכידוע בבחי' המ' שנק' נו\"ן כפופה כשמקבלת לעצמה ונק' נו\"ן פשוטה כשמתפשטת למטה והיינו בנפ\"א כאשר אור האלקי יורד עד למטה מטה גם בבחי' גסות דנוגה לברר הניצוצות ולהעלותן ולדבקם למעלה עד רום המעלות וכנ\"ל שאין חומר גופו מסתיר בנפ\"א לפי שגם הוא עולה כו' וע\"ז אמר ובו תדבקון בנו\"ן פשוטה למטה שיוכל הכל לעלות וכדוגמא דלע\"ל שיבוער הרע מכל וכל דלכך א' תדבקון ל' עתיד כנ\"ל להיותו מורה ענין דביקות נצחי בלי יפרד לעולם וזהו לע\"ל דוקא דכתיב וע\"י יתיב כו' מלכותיה מלכות עלם דלא תשתני כו' משא\"כ יחוד דלפי שעה בש\"ע או בשבת ויו\"ט ובכלל הוא בזמן בהמ\"ק לזמן מיוחד ואח\"כ גלות כו' (ובאמת נהפוך הוא דבנפ\"א גם דק שבדקות שמץ דבר רע פוסל ומעכב עצם טוב הדיבוק ויוכל ליפרד בהיות שצריך להתאחד במהות א' וכתיב לא יגורך כו' משא\"כ ביחוד לפי שעה אינו מפריד בין הדבקים כ\"א בחי' גסות ביותר וראיה מענין היחוד"],[2500660196,"בבורסקי כו' וכן מקרא מפורש לא מאסתים כו' להפר בריתי אתם כו' וגם שגלו לאדום שכינה עמהם בתוך טומאותם כו' וכתיב אנכי ארד עמך כו' אנכי ממש וכמ\"ש בכל צרתם לו צר כו') ובזה יובן מה שאשתו של ר\"א בן הורקנוס לא הניחו לנפילת אפים כו' שלא יצדק שם כל חי כו' וגם בהיות שזהו תכלית הירידה לברר בהיכלות דנוגה וכמ\"ש למעלה בענין ויט עד איש עדולמי כו':\n(מ) <b>וזהו</b> ימינך ה' נאדרי בכח כו' ב' פעמים ימין לנגד ב\"פ שמאל שבשמאל דוחה דמקבל ושמאל דוחה דמשפיע שז\"ש שמאלו תחת ראשי ושמאלו תחת לראשי ובשניהם א' וימינו תחבקני והן ב\"פ ימין שא' כאן ימינך ה' נאדרי בכח וימינך ה' תרעץ אויב להבא דוקא וימינך ה' נאדרי בכח עכשיו והענין דעכשיו כל היחודים העליונים הוא במצות מעשיות שהן בבחי' יחוד קוב\"ה ושכינתיה בחי' זו\"נ והן רמ\"ח תיבין דק\"ש כו' כנ\"ל אבל ימינך ה' תרעץ אויב להבא הוא לע\"ל אחר כל הבירורים דרפ\"ח כו' שע\"י המצות אז אמר תרעץ אויב ולכאורה אין זה מובן מאחר שיבוער אז כל הרע מכל וכל למה צריך לימין זה לרעוץ אויב כו' מאחר שלא יהיה אויב ה' המנגד כלל אך הענין הוא דימינך ה' נאדרי בכח הענין הוא תוקף ועוז כח התגברות החסדים דימין על בחי' הגבורות שבקו השמאל כי כח השמאל נכלל בימין והיינו התגברות הימין במה שנוסף בו התכללו' כח השמאל והוא בחי' גבורה שבחסד שאז החסד בעוז ותוקף גדול ביותר משיעור כח עצמו וזהו נאדרי בכח של השמאל כו'. וביאור הדברים להיות שע\"י בחי' שמאל דוחה נמשך בחי' ימין מקרבת וכמו בש\"ע באדני שפתי כו' כי אין מלה בלשוני בתכלית השפלות דשמאל דוחה שבמקבל כנ\"ל עי\"ז נמשך מקור החסדים שבקו הימין והוא במ\"ש אלקי אברהם כו' הגדול כו' שברכה ראשונה הוא במקור החסד דאברהם ומסיים מגן אברהם בחי' מקיף דימין כמשל המגביה משא יותר מכפי כחו המצומצם שבא מצד בחי' המקיף שבהעלם ואמנם רוב עוז ותעצומות כח יתירה במקיף זה להגביה אין זה רק ע\"י"],[2500660197,"בחי' תגבורת דקו השמאל והוא בברכה שניה דאתה גבור לעולם שם אגל\"א שבזה רב להושיע בימין הרבה יותר מכפי כח הימין עצמו לפי שנכלל בו כח קו השמאל דיצחק כענין עקידת יצחק שעי\"ז נתחזק כח החסד דאברהם יותר וע\"כ מכלכל חיים בחסד לבא בכלים מכלים שונים וכמו המזון ששורשו בגבורה שבחסד וזהו שולחן בצפון וכן תח\"ה וגבורות גשמים כו' שיורדים בגבורה שבחסד וזהו מי כמוך בעל גבורות שבחסד לגבור חסדו מפני שנכלל שמאל בימין (וכמ\"ש במ\"א בענין ד' שנכנסו לפרדס שהיה רק כדי להגביר החסדים על הגבורות בשורש הראשון שלהם בבחי' הכת\"ר וזהו ענין יהש\"ר מברך כו') והיינו פי' נאדרי בכח והוא עכשיו כל זמן הגלות ע\"י ק\"ש ושמ\"ע ומצות מעשיות שימין מקרבת אחר שמאל דוחה כו' והוא מ\"ש שמאלו תחת ראשי ולא תחת לראשי כן לפי ערך ימינו תחבקני שז\"ש ימינך נאדרי בכח שהוא לפי ערך התכללות הגבורות דנוקבא בהעלאת מ\"ן כך ערך המשכת מ\"ד ממקור החסדים דדכורא להגביר על הגבורות ולהמתיקן (כמ\"ש במ\"א בענין עיני כל אליך ישברו להמתיקן כו') אבל ימינך ה' תרעץ אויב להבא הוא ימין הב' שלאחר שמאל דוחה דמשפיע בבחי' ביטול המציאות לגמרי כמ\"ש למעלה בענין ואותו תיראו בבחי' שוב שאחר הרצוא כמו ויעמדו מרחוק כו' ואחר שמאל דוחה כזה שעומד מרחוק כמו בזמן הגלות דכתיב הסתר אסתיר פני כו' ומרחוק מאד עומדים כנ\"י רק אעפ\"כ מרחוק זה ה' נראה להם עכשיו בעול מצות בפו\"מ דוקא בהסתר ולבוש שק דנוגה כו' ולע\"ל יהיה בחי' ימין מקרבת שאחר שמאל דוחה זה והוא מ\"ש שלא יכנף עוד מוריך בלבושים וכו' והיו עיניך רואות כו' וראיה זו יהיה ע\"י הזדככות הלבושים דמצות דעכשיו כו' וכל שאינו בהסתר פנים עכשיו בקיום המצות אינו זוכה בגילוי פנים העצמית אשר עין בעין כו' כמ\"ש ואמר ביום ההוא הנה אלקינו זה כו' ואז נאמר ימינך ה' תרעץ אויב כי יש ב' מקיפים א' שמדחה ומגרש החיצונים כמו קומה ה' ויפוצו כו' וכן יתפרדו כו' שלא יהיה בהם קומה שלימה רק"],[2500660198,"יתפרדו ויפוצו כמו עכשיו בשעת היחוד דש\"ע בפב\"פ שנפוצו ויפלו וינוסו כו' אבל לא שנתרוצצו לגמרי באופן שלא יהיה להם תקומה לעולם רק לע\"ל דכתיב תרעץ אויב שהוא ע\"י בחינת מקיף הב' דימין העצמות שכולו ימין וכמ\"ש לית שמאלא בהאי ע\"י משום דלע\"ל כתיב וע\"י יתיב כו' דלא תשתני כלל מצד כח הדין אשר בקו השמאל לעולם שזהו למעלה מהתכללות השמאל בימין וכמ\"ש אך טוב לישראל יום שכולו טוב שכולו ארוך כו' (ואז גם דק שבדקות שברע יפול או כמשרז\"ל ישחוט ליצה\"ר כו' והיינו גם שיורי הז' מלכים הגסים לפי פי' הא' דלעיל) והיינו תרעץ להבא דוקא אחר תשלום הבירורים דרפ\"ח שע\"י המצות שאינו רק להבדיל ולגרש אבל תרעץ לחלקים קטנים שלא יוכלו להבנות לעולם הוא ע\"י ימינו העצמי שאחר שמאלו העצמי שהוא בחי' שמאל דוחה דמקבל בבחי' ביטול העצמות מכל וכל שבא מצד רוממות עצמותו דוקא והיינו כמו ענין תדבקון שבנפ\"א שהוא כדוגמא שיהיה לע\"ל כנ\"ל (בפ' לח) שלזה אמר תדבקון בנו\"ן פשוטה שנו\"ן פשוטה זה תרעץ אויב כמו ימינך ה' הב' שתרעץ אויב והכל א' וד\"ל:\n(מא) <b>ובכל</b> זה יובן מ\"ש אליך ה' כו' בך בטחתי אל אבושה כו' דהנה יש להבין בעיקר ההפרש בין עכשיו לע\"ל שהוא בענין השינוים בעליות וירידות אשר עכשיו תמיד בשינוי מזמן לזמן לפעמים בחי' המל' שורש כנ\"י בהעלאה ולפעמים בירידה ובדרך כלל הרי היה תכלית העילוי בזמן בית המקדש ראשון כמו בימי שלמה וכה\"ג ואחר כך זמן הגלות בירידה עצומה ונקרא סוכת דוד הנופלת ממש כו' וידוע במ\"ש ולאום מלאום יאמץ שכשזה קם זה נופל וכן אמרו לא נתמלאה צור אלא רק מחורבנה של ירושלים דכתיב אמלאה החרבה כו' משום דאת זה לעומת זה עשה כו' וזהו עיקר שמחת אויב מנפילת המנגדו בירידה עצומה דוקא שאז ישמח ביותר שעל זה אמר לא יעלצו אויבי כו' שלעולם לא יהיה ירידת המל' באופן שיעלצו אויבי לפי שאמר בך בטחתי דוקא הענין הוא"],[2500660199,"כידוע בביאור מה שאמר תנו עו\"ז לאלקים שהוא המשכת הכח ועוז לבחי' שם ב\"ן בחי' אלקים לברר ברורים דרפ\"ח שזהו בירידת המל' בגלו' דוקא כידוע בענין עת אשר שלט האדם באדם לרע לו דוקא שעי\"ז יוציאו כל הטוב שנפל בקליפו' כמ\"ש חיל בלע ויקיאנו וכן והוצאתי את בלעו כו' והנה באמת לכאורה אין זה מובן למה צריך לעוז וכח זה הרי בחי' אלקי' הוא המברר מכח עצמו כמ\"ש כהמס דונג כו' כן יאבדו רשעים מפני אלקים כו' וכמו במדבר העמי' דכתיב ויהי בנסוע הארון ויאמר משה קומה ה' ויפוצו אויביך כו' אך הענין הוא כידוע בפי' המאמר האיש דרכו לכבוש ולא האשה כו' דהיינו שבכח הדכר דוקא עיקר הכח לברר בירורים דרפ\"ח שנק' כיבוש מלחמה ולא באשה שהיא בחי' המל' בחי' נוק' והטעם הוא כי מאחר שמבחי' המל' מקבלים גם החיצונים יניקה כמ\"ש ומלכותו בכל משלה וכן מלך אלקים על גוים כו' איך יעשה דבר היפוכו להפריד שרש יניקה זו מהם ומכ\"ש בהיו' אור השפע נמשך להם בבחי' גלו' שלא ברצון פנימי רק להאבידם בזה כמ\"ש כי גחלים אתה חותה כו' ולכך נק' בשם גלות א\"כ איך חבוש יתיר א\"ע כו' רק ע\"י כח ועוז מעליון הימנו שהוא בחי' דכר והוא מ\"ש ה' איש מלחמה שדרכו של איש לכבוש כו' והיינו תנו עוז לאלקים בחי' ב\"ן כו' להיו' שם הוי' הוא למעלה מבחי' התפשטו' השפע לנבראים עדיין כו' (וגם להיו' כי בחכמה אתברירו בבחי' הדעת דדכורא שכולל חו\"ג ולא בדעת דנוק' שאין לה רק עטרה דגבורה והוא מ\"ש נשים דעתן קלה ק\"ל חצי מספר ר\"ס כמ\"ש כי סר לראות יו\"ד הויו\"ת כו') ויובן זה בנפש האלקית שנק' נר ה' דוקא שבכחה לברר לבחי' נוגה דנה\"ב כו' כידוע בפי' עובד אלקים שמברר לבחי' נוגה שמקבל מאלקי' כו' הרי אין זה רק בבחי' דעת דבחי' דכורא ולא בבחי' הנוק' שהוא כמו דו\"ר טבעי' שבה כי אין חבוש מתיר עצמו כו' וכמו שאמרו אשרי איש כשהוא איש כו' (ומה שכנ\"י נק' אשה יראת ה' וכן אמרו בזוהר בכמה דוכתי ע\"פ בזאת יבוא אהרן כו' בבחי' היראה שנק' זאת דוקא"],[2500660200,"והוא יראת חטא שקודמת לחכמתו ונק' שער לה' כו' היינו רק בבחי' ההעלאה למעלה כמ\"ש בזאת יבוא כו' אבל בענין בחי' הירידה למטה לברר בטו\"ר שבע\"ד שם עיקר הבירור בחכמה ודעת ומ\"ש אם אין יראה אין חכמה כו' קאי ביראה שקודמת לחכמתו ומ\"ש הן יראת ה' היא חכמה היינו אם אין חכמה אין יראה וקאי ביראה עילאה כמ\"ש במ\"א) וזהו בך בטחתי (פי' בשם הוי\"ה) בחי' דכר שבכחו לכבוש ולברר כמ\"ש תנו עוז לאלקים אז ודאי לא יעלצו אויבי לי שלא יהיה ירידת המל' שהיא כנ\"י בנפילה וריחוק שמזה יעלצו אויבי כו' אך פי' בטחתי היינו כמו ענין טיח ודיבוק כמו בטוחות חכמה וזהו ג\"כ ענין הבטחון שאינו רק השלכת וביטול כל עצמו באלקו' לבטוח בו לבד ולא בכח עצמו כלל וכלל והוא דוקא בבחי' ומדרגו' דביקות האמיתי דבו תדבקון הנ\"ל בנפ\"א וכה\"ג (אמנם הנה גם בזה יש ב' אופנים הא' עכשיו גם בזמן הגלות שנמשך כח משם הוי\"ה לאלקים כמ\"ש תנו עוז כו' עד שלא יעלצו אויבי מבחי' נפילה כלל וכמ\"ש ימינך ה' נאדרי בכח להגביר על כח הדינין שבקו השמאל כנ\"ל כמ\"ש הושיעה לו ימינו והוא התגברות כח החסד דגבר חסדו דבחי' דכורא דוקא שרובו חסדים) אבל עדיין יש בזה שינוי מזמן לזמן שאין כל הזמנים שוים בזה כנ\"ל משא\"כ ימין הב' דתרעץ אויב לגמרי כמו שיהיה לעתיד לבוא אין בזה שינוי כלל וכמ\"ש לעיל וע\"י יתיב כו' כנ\"ל והיינו בך בטחתי בקיום נצחי כמאמר דוד מלך ישראל חי וקים וכן לעולם ועד כו' ולא יעלצו אויבי לעולם כי לא יהיה להם תקומה עולמית כו' ולכך ל' עתיד אל יעלצו (ובאמת במזמור דלדוד ה' אורי שאו' באלול יש סתירה לזה לכאורה שהרי אמר שם בפי' אם תקום עלי מלחמה בזאת אני בוטח בזאת דוקא דהיינו בחי' היראה דבחי' המל' בחי' נוק' ועוד מצינו יותר שגם בחי' שם הוי\"ה בעלה דמל' בוטח במל' כמ\"ש בטח בה לב בעלה כו' כי נק' עקרת הבית לברר כל הבירורים ולכך נק' אשת חיל כמ\"ש רבות עשו חיל ואת עלית כו' הרי נהפוך הוא שבחי' דכר בוטח בנוק' היפך הפסוק דבך"],[2500660201,"בטחתי או בטח בה' וכה\"ג וכן בזאת דוקא אני בוטח כו' אך הענין הוא דחודש אלול עד יו\"כ עולה המל' בפנימי' ע\"י וכמ\"ש ותרם התיבה כו' וז\"ש אני לדודי ודודי לי ר\"ת אלול ולכך א' ה' אורי כו' והוא כמו שיהיה לע\"ל דכל השלימות של הבירורים יהיה ע\"י בחי' המל' דוקא כמ\"ש א\"ח עט\"ב נקבה תסובב גבר כו' משום דסוף מעשה עולה במחשבה תחלה כו' ע\"כ אמ' לעתיד"],[2500660202,"דוקא בטח בה לב בעלה שלא יצטרך ליתן עוז לאלקים לברר אדרבה יבטח בה' בלבד כו' וכן הוא מ\"ש בזאת אני בוטח בזאת דוקא והוא ג\"כ מ\"ש אחת שאלתי בחי' אחת שעולה למעלה מעלה בפנימי' הכתר כמו שמסיים בצור ירוממני ועתה ירום ראשי על אויבי כו' משום דלע\"ל תקרא ארץ חפץ חפצי בה כו' (וכמ\"ש במ\"א בענין עתידה א\"י שתוציא גלוסקאות וכלי מילת כו' וד\"ל):"],[2500660203,"<h3>ביאור ביסוד ענין התפלה. פדה בשלום. יב\"פ</h3>\n<b></b><b>ביאור ביסוד ענין התפלה שנקרא שעת קרבא מיוסד ע\"פ פדה בשלום</b>\n(א) <b>פדה</b> בשלום נפשי מקרב לי כי ברבים היו עמדי. הנה כתיב כי הנה אויביך ה' כי הנה אויביך יאבדו יתפרדו כל פועלי און הענין הוא על דרך משל שני בני אדם הנלחמים יחד שכ\"א רוצה לנצח לזולתו ולהכניעו תחתיו הנה בהכרח שיתקרבו יחד ויצמדו וידבקו גופם זע\"ז הנקרא התאבקות כמו ויאבק איש עמו בשרו של עשו שנלחם עם יעקב כידוע שנתאבקו ונתקרבו בקירוב ודיבוק גמור והגם שבודאי כל הנלחמים המה ב' הפכים בתכלית וא\"ל לא היו נלחמים כלל וכל ב' ההפכים בטבעם וודאי יש ריחוק עצום תמיד ביניהם לא יוכלו להתקרב יחד לעולם כמו שלא יוכלו אש ומים להתחבר יחד אך כשרוצים להלחם לנצח זה את זה הנה אז בהכרח שיתחברו ויתקרבו להתאבק זה עם זה בתכלית היחוד והדיבוק זה בזה ואמנם אין קירוב ודיבוק זה אמיתי מצד עצמו כי אדרבה הרי היו רחוקים ומפורדים זה מזה בתכלית כי ב' הפכים המה לגמרי רק למען המלחמה והניצוח שרוצה כ\"א לנצח לזולתו מכריח זה הדיבוק והחיבור הנקרא התאבקות כנ\"ל ויהיה איך שיהיה על כל פנים הרי באו לכלל בחי' דיבוק וחיבור בשעה זאת שנלחמים יחד והנה וודאי מובן ממילא שכמו שזה הדיבוק הוא בגשמיות גופם החומרי שנדבקו ב' גופים יחד כך הוא בבחי' רוחניות של נפשם שנדבקו ונתאבקו ב' הנפשות זע\"ז ואדרבא העיקר של הדיבוק וההתאבקות הזאת הוא בבחי' הנפשות שלהם דווקא כי הנפש הוא"],[2500660204,"העיקר וממילא בא סיבת הדיבוק בגופים שלהם כידוע ולפ\"ז וודאי יש תערובות אור החיות של נפשותם בעת האבקם יחד דהיינו מפני שכ\"א רוצה לנצח לאור וחיות נפש חבירו ולהכניע אל נפשו שתוכלל בו ולא תהי' בחי' יש ודבר בפ\"ע לנגד נפשו כלל ולזאת מתאבקים יחד גם בגופם להפיל לזולתו ולהכניעו אליו דהיינו שיוכלל בו דוקא ולא יוכל להרים ראש בבחי' יש ודבר בפ\"ע לעולם וכמו אש ומים שנלחמים יחד שבהתגברות האש על המים יהפוך האש כל טבע המים להיות כלול בטבע האש והוא כמו רתיחת המים שע\"י האש כשיגבר עליו האש עד שיוציא כל לחלוחית שבמים עד שיכלה לגמרי וכמו באש ה' שליחכו לכל המים שיצק אליהו על העצים כו' וכן להיפוך כשיגברו המים על האש יהפכו כל טבע האש ליכלל בטבע המים לגמרי כמו המים שמכבים האש לצנן אותו להוציא כל כח טבעו עד שיכלה לגמרי ויוכלל בטבע המים כידוע בס' הטבע בפרטי ההתכללות של ד' היסודות זב\"ז בדרך מלחמה וניצוח שזהו דוקא ע\"י קירוב ודיבוק זע\"ז וכל שיהיה הדיבוק והקירוב של ב' הפכים יותר יותר יוכל הא' לנצח לעשות התכללות זולתו בו וא\"ל ישארו מופרדים זה מזה וכ\"א נשאר במהותו וטבעו ולא נכלל בזולתו כלל וזהו ג\"כ טעם בחי' ההתאבקות של ב' אנשים בנפשם וגופם בהלחם יחד כדי שיוכל אחד לנצח לזולתו שיוכלל בו וא\"ל כ\"א נשאר בעמדו כמו שהי' ואין א' נכלל בזולתו כלל אלא המה ב' הפכים מנגדים כמקדם (ונמצא מובן עכ\"פ"],[2500660205,"שעיקר המכוון מן המלחמה באיבוק וקירוב זה הוא בחי' ההתכללות זב\"ז שזהו בחי' היחוד היפוך בחי' הפירוד שהי' ביניהם קודם ולזה הטעם צריכין לבא לבחי' ההתאבקות כנ\"ל) וכמו שאנו רואים במלחמות המלכים שעיקר גמר הניצוח הוא כשמתקרבים זע\"ז כו' כידוע והנמשל מכ\"ז יובן ג\"כ בענין מלחמת ב' הנפשות נפש אלקית ונפש הבהמית כידוע בענין ולאום מלאום יאמץ שכאשר זה קם זה נופל כו' שזה הי' בחי' המלחמה הכללי דיעקב עם שרו של עשו שהוא בחי' מדות דקדושות עם בחי' מדות דקליפ' כמ\"ש במ\"א על פסוק ויאבק איש עמו כו' וד\"ל. דהנה ידוע שטבע ב' הנפשות הללו המה ב' הפכים מנגדים לגמרי כמ\"ש כי רוח האדם הוא העולה כו' ורוח הבהמה יורדת למטה כו' ה\"ז עולה למעלה ברום המעלות בדביקות והתקשרות באלקים חיים מקור חוצבה כי הוא חלק אלוה כו' כמ\"ש כי חלק הוי' כו' וטבע של רוח הבהמה לירד ולדבק למטה מטה בגופניות וחומריות התאוות הגשמיות כמעשה בהמה ממש כידוע ולהיות כן וודאי המה רחוקים ומפורדים זה מזה בתכלית הריחוק והפירוד וא\"א שיתקרבו ב' רוחות הללו יחד כי המה מנגדים זה לזה בתכלית כאש ומים וכה\"ג אך הנה זהו דוקא כשאינם נלחמים זע\"ז אז הן בבחי' הפירוד והריחוק מאוד זמ\"ז אבל כשנלחמים יחד אז נצמדים ודבוקים זה עם זה כדרך מלחמת ב' בנ\"א שרוצה הא' לנצח לזולתו שיוכלל בו כנ\"ל באריכות:\n(ב) <b>והענין</b> הוא כמ\"ש בזוהר דשעת צלות' שעת קרבא כו'. דהנה באמת יש ב' מדרגות בעבודה שבתפלה הא' שאינו נק' קרבא ומלחמה כלל והוא בחי' עבודה של נפש אלקית מצד עצמה וטבעה לבד שהוא טבע רוח האדם העולה כו' כנ\"ל וכידוע בענין תפלה דשבת שהוא רק להתענג על ה' כו' שזהו בחי' התכללות אור הנשמה האלקית במקור חוצבה שעולה לשם כביטול והתכללות הנר בפני האבוקה כמו הנשמות בג\"ע שנהנין מזיו כו' וכמו כן תתעורר רוח נה\"א בשעת התפלה לידבק וליכלל באחדות ה' מצד מהות טבעה ואינה מהפכת לטבע"],[2500660206,"רוח הבהמה שבחלל השמאלי שבלב כלל להיות גם היא מסכמת ורוצה לעלות לה' כו' אלא טבע רוח הבהמה נשאר במהותו בבחי' הפירוד כו' רק אור הנשמה מצד עצמה מתדבקת ועולה למעלה מעלה כידוע בענין למסור נפשו באחד כו' והיינו כשאין מלחמה כלל בין ב' הרוחות הללו אלא כ\"א עומד במדרגתו ומופרדים זה מזה ולא קרב זה עם זה כלל ואמנם המדריגה הב' בתפלה הוא כשנקרא קרבא ומלחמה כמ\"ש בזוהר הוא כאשר תתגבר רוח האדם ברשפי אש התשוקה לה' להפוך גם לרוח הבהמה שבגוף החומרי שגם הוא לא יתאוה ברצון ותשוקה זרה רק לה' לבדו ולמאוס בכל רצון תאוה זרה ולא לחפוץ בשום דבר מהבלי העולם הזה בלתי לה' לבדו כמ\"ש מי לי בשמים ועמך לא חפצתי כו' וכמארז\"ל לב א' לאביו שבשמי' כו' שהוא רק רצון א' לה' לבדו כו' הנה זה א\"א להיות כ\"א בדרך מלחמה וניצוח כשנפש האלקית נלחמת עם נה\"ב ורוצה להכניעה להיותה כלולה בה ולא תהיה בחי' מנגד כלל והוא להפוך את הטבע לגמרי שלא תרד למטה לידבק לגופניו' וחומריו' דמעשה בהמה רק תהיה עולה למעלה ברצון ותשוקה כמו רוח האדם שעולה כו' ה\"ז כמו שיגבר הא' על זולתו ומנצחו שיוכלל בו ולא יהיה בחי' נפרד בפ\"ע כלל וכנ\"ל בב' הפכים דאש ומים כשיגביר הא' על היפוכו שמהפכו להיות כטבעו כו' וא\"כ וודאי זה א\"א כ\"א שיתקרבו ויתדבקו ב' הנפשות הללו כדרך הנלחמים יחד הנק' התאבקות כמו ויאבק איש עמו והוא מ\"ש בזוהר דשעת צלותא שעת קרבא שב' הנפשות נלחמים זה עם זה וכ\"א רוצה להתגבר על זולתו ולהכניע וליכלל בו וזהו שורש ענין המ\"ז שבתפלה כידוע דהנה אנו רואים שיוכל להיות התפלה בכוונה ואף על פי כן מיד אחר התפלה הולך ומתעסק בהבלי עולם בכל לב ונפש כאלו לא התפלל כלל ולכאורה נראה לאדם שתפלה זאת לא היתה אמיתית כלל שאם היתה אמיתית בכל לב ונפש הרי נאמר שפת אמת תכון לעד ועד ארגיעה לשון שקר כו' אבל האמת הוא שתפלה זאת נק' שפת אמת מצד התעוררות נפש האלקית שרוח האדם עולה באמת מצד"],[2500660207,"טבעו ושרשו כנ\"ל ולעבודה הזאת של נה\"א מצד עצמה תכון לעד ואין בה שינוי לעולם וכמו שאומר נשמה שנתת בי טהורה היא כו' אך מה שאחר התפלה חוזר להתקש' ברצונות זרות של הבלי עולם זהו מצד ההתעוררות רוח הבהמי שנשארת בגוף בתקפה ולא נזוזה ממקומה וטבעה כלל בשעת התפלה ועבודה של נה\"א כי נה\"ב רחוקה ומופרדת ואין לה שייכות כלל עם עבודה דנה\"א אדרבה בורחת מאוד מאור אלקי הזה שבנה\"א וע\"ז נאמ' ועד ארגיע לשון שקר דגם אם נה\"ב מתעוררת בתפלה לפעמים להיות גם היא עולה ברצון ה' כו' אין זה רק כמעט רגע בלבד אבל מיד יש בה שינוי ותחזור לקילקולה להמשך למטה כטבע רוח הבהמה שיורדת למטה כו' אך אם הנה\"א נלחמת עם הנה\"ב ומנצחת לנה\"ב לאכפיא ס\"א כו' להכניע אותה בתכלי' עד שיוכלל לגמרי להיות גם היא כמו רוח האדם לעלות למעלה שהוא רק רצון א' לה' לבדו ואין זר אתו כו' כנ\"ל אז גם בה נאמר שפת אמת תכון לעד שאין בה שינוי לפי שנתקשרו ונכללו בנה\"א לבלתי תוכל להפרד בבחי' פירוד במהות בפ\"ע וכמו צ\"ג שלבם ברשותם לפי שהנשמה שבמוח שליט על הלב כו' וד\"ל:\n(ג) <b>והנה</b> כאשר רוח האדם נלחם עם רוח הבהמה בהכרח שיתאבקו ויתקרבו יחד וזהו שרש הטעם להתגברות המ\"ז בשעת התפלה דווקא יותר מבשעה אחרת כי שעת צלות' שעת קרבא שנה\"א נלחם לנצח לנה\"ב ועיקר הניצוח אינו בא אלא מסיבות ההתאבקות מקירוב דוקא כמו במלחמו' ב' בנ\"א כו' וכך בתפל' דוקא שכאשר מתעורר נה\"א להפוך גם הרע שבנה\"ב שאז מתקרב ומתאבק בנה\"ב ונה\"ב מתאחד ונדבק בנה\"א לבלבלה במחשבות זרות כי היא הפכית ממש מרוח האדם ולזאת מתגברת בכל כחה אז דוקא לבלבל במ\"ז שונות שלא היה עולין מחשבות רעות כאלה שלא בשעת התפלה כי בשעת מלחמה דוקא אז טבע הנלחם להתגבר בכל כחו על זולתו לנצחו ולהכניעו אליו שיוכלל בו כנ\"ל וכך מתגבר' בכל כחה הנה\"ב"],[2500660208,"להכניע לנפש האלקית שלא תעלה למעלה אלא תרד ותמשך גם היא למטה מטה להיות כטבע נה\"ב שיורדת למטה כו' והן הן התגברות המ\"ז כו' משא\"כ כשאין נה\"א רוצה להלחם עם נה\"ב אלא עבודתה מצד בחי' עצמותו לבדה ולא להפוך לנה\"ב כלל (כמו ענין התפלה דשבת כנ\"ל) אז אין מתגברין מ\"ז כלל כידוע וד\"ל. והנה ידוע שכמו שהנפש עצמ' אין לה איבוד וכליון כך גם כל כחות שלה המתפשטי' ממנה אין להם איבוד וכליון ולפ\"ז אפי' מחשב' אחת שאדם חושב אין לה איבוד כי לא דבר גשמי הוא שיכלה ויאבד כו' ומאחר שהמחשבה הוא בחי' התפשטות אור וחיות מעצמות הנפש הרי בהכרח שיש קיום נצחי למחשבה זאת כמו שיתקיים עצם הנפש וא\"כ בצאת הנפש ממאסר הגוף יצא עמה כל הכחות המתפשטו' ממנה וגם אפי' מחשבה א' שחשב תצא עמה ואין לה איבוד כלל ולפ\"ז כל המ\"ז אשר לא לה' המה שחשב האדם כל ימי חיי הבלו בעוה\"ז אחת לא נעדרת בצאת הנפש מהגוף וגם כל אותיות הדיבור חיים וקיימי' כמ\"ש במ\"א (וראיה ממ\"ש מגיד לאדם מה שיחו אפי' שיחה קלה כו' אך הבל אותיות הדיבור הוא נשאר באויר אבל אותיות המחשבה מתאחדת בנפש כו') והנה ידוע ג\"כ שאין לנפש קיום בלי התפשטות וכלי שהוא הגוף כמו שאין לאור קיום בלא עץ ופתילה כו' ולזאת לא מצינו שתתקיים הנפש בלא כלי ואם תצא הנפש מגוף זה מיד תתפשט בגוף אחר וגם הנפשות העולות לג\"ע מתלבשים ומתפשטים שם בכלי דוקא כידוע ומבואר במ\"א וא\"כ הרי מובן ממילא שגם המחשבות שהן בחי' התפשטות אורה המה בדומה אלי' בדבר הזה שא\"א להם להתקיים בלי התפשטות בכלי מאחר שהן בחי' אור וחיות רוחני וכל בחי' אור וחיות רוחני אין לו מציאות בלי התלבשות והתפשטות בכלי שהוא הגוף כו' וזהו שאנו מוצאין שיוכל להיות התהוות הנפש שלמה להחיות גוף א' מבחי' ריבוי המחשבו' הזרות שמתקבצין ביותר ונעשים בחי' אור וחיות נפש שלמה כמו נפש בע\"ח של המזיקין שנעשים ממ\"ז של בנ\"א והן המייסרין"],[2500660209,"ורודפין את האדם (וכמ\"ש במ\"א שמנשמה גבוה נופלים המ\"ז שלה ונעשים בחי' נפש שלימה למטה ומתלבשים בגוף והוא המקטרג ורודף ומייסרו כו' ויש נשמות גבוהו' שממ\"ז שלהם בחי' נובלות ומותרות יהיה מזה שפע רב למטה כמשל עלה של אילן גבוה במעלה מתהווה ממנה פרי באילן שלמטה הימנה כו') ונמצא שרבוי המ\"ז דרוח הבהמה מתהווה מהן אויבים ושונאים הרבה שנק' מקטרגים ומזיקין שרודפין לנפש האדם ונעשים רצועה לאלקאה כו' מפני שבאין בהתלבשות בגופין עד שהן כמו אויבים נפרדים ובאמת הן הן מחשבותיו שחשב בנפש ורוח הבהמ' כל ימיו כו' ולפ\"ז יובן שבהתגברות המ\"ז בשעת התפלה ה\"ז כמו שקמים עליו אויביו ושונאיו להזיקו ולהפילו כו' וד\"ל:\n(ד) <b>וזהו</b> כי הנה אויביך ה' כו' דהנה ידוע דשם הויה הוא מאיר בכל נה\"א כו' לפי שבצלם אלקים עשה את האדם בב' שמות דהויה ואלקים כמ\"ש וייצר ה' אלקים את האדם כו' ובחי' האויבים המנגדים לבחי' הויה המאיר בנה\"א הוא בחי' התגברו' המ\"ז בנה\"ב בשעת התפלה דוקא שאז מתגברת בכל כחה ללחום עם נה\"א כנ\"ל דשעת צלותא דוקא שעת קרבא כנ\"ל (ועד\"מ הנלחמים שמתאבקים יחד כו' כך מתאבקת הנה\"ב ונאחזת ונדבקת בהתקרבות עצום בנה\"א כדי לנצחה במ\"ז כנ\"ל). והנה אז דוקא אויבי ה' שהן המ\"ז מקבלין תו' יניקה וחיות מאור אלקי שבנה\"א כי באמת אין רע יורד מלמעלה שנאמר לא יגורך רע כו' וכן מפי עליון לא תצא הרעות כו' אך מבחי' הפסולת של הטוב מקבל הרע יניקה וכידוע בשרש ענין עה\"ד טו\"ר כו' וכל מקום שיש ריבוי הטוב שם נמצא קירוב ודיבוק הרע לקבל יניקה יותר ע\"ד שארז\"ל כל הגדול מחברו יצרו גדול כו' וכמו גנבים שודדי לילה שמוסרי' נפשם במקום שיש אוצר רב דוקא כו' וכמ\"ש במ\"א וזהו הטעם בשע' התפלה דוקא לפי שאז מתגבר הנה\"א בכל כחה להפוך גם נה\"ב כנ\"ל אז דוקא מתקרב הנה\"ב בכל כחה לדבק בנה\"א במ\"ז לקבל יניקה יתירה להיות כי נעשה בבחי' תערובו' טו\"ר ביותר ע\"י ההתאבקות הזאת כו'"],[2500660210,"כי הנה ידוע כל המתאבק עם מנוול מתנוול גם הוא בהאבקו עמו כו' כי מאחר שצריך להאבק עמו בדיבוק וקירוב ביותר אע\"פ שמנצחו ומפילו מ\"מ בעת חיבוקו עמו הרי נתלכלך ונדבק בו מלכלוך צואת המנוול וצריך רחיצה ושיפשוף גדול אח\"כ כו' וכך היה בהאבק יעקב עם שרו של עשו אע\"פ שנצחו מ\"מ נתלכלך מאבק זה כמרז\"ל שהעלו אבק כו' (וכדוגמא זאת בכל הברורים דמברר צריך להתלכלך בגדיו בשעת התלבשותו לברר ע\"י לבושים צואים של המתברר כמו שמבואר בענין תרומת הדשן שצריך להתלבש בלבושים פחותים להוצאת הדשן מפני שצריך להתלכלך בדשן וע\"ד שארז\"ל בגדים שבשל בהם קדירה לרבו כו' וכך למעלה בבירורים דשם ב\"ן בכל גלות השכינה באוה\"ע כו' כמארז\"ל גלו לאדום שכינה עמהם כו' דכתיב מי זה בא מאדום חמוץ בגדים כו' פורה דרכתי לבדי כו' ויז נצחם על בגדי וכל מלבושי אגאלתי וכמ\"ש במ\"א באריכות כו' וד\"ל) וכך הוא בהאבק נה\"א עם נה\"ב בקירוב גדול אע\"פ שמנצח ומהפך כל הרע דמ\"ז להיות עקירת כל רצון זר בלתי לה' לבדו כו' מ\"מ בעת האבקם מתלכלך נה\"א בלבושים צואים דנה\"ב שהן המ\"ז וכה\"ג וצריכה רחיצה ושפשוף גדול וז\"ש רחצתי את רגלי איככה אטנפם כו' וכמ\"ש במ\"א בענין אם רחץ ה' את צואת כו' תבא האם ותקנח צואת בנה שהוא הנה\"א מלבושים צואים דנה\"ב בהאבקם יחד וד\"ל וכה\"ג היה ענין ערב רב שעלו עם ישראל ממצרים שהמה האספסוף שבקרבו שהתאוו תאוה כו' וגרמו רע' לישראל כי כל רע הקרוב יותר ומתדבק אל בחי' הטוב יותר מזיק לטוב לנוולו כו' וכמ\"ש במ\"א בענין השליא של הולד שהשונאים והאויבים ביותר לישראל עם קדוש המה עכו\"ם הקרובים יותר אל בחי' הטוב כמו האפיקורסים שיודעים את רבונם כו' שעליהם נאמר תכלית שנאה שנאתים כו' ואפילו גרים שבאוה\"ע קשים לישראל כספחת כו' וד\"ל. וזהו כי הנה אויביך ה' כו' יאבדו כו' פי' אויבי ה' הן הקרובי' ביותר אל בחי' הטוב שבכללו' נ\"י שמתדבקי' לקבל תו' יניקה וחיות"],[2500660211,"כמו בהאבק איש עם יעקב שבחיבוק זה קיבל שרו של עשו תוס' יניקה מבחי' יעקב דקדושה וז\"ש אויביך ה' יאבדו ויש פסיק טעמא בגווייהו להיות שגם שסיבת תוספ' יניקת האויבים מהקדושה הוא בא מצד בחי' הקירוב והדיבוק בהאבקם כנ\"ל אבל מ\"מ הרי עיקר ההתאבקות הזאת אינו דיבוק ויחוד אמיתי מצד עצמו אלא אדרבה הרי הן באין למנגד ולחלק להיות עי\"ז התגברות הרע על הטוב בבחי' הפירוד למטה כנ\"ל ונמצא מובן שבאותו האור וחיות האלקי שמקבלין מצד בחי' הקירוב והדיבוק של ההתאבקות הזאת גופא המה מתגברים להיות למנגד לה' עד שנקרא אויבי ה' ממש ולכך פסיק טעמא בגווייהו להורות על הפסק ופירוד גמור שנעשה מזה הדיבוק בהוי\"ה כו' אך הנה אמר דאויביך ה' הנלחמים עמו יאבדו כו' להיות שכל זאת יניקה והתגברות האור והשפע לחיצונים בהאבקם עם הקדושה האלקית אינו רק לפי שעה בלבד וכמאמר שהשעה משחקת להם כו' והוא שעת קרבא לבד אבל לאחר גמר המלחמה כשנה\"א מתגבר על נה\"ב ומנצחה להיות גם היא מוסרת נפשה וכל רצונה בלתי לה' לבדו כנ\"ל וכמ\"ש ביעקב כי שרית עם אלקים כו' שהודה לו וברכו כו' וזהו בכללות נ\"י כמו בדרך פרט בכל ניצוץ אלקי שבכל א' וא' מישראל שנקרא ישראל מטעם זה כי שרית כו' וכידוע והוא באמרו שמע ישראל כו' ומזה נעשה ואהבת כו' בכל לבבך בשני יצרך כו' דוקא כידוע דהיינו שגם הרע נהפוך לטוב או כפוף בתכלית כמו בצדיק גמור לבו ברשותו שהמוח שליט על הלב שנקרא אתכפיא כנ\"ל אז נהפוך הוא שנכרת ונפסק כל שורש חיות אלקי מבלתי נמשך עוד לחיצונים אפילו כדי מדתם המצומצמת מקדם וז\"ש כי הנה אויביך יאבדו מפני שנפסק מהם גם שורש יניקתם הקדום ואז ממילא יאבדו כי אין לרע קיום ותקוה רק מן הטוב כנ\"ל וזהו ולמלשינים אל תהי תקוה כו' וכמ\"ש במ\"א בפי' חיל בלע ויקיאנו וכן והוצאתי את בלעו מפיו שכל אור וחיות שבלע מן הקדושה ע\"י המלחמה וההתאבקות יקיאנו כי יוציא ממנו כל בחי' הטוב גם מה"],[2500660212,"שהיה לו מצד עצם הבריאה ע\"פ מאמר קו המדה כי זהו דרך המלחמה כשמנצח לאויב ושונא שנעשה עבד גם בשלו וכמו ואכלת את שלל אויביך כו' (וכדוגמא זאת מצינו באברהם אבינו ע\"ה עם הד' מלכים דכתיב ויחלק עליהם לילה ויכם כו' דחלק זה הוא ענין פסיק טעמא הנ\"ל באויביך ה' דהיינו שנחלק ה\"א דלילה להיות כמו ליל שמורים כו' משום דה\"א תתאה בחי' המל' מחיה גם לחיצונים וכמ\"ש ומלכותו בכל משלה ונחלק עליהם הלילה שלא יחיה עוד לחיצונים מפני שאבות הן המרכבה והפריד אברהם אע\"ה מנה\"ב שבגופו כל פסולת ורע עד שלא היה להם צד קירוב ודיבוק להאחז ולהדבק בה\"א תתאה כלל כמו אחר גמר הניצוח דנה\"א לנה\"ב כנ\"ל ואז ממילא אין לחיצונים חיות כלל וכמ\"ש בענין סר צלם מעליהם שנעשו כבהמות שיראים מאדם ע\"כ א' ירדוף אלף כו' ואז ויכם וז\"ש יתן כעפר חרבו שדי עפרא והוי חרבא כו' וד\"ל). והנה מ\"ש יאבדו ואח\"כ אמר יתפרדו כל פועלי און כו' הענין הוא להיות מבואר למעלה שיוכל להיות התהוות נפש שלימה בגוף מריבוי המ\"ז כו' והוא הנקרא אויביך אשר רדפוך כו' אך לאחר ניצוח דנה\"א לנה\"ב שנהפך גם כל המ\"ז שקדמה להיות לה' לבדו ואין זר אתו כו' הרי כל המ\"ז שחשבה הנפש מכבר לא יתפשטו עוד לבוא בגופים אלא יאבדו לגמרי כמו הפסולת שנאבד ויצא לחוץ כמו באיבוד רשעים מאחר שיצא כל בחי' הטוב מהם ע\"י התשובה מעומקא דלבא בעקיר' כל רצון הזר כו' א\"כ מה שנשאר חיות מהם הוא רק בחי' תכלית הפסולת שאין לו תיקון רק איבודם זהו תיקונ' כמ\"ש באבוד רשעים רנה זהו בחי' רנה ותיקון שלהם כמ\"ש במשל העלוקה ששואבת פסולת הדם ונופלת ומתה וז\"ש תמות' רשע רעה וכמאמ' רז\"ל לע\"ל ישחוט ליצה\"ר כו' וז\"ש כי הנה אויביך ה' שאין להם בירור יאבדו לגמרי כו' ומ\"ש יתפרדו כו' היינו אותן מ\"ז של כל מיני רע שכבר נתפשטו וירדו להתלבש בגופי' ונעשו מזיקין ומקטרגין ליסר האדם ולרודפו והן הנק' נגעי בנ\"א הן ברוחניות הן בגשמיו' כנ\"ל ע\"ז אמר שגם אותן הגופים יתפרדו פי' שגם שהם"],[2500660213,"כבר מלובשים בגופים אבל לא יפעלו רע כלל מפני שיתפרדו בבחי' פירוד ופיזו' גדול כמארז\"ל פיזור לרשעים הנאה להם כו' כי הקיבוץ מן כל המ\"ז נעשה רוב עם העומדים לבחי' מנגד להם כנ\"ל אבל בפיזור ופירוד שלהם אין בכל א' כח ועוז כלל לעמוד לנגד אלא אדרבא כאו\"א נכנע ובטל בתכלית במיעוטו כו' וזהו מ\"ש קומה ה' ויפוצו אויביך כו' מפני שכאשר זה קם זה נופל כו' שכשיש בחי' בנין קומה שלימה בכנ\"י בכחב\"ד ומדות כו' אז בזלע\"ז נעשה פיזור ופירוד כו' וז\"ש יאבדו על המ\"ז שלא באו בגופי' ויתפרדו גם אותן שבאו בגופים כמו כל מלחמה גשמית שהרבה נהרגין ונאבדים לגמרי והרבה נפוצי' ונתפזרין וכמ\"ש ויפוצו וינוסו כו' וזהו דוקא עכשיו דצלותא נק' קרבא אבל לע\"ל כתיב לא ירעו ולא ישחיתו כו' ארי' כבקר יאכל תבן וגר זאב עם כבש ופרה ודוב כו' מצד בחי' הביטול שיהי' על כל הברואים שמפני שנגלה כבוד הויה כו' שזהו לאחר כל הבירורים דעכשיו דכתיב אז אהפוך כו' שפה ברורה שלא יצטרך להיות בחי' מלחמה כלל אלא יהיו כולם בבחי' הביטול האמיתי כו' (כמו שיתבא' בסמוך בפ' פדה בשלום נפשי כו') :\n(ה) <b>והנה</b> כל ענין מלחמה הנ\"ל של נה\"א עם נה\"ב לא שייך רק בחלק של נה\"א המלובש בגוף והוא בחי' נר\"נ שבה שבא בבחי' אור פנימי אור בכלי הגבלה כו' כידוע וזהו בחי' אהבה דבכל לבבך ובכל נפשך אבל בחי' חיה יחידה שבנה\"א שלמעלה מבחי' הגבלת אור בכלי הגוף לגמרי כי הוא רק בבחי' אור מקיף והוא אהבה רבה דבכל מאודך כידוע הנה שם לא שייך לומר בחי' מלחמה כלל עם הנה\"ב כו' וד\"ל. וביאור הדברים הנה ידוע ומובן עד\"מ מבחי' אור וחיות הנפש בגוף בכלל שיש בזה ב' מדרגות כידוע הא' בחי' או\"פ והוא בחי' אור וחיות הנפש הבא בכל אברי הגוף בכל אבר לפי מזגו ותכונתו דוקא כמו בכלי המוח שם משכן אור השכל ובכלי העין משכן אור הראיה וכה\"ג עד שבחי' החיות הזה נמשך בצמצום ומיעוט אחר מיעוט בכלים מכלים שונים באיברי הגוף"],[2500660214,"ממוזג רק לפי טבעי האברים שזהו הנקרא בחי' א\"פ עד מיעוט וצמצום היותר אחרון כמו ציפורן הרגל וכמ\"ש במ\"א אבל בחי' אור מקיף דנפש היינו חלק העצמות שבנפש שהוא העיקר והמקור שממנו בא ונמשך בחי' התפשטות האור וחיות דנפש באברי הגוף לכל או\"א כמזגו כו' ולפ\"ז יובן שבחי' מקור זה נקרא בחי' מקיף שסובב ומקיף לכל האור וחיות הבא בבחי' או\"פ בכלי הגוף מראש לסוף וכוללם יחד לפי שבעצמו הוא למעלה מבחי' התחלקות ראש וסוף מאחר שהוא למעלה מבחי' התלבשות בכלי ע\"כ ממילא הוא מאיר בבחי' מקיף וסובב לכל הגוף ראש וסוף בהשוואה א' ממש כו' בלי חילוק מדרגה כלל בין המוחין שבראש לציפורן הרגל וכה\"ג וכמ\"ש במ\"א וד\"ל וכמ\"כ יובן ההפרש שבין בחי' מקיף דנה\"א שנקרא חיה יחידה לבחי' א\"פ הנקרא נר\"נ כנ\"ל דהיינו שבחי' המוחין חב\"ד שבה היא בבחי' ההשגה והתפיסה בא\"פ שנתפס בכלי המוחין נקרא נשמה כידוע שמשכן הנשמה במוח ורוח בלב כו' וזהו בחי' או\"פ מוגבל בכלי המוחין בכל חד וחד לפום שעוריה דיליה כמ\"ש בזוהר ע\"פ נודע בשערים כו' כי יש שכל מתפעל כו' וכן רוח בלב שע\"ז נאמר תוכן רוחות ה' וכמ\"ש במ\"א וכ\"ז בבחי' א\"פ מוגבל בכלי כמשל אור וחיות הנפש באברי הגוף בכל א' לפי מזגו כנ\"ל אבל בחי' המקיף דנה\"א הוא בחי' עצמיות דנה\"א שלמעלה מבחי' התפשטות והתלבשות בכלי המוחין חב\"ד וחג\"ת כו' אלא הוא בחי' העיקר והמקור שממנו בא בחי' התפשטות אורות דנר\"נ בכלים מוחא ולבא כו' ע\"כ הארתו בבחי' מקיף וסובב עליהם בהשוואה א' לראש וסוף ממש בלי חילוק מדרגה כלל כנ\"ל במשל המקיף דנפש על אור וחיות אברי הגשמיים כו' וד\"ל:\n(ו) <b>וזהו</b> ג\"כ ההפרש בין אהבה דבכל נפשך שהוא בבחי' א\"פ בבחי' נר\"ן במוחא ולבא כו' הבא בבחי' הגבלה מאוד רק כפי ערך הגבלת הכלים דמוחא ולבא כו' לבחי' אה\"ר דבכל מאודך שהוא בחי' אור מקיף בלתי מוגבל בכלי המוח כו' שע\"ז אמרו רז\"ל דאכל עשרה שכינתא שריא"],[2500660215,"כו' משום דבבחי' יחידה דנה\"א שורה אלקות ממש ואין חיצונים מקבלים שם יניקה כלל כמ\"ש מיד כלב יחידתי כו' וז\"ש גם כי אלך בגיא צלמות לא אירא רע כי אתה עמדי דא שכינתא דשריא על רישא דב\"נ שהוא בחי' המקיף דיחידה שנאמר ע\"ז אך בצלם יתהלך איש כו' וכמ\"ש בזוהר ע\"פ שימני כחותם כו' דיוקני אשתאר בך כו' וז\"ש ג\"כ בזוהר ע\"פ נפש כי תחטא תווהא כו' וכמ\"ש נשמה שנתת בי טהורה היא כו' וכמ\"ש במ\"א באריכות ולכך נקרא בכל מאודך בלי גבול בכלי כידוע והנה יש ב' מקיפין בחי' חי' ובחי' יחידה כו' כידוע והן ב' מיני רצון הא' רצון המאיר ומתפשט בכלי המוח והלב כו' דגם ששרשו בבחי' מקיף מ\"מ מאיר ובא במוח ולב דרך פרט כו' אבל רצון הב' הוא נקרא רצון פשוט שלמעלה מהארה והתפשטות לגמרי במוח ולב כו' והוא ההפרש שבין בחי' ב' מקיפין דחיה ויחידה שנקרא מקיף כללי ומקיף פרטי כמ\"ש בע\"ח. וביאור הדברים הנה יש להקדים תחלה במה שאנו רואים שכאשר יש לאדם איזה רצון ותשוקה לדבר מה הנה יוכל להיות בה ביטול והפסק לגמרי מפני רצון ותשוקה הגדולה ונפלאה ממנה הרבה כאשר היא הפכית מתשוקה ורצון זה אע\"פ שמפני התגברות אותה התשוקה הנפלאה יכנע ויבוטל לגמרי תשוקה הראשונה כאלו לא היתה מעולם אעפ\"כ אין זה ביטול גמור בהפיכת מהותה וטבעה שהרי לא נהפך טבעה ומהותה כלל ואדרבה הרי ישנה בתקפה ומהותה ולא נתבטל ממנה כלום רק שאינה מאירה בגילוי במוח ולב כלל מפני תוקף התגברות הרצון והתשוקה הגדולה ממנה בשעה זאת במוח ולב אבל מיד כשיסיר ממוחו ולבו אור ורצון התשוקה הגדולה והנפלאה ממנה תשוב התשוקה הזאת לתקפה וטבעה בגילוי גמור כמו שהיא בלי ביטול אפי' כל שהוא ונמצא שבחי' הביטול וההפסק שלה אינו ביטול אמיתי רק הפסק וביטול לפי שעה וגם זה אינו נקרא ביטול המהות כלל רק העדר גילויה לבד כו' וא\"כ לפ\"ז יובן שגם בבחי' מלחמה וניצוח הגם שמנצח הרצון הזה לרצון ותשוקה הקודמת אליה מפני תוקף התגברותה עליה ביותר כו' מ\"מ"],[2500660216,"אין זה ביטול גמור ואמיתי דגם שיבטלנה לפי שעה אבל לא ביטול המהות כלל רק דרך ההכנעה להיות בבחי' העדר הגילוי לגמרי כאלו אינה במציאות כלל אבל באמת הרי ישנה בתקפה כנ\"ל וזהו נקרא אכפייא ולא אתהפכא כו' ע\"ד דוגמא כשאדם חפץ ורוצה בתאות ממון להרויח הון רב אך בסיבת זה יפסיד חיי נפשו או נפש ב\"ב שיקרים בעיניו מכל הון כו' וכה\"ג או כשיבא לידו איזה גדולה וכבוד להיות מלך או שר כשיפסיד הריוח או מפזר הון רב וכה\"ג הנה ודאי כלא חשיב כל הון הממון לגבי הגדולה והכבוד שישיג וישליך מנגד זה הרצון ותשוקה של הממון לגבי הרצון ותשוקה הגדולה ונפלאה ממנה שהוא רוב הכבוד והגדולה כידוע ואמנם לא שנתבטל הרצון מן הממון לגמרי כי ודאי יש לו צער מהיזק הממון רק שמפני תוקף התגברות הרצון של כבוד והגדולה יבוטל רצון זה של הממון לפי שעה ולא יאיר בגילוי כלל אבל ישנו בטבעו ומהותו רק שנכנע ובטל בהעדר התפשטות הגילוי בלבד כו' כנ\"ל וד\"ל. וכ\"ז מפני שכל עיקר תולדות הרצון הזה אינו בא אלא בבחי' גילוי א\"פ מן הנפש במוח ולב כו' שהוא בא בבחי' הגבלה לפי הכלי בלבד כו' ע\"כ בבוא גילוי רצון אחר הגדול הימנו בהכרח שיסתלק אור הרצון הראשון מן המוח והלב מפני תוקף גילוי אור הרצון הזה כו' וזה הנקרא בחי' מלחמה וניצוח שמנצח ומכניע לזולתו שיסתלק ויתבטל לפי שעה ממעמדו והוא עומד בעמדו כו' כמשל ב' בנ\"א הנלחמים שכאשר ינצח הא' לזולתו ויפילנו יעמוד במקומו ומעמדו כו' אבל אין זה ביטול המהות של זולתו לגמרי רק שמכניע אותו לבלתי יתפשט להרים ראש וד\"ל אבל מלחמה ונצוח דב' יסודות הפכים כמו אש ומים אין זה ענין הכנעה לבד אלא היפוך המהות לגמרי שהרי כשיגביר האש על המים יהפוך טבע המי' להיו' כמוהו כטבע האש ממש וכן להיפוך כשיגברו המים על האש כו' כידוע בהרכבת היסודות ההפכים שכל א' כשנהפך ונכלל בזולתו ההפכי מוסיף בטבע זולתו כאלו הוא חלק עצמי ממנו ולא מורכב כו' וזהו עיקר בחי' ההתכללו' האמיתי"],[2500660217,"כידוע אך כאשר הא' סובל היפוכו בלבד בדרך סבלנות והכנעה ולא ביטול המהות אין זה נק' התכללות ע\"ד שאמרו מיכאל וגבריאל שר של אש ושר של מים ואין מכבים זה את זה כו' הרי מ\"ש רק שאין מכבי' להיות א' מנגד לזולתו אלא כ\"א סובל היפוכו אבל לא שנתבטל מהות כ\"א ליכלל בהיפוכו כמו ב' עבדים או שרים מנגדים שעומדים לפני המלך שסובלים זה את זה מצד בחי' הביטול שעליהם מאימת המלך אבל בעצם מהותם הם ב' הפכים באמת כו' וז\"ש עושה שלום כו' כמ\"ש במ\"א אבל מלחמה להפוך המהות כנ\"ל יותר נעלה מענין השלום כזה רק שלום אמיתי בהתכללות אמיתי הוא בא בב' אופנים א' ע\"י המלחמה להפוך המהות כמו מלחמות יהושע ודוד או בלא מלחמה כמו בימי שלמה וימות המשיח כמ\"ש במ\"א וד\"ל. ונמצא שיש ב' מיני מלחמה הא' רק להכניע ולאכפייא לבלתי יתפשט לבד אבל לא ביטול המהות הנק' התכללות אמיתי כנ\"ל והב' מלחמה שמנצח להפוך ולבטל המהות כנ\"ל עד שנכלל בו ונעשה כחלק עצמי ממנו כו' שנק' התכללות אמיתי כנ\"ל והנה ב' מיני מלחמות הללו הכל הוא בבחי' א\"פ לבד דהיינו כמו בב' רצונות שהמה מוגבלים במוח ולב בבחי' א\"פ כאשר יגבר הא' על היפוכו המנגדו להכניעו ולבטלו גם בבחי' ביטול המהות שנק' התכללות כנ\"ל וזהו גם בבחי' מקיף שנק' חיה המאיר במוח ולב דגם שמצד עצמו הוא בחי' מקיף למעלה מהגבלת כלי המוח והלב כידוע דנר\"נ מלובש במוחא ולבא כו' אבל בחי' חיה ויחידה בלתי מוגבלים בכלים כלל כמ\"ש בע\"ח וכנ\"ל אך עכ\"ז מאחר שמאיר ומלובש בכלי המוח והלב כו' ג\"כ בו יתכן בחי' מלחמה הנ\"ל משא\"כ בבחי' יחידה כמשית' בעז\"ה וד\"ל :\n(ז) <b>וכמו</b> כן יובן בב' מיני אהבות דבכל לבבך ובכל נפשך שארז\"ל בשני יצרך שזהו לאכפייא או לאתהפכא בבחי' ביטול והתכללות כל הרצונות הזרות להיות הרצון רק לה' לבדו כמ\"ש מי לי בשמים כו' והוא ע\"י בכל נפשך בחי' המקיף דחי' שמגביר אור הרצון אלקי שבנה\"א להכניע לכל הרצונות דנה\"ב לגמרי בדרך"],[2500660218,"מלחמה וניצוח להפוך המהות כנ\"ל והוא מה שאנו רואים שיוכל להיות בחי' היפוך מהות וטבע כל המדות רעות להיות רק לה' לבדו ואין זר אתו רק ע\"י מלחמה דנה\"א שמתגבר על נה\"ב בשעת התפלה שאז שעת קרבא כנ\"ל וד\"ל אבל בחי' אה\"ר דבכל מאודך היא בחי' מקיף דיחידה שלמעלה לגמרי מבחי' הגבלה במוח ולב כו' דהיינו שאינו מאיר לעולם במוחא ולבא גם לא בבחי' מקיף ונק' מאדך בלי גבול בעצם ולא שהוא בלי גבול לגבי הכלי לבד כמקיף דחי' הנ\"ל דשם לא יתכן בחי' מלחמה כלל וזהו בחי' מס\"נ האמיתי שאחר מס\"נ בכל נפשך כו' וד\"ל. וביאור הדברים הנה ידוע דיש ב' מיני מס\"נ הא' ע\"ד הנ\"ל בבחי' ביטול כל הרצונות הזרות דנה\"ב בהיפוך המהות הנק' התכללות כו' מצד בחי' המלחמה דנה\"א שנלחמת עם נה\"ב עד שיגבר גודל התשוקה הנפלאה בתענוג האלקי בהתגברות נפלאה ועצומה ביותר עד שהרצון הזר המנגד יתבטל בתכלית הביטול והתכללות כאילו אינו במציאות ומהות הקדום אדרבה נהפוך למהות אחר והוא למאוס ברע ולבחור בטוב שזהו נגד טבעו ומהותו הקדום כו' כנ\"ל. אך הנה אנו רואים שכ\"ז הביטול מנה\"ב במציאותה אינו רק מצד בחי' ביטול המיעוט ברוב ע\"ד דוגמא מביטול טיפה בים שנכללת בים כאלו אינו מציאות כלל ואע\"פ שהוא ההפכית כמו מים מרים במים מתוקים שנהפוך המר למתוק ע\"י בחי' ביטול במיעוטו בתכלית המיעוט כמו טפה בים וכה\"ג או מצד תגבורת טעם המתיקות כ\"כ עד שמהפך גם לטעם המרירות למתיקות וזה הביטול וההיפוך אינו מצד המיעוט אלא מצד התגברות הכח המנגדו עד שמהפכו כו' (וכמ\"כ התכללות האש במים כשמתגבר כח יסוד המים עליו עד שהי' כמוהו כו' או להיפוך כנ\"ל) וכך הוא ממש בענין הביטול הרצון הקטן לגבי הרצון הגדול ממנו כמו רצון ותשוקה להרוויח ממון שבטל ונכלל ברצון הגדול הימנו כמו כשצריך לפזר הון רב או להפסיד כל אשר לו בשביל הכבוד והגדולה או להצלה ופיקוח נפשו ונפשות ב\"ב וכה\"ג וכך יובן ממש בבחי' מס\"נ בבחי' ביטול כל הרצונות הזרות"],[2500660219,"שמתבטלים ונכללים באור הרצון הגובר עליהם עד שמהפכים להיות גם הם רק לה' לבדו כו' דודאי אין זה הביטול רק מצד המיעוט מפני שהרצון והתשוקה לה' נפלאה ורבה ועצומה ביותר עד שהרצון הזר כלא ממש חשוב ונתבטל במיעוטו כטפה בים וכה\"ג ואע\"פ שהוא בחי' מנגד בטבעו לרצון האלקי מכל מקום נהפוך טבעו כמו הפיכת מים מרים מועטי' במים רבים מתוקים שנהפך טעם המרירות למתיקות או גם כאשר אין הרצון הזר מועט והרצון אלקי גדול ורב הימנו אלא שניהם שוים בכמות כו' אך מצד בחי' התגברות הרצון והתשוקה לה' כשהוא בתוקף ועומק הלב ביותר שאז גם הרצונות הזרים רבים יותר יתבטלו במהותם ונהפכים כולן לה' כמו שנהפך המר למתוק גם אם המר רב יותר אם מעט המתוק מתוק ביותר עד\"מ דבש המתוק ביותר שמרירות הצנון נהפוך למתיקות ג\"כ מצד בחי' התגברות טעם המתיקות שבדבש שגובר עליו כו' וכדוגמא לדבר מ\"ש וישלך עץ וימתקו המים ואע\"פ שהעץ מועט והמים שבמרה רבים ביותר אעפ\"כ נמתקו. ואמנם הנה יובן מכ\"ז שאין זה הביטול נק' בחי' ביטול בעצם מצד עצמו לבד אלא רק מצד התגברות כח המנגד עליו עד שמהפכו כו' וא\"כ אין זה רק בשעה זאת שהכח הגדול הימנו גובר עליו ביותר אבל מיד כשיסתלק האור והכח הגדול הימנו וילך לו אזי חוזר וניעור אור וכח הרצון הקדום המנגד להיות בתקפו ומהותו הקדום ממש כו' וראי' לזה הנה אנו מוצאים בכל בחי' התכללות דבר והיפוכו כמו במר ומתוק או התכללו' ב' יסודות אש ומים וכה\"ג כאשר יבדילו ויוציאו כל אור וכח וחיות אותו הכח הגדול שנתגבר על החלוש ומועט הימנו עד שילך לו לגמרי אז חוזר וניעור אותו הכח המועט והחלוש יאמר גבור אני כו' ונמצא הוא במציאותו כמו שהיה בתחלה ממש בלי שינוי המהות כלל וכלל שהרי אם יוציאו ויבדילו כל טעם המתיקות של הדבש וכה\"ג ישאר חלק טעם המרירות של הצנון כמו שהיה בתחלה ממש וכן גם מים המתוקים שכבר המתיקו למים המרים כאשר יוציאו ויבדילו כל חלקי המים המתוקים נמצאו מציאת מים"],[2500660220,"המרים המועטים כמו שהן כו' וכן בהתכללות אש ומים כאשר יוציאו מן העץ המורכב מב' יסודות אש ומים כל חלקי האש כאשר גבר בו יסוד האש כבר נשרף כל חלקי יסוד המים והיה לאש מ\"מ בהסיר כל חלקי האש לגמרי ימצאו בו מציאות כל חלקי המים בשלימות כידוע וכן יובן בביטול והתכללות הרצון הזר בשעת התגברות הרצון האלקי עליו שזהו רק בשעה זו לבד אבל מיד כאשר יסתלק אור וכח הרצון האלקי אז כח הרצון הזר חוזר וניעור כמו שהיה תחלה כו' ואעפ\"כ נקר' בשם מס\"נ ממש מאחר שבאות' השעה שגבר אור הרצון האלקי דנה\"א נתבטל כל כח הרצון הזר ונהפוך גם הוא להיות מואס ברע ובוחר בטוב כו' אך אין זה מס\"נ בעצמה ומהותה רק שזה הנק' מסירת הרצון לבד שהרצון הזר הנמשך מן הנפש נתבטל ונמסר לה' ולכך נק' בל' מסירה כדבר הנמסר מרשות לרשות שנשתנה ממהות הראשון לפי אותה השעה שנמסר ברשות אחר כי הרי בהיותו נמסר ברשות אחר נהפך להיות שם כאחד מחלקיו העצמי' אבל יוכל להיות שינוי הרשות שיצא מרשות זה לרשות הראשון וכן ע\"ד דוגמא ענין מסירת הרצון שהרצון הזר יצא מרשות הרבים עולם הפירוד ומסר א\"ע לרה\"י עולם היחוד כו' דאע\"פ שבשעה זו שנמסר לעולם היחוד הרי הוא ביטול גמור בחי' ביטול המהות הראשון כנ\"ל אבל הרי יוכל להיות שינוי הרשות דהיינו כשמסתלק הרצון האלקי שנמסר לרשותו אז חוזר ונכנס לרשות הראשון שהוא רה\"ר עולם הפירוד כו' בבחי' רצון הטבעי דנה\"ב כמו שהיה קודם לפי שכל ענין מסירה אינו בחי' ביטול עצמי רק דרך מסירה לבד שהוא לפי שעה מצד רשות המושל וגובר עליו אז באותה שעה לבד כו' וד\"ל:\n(ח) <b>והנה</b> יש עוד בחי' מסירת נפש שלמעלה הרבה ממס\"נ הנ\"ל שאין הכוונה בו ענין מסירת הרצון לבד שזהו מסירת הרצון לרשות רצון הגובר עליו כנ\"ל אלא הכוונה בו הוא ענין מסירת הנפש בעצמה דוקא ולא מסירת הרצון לבד ואע\"פ שמבואר במ\"א שהרצון נק' נפש כמו היש"],[2500660221,"את נפשך אין נפשי כו' אין זה ערך כלל וכלל לגבי המהות של הנפש עצמה שממנה נמשך כל רצון ותשוקה כידוע כו' ולהיות כן לא יתכן בזה ענין מלחמה ונצוח של ב' רצונות והרצון א' גובר על היפוכו המנגדו עד שמהפכו כו' מאחר שהנפש עצמה הוא מקור כל בחי' רצון ותשוקה כידוע א\"כ מובן דלגבי עצמות הנפש ממש שוה רצון הגדול עם רצון הקטן מאחר שהנפש מושללת מבחי' רצון לגמרי רק שממנה נמשך מקור לכל רצון א\"כ אין הפרש בין רצון גדול לרצון קטן כלל וכלל. ולא שהרצון הגדול הוא חלק גדול מן הנפש והרצון הקטן הוא חלק קטן מן הנפש ויש יתרון לגדול על הקטן כו' אחר שאין הרצון חלק מן הנפש כלל כי בחי' עצמותו מושלל לגמרי מבחי' רצון כו' וא\"כ יובן מעלתו ומדריגתו דמס\"נ בעצמה ומהותה שזהו למעלה הרבה מבחי' מסירת הרצון לבד והענין הוא דזהו בחי' ביטול בעצם מצד עצמו ומהותו כשהוא עצמו נהפך ולא מצד התגברות כח אחר המנגד עליו כלל רק מצד בחי' עצמותו ומהותו הרי נתבטל כל בחי' טבע ומהות עצמותו לגמרי מכל וכל בבחי' ביטול בעצם שלא יתכן בזה סיבת מלחמה וניצוח כלל כו' והוא בחי' אהבה דבכל מאדך שהוא מס\"נ האמיתי שאחר מס\"נ דבכל נפשך כנ\"ל. ולהבין שורש ענין דבר זה לתכליתו הנה יש להקדים ענין א' והוא הנקרא בחי' ההשתוות כידוע והענין הוא להיות שאנו רואים שהעיקר והמקור הכולל כל הדברים שבעולם הם ב' דברים עונג וצער וזהו הכולל כל הדברים שהנפש נמשך אחריהם כידוע דכל עיקר המשכת הנפש בדבר מה אינו רק מפני בחי' העונג שיש באותו דבר והעונג ההוא הוא הגורם את הרצון והחפץ שרוצה וחפץ בזה ואם לא העונג שהיה לו בזה לא היה רוצה כלל באותו הדבר כידוע ומטעם זה אנו רואים שכאשר יעשו לאדם דבר מה שהוא נגד רצונו יתפעל בצער גדול בנפשו והוא הנקרא בשם יסורים לנפש ולכאורה זהו פלא גדול מאין יבוא התפעלות הצער הזה כ\"כ עד שיצר לו לגרוע האור והחיות שבעצמות הנפש"],[2500660222,"בגירעון גמור ונקרא רוח נדכא או רוח נשברה וכידוע והלא הנפש רוחנית היא ואיך שייך בה שבירה כו' וזה הגירעון בא רק ממה שעושין נגד רצונו והרי עיקר הרצון אינו מבחי' עצמות הנפש רק הארה בעלמא כידוע אלא מוכרח לומר לפי שבחי' אור העונג הוא מאיר ובא בעצמות הנפש ע\"כ הצער שהוא היפוך העונג והרצון עושה גירעון האור וכידוע דנגע אותיות עונג כו' והנה אנו רואים חילוק מדריגות רבות זו למעלה מזו בענין גירעון האור על ידי הצער שיש צער ויסורים שאין נוגעין אל הנפש כ\"כ עד שיוכל לבטל הצער בקל מאוד כמו דאגה וצער שבלב איש ישיחנה ועל ידי הדיבור יוצא הצער והדאגה או על ידי כלי שיר ושחוק או איזה סיבה אחרת כמו בטיול ותענוגים אחרים וכהאי גוונא ויש צער ויסורים שנוגעים אל הנפש ביותר עד שלא יוכל לבטל ולהסיח דעתו ולבו בשום דבר בעולם וכל זה אינו אלא מפני ששורש הצער והיסורים הוא היפוך העונג והרצון לבד כנ\"ל ע\"כ תלוי ריבוי ומיעוט הצער לפי ערך ריבוי ומיעוט העונג והרצון שאם העונג והרצון רב ביותר עד שפנימי' נפשו מתענג ומשתעשע אזי כשעושין דבר המנגד מאד לאותו העונג והרצון יהי' הצער והיסורים מזה רב ביותר לעשות גירעון גדול ביותר כי ממש כפי ערך רוב העונג כן ירבה הצער בהעדר אור העונג במדה ושיעור ולא יוסיף הצער על העונג ולא ימעט ממנו אלא המה כשיעו' ומדה א' מאחר שאין הצער בא רק מצד גירעון והעדר העונג כו' ע\"ד דוגמ' הצער בהיזק הון רב ירבה הצער לפי ערך ריבוי העונג בהון רב זה ובהיזק ממנו מעט ימעט הצער לפי ערך מיעוט העונג בו כו' וכן בשאר תענוגי' הגדולי' יותר כמו תענוג הכבוד והגדולה לפי ערך כן ירבה הצער בהעדר ונפילת הכבוד וכו' וכן בתענוג תאות המשגל לפי ערך גודל התענוג כן ירבה הצער בהעדרו כמו מעשה באחד שהעלה טינא בלבו כו' וכה\"ג א' כד ארי' ואריותא קיימין כו' וכן יש עונג ורצון מצומצם ביותר עד שההיפוך שעושין לנגד הרצון אינו נק' יסורים כ\"כ"],[2500660223,"רק בצמצום ומיעוט הצער ולפי ערך מיעוט וצמצום העונג והרצון כו' אך גם שהרצון והעונג אינו עצמות הנפש ממש אלא הארה בעלמא ממנה כו' מ\"מ הצער עושה גירעון אור בעצמות הנפש מפני שכמו שהעונג מגיע בעצמות הנפש כן הצער בהעדר העונג מגיע בעצמות הנפש עד שנק' רוח נשברה ונדכ' וכה\"ג וד\"ל (וכמ\"ש במ\"א שהנפש עצמה משתעשע בעונג זה הפרטי כו' וכידוע בענין ג' סעודות דשבת כו' וד\"ל) אך הנה אנו רואין שיוכל להיות באדם בחי' ההשתוות דהיינו שגם בדבר שהנפש מחמדתו כמו כל התענוגי עוה\"ז כממון וכבוד ושאר חמדות ותאות עוה\"ז אין לו בהם חפץ כלל וכלל אדרבה מואס בהם בתכלית כאלו שנאה נפשו בבחי' טבעית ועצמיות וזהו מעלה ומדרגה יתירה שאין למעלה הימנו ונק' הפשטות הגשמיות כמו צדיקים גמורים שנפשם מושלל ומופשט מכל רצון ותשוקה לגשמיות עוה\"ז הגם שזהו נגד טבע נפש הבהמית אבל נתבטל הטבע הראשונה בבחי' ביטול לגמרי ונעשה כמו טבע אחרת למאוס בתענוגי עוה\"ז לגמרי ואמיתת דבר זה לא יבורר לתכליתו כ\"א מן ההיפוכו דוקא שהוא הצער היפוך העונג הבא מכחו במדה ושיעור א' דוקא כנ\"ל דהיינו אם כשעושין לו דבר מה בענייני עוה\"ז שהוא נגד רצונו יתפעל בצער ויסורים הרי בהכרח שיש לו בדבר זה איזה רצון ותענוג שלפי ערכו יש לו צער בהעדר הרצון והעונג כנ\"ל א\"כ זה האיש לא נתהפך ונתבטל אצלו ביטול גמור לטבעי' הגשמיות ולא נק' מופשט מגשמיי' עדיין ע\"ד דוגמא כשיהי' לו היזק ממון או נפילה בכבוד וכה\"ג יתפעל בצער נפשו הרי בהכרח שיש לו רצון ותענוג בממון וכבוד וכה\"ג בשאר חמדות ותאות עוה\"ז כו' ולפי ערך הצער אם רב או מעט כך מוכרח ערך התענוג והרצון שיש לו בממון וכבוד וכה\"ג והגם שיש צדיקים שמתפעלים בצער על העדר כבוד ושאר חמדת עוה\"ז אבל בקל מאד יתבטל הצער כי לא נגע עד הנפש כ\"כ מזה מוכרח שאין להם בחי' רצון ותענוג גדול בזה רק מעט מזעיר ע\"כ הצער מעט ובקל יתבטל מאחר"],[2500660224,"שבא הצער במדה א' ממש לפי מדת העונג כנ\"ל ויש צדיקים גמורים שאינם מתפעלים כלל מן ההיזק ממון או נפילת הכבוד וגם בגירעון שפע דבני חיי ומזוני מקבל באהב' ורצון גמור כידוע א\"כ מוכרח שאין להם שום רצון ותשוקה אפילו מועטת בענייני עוה\"ז ע\"כ לא יתפעל בצער ויסורים כלל וכלל מן ההיפוך בהעדר כו' עד שבכל הדברים שבעוה\"ז גם כאשר רוצה לדבר מה אם עושין לנגד רצונו לא יקפיד כלל כי אינו מצטער כלל מהיפך רצונו כי הרצון הזה אינו בא בבחי' פנימית כלל רק בבחי' חיצוני' מאד עד שלא יפול ענין יסורים וצער בהיפוכו משא\"כ כשמצטער אפי' קצת מן ההיפוך רצונו אז בהכרח שיש לו רצון פנימי לפי ערך הצער הזה כנ\"ל ונמצא שצדיקי' גמורי' שמתפשטי' מכל רצון בגשמיות עוה\"ז גם כשעושין לנגד רצונם לא יצטערו כלל מפני שאין להם חפץ ורצון כלל בתענוגי עוה\"ז וזהו הנק' בחי' ההשתוות ששוה אצלו הן ולאו ממש בהשוואה א' כמו עושר וכבוד שבהעדרם לא יצטער כלל מפני ששוה אצלו הן ולאו וכמו שאמר ה' נתן וה' לקח א\"כ שוה הנתינה עם הלקיחה ולכך צריך לברך על הרעה כמו שמברך על הטובה ממש בהשוואה א' כו' וד\"ל:\n(ט) <b>והנה</b> שורש ענין ההשתוות הנ\"ל בא מצד שניטל ונלקח שורש ומקור חיי נפש הבהמית שזהו בחי' מקור הרצון הזר שלה עד שלא נמשך ממנה שום רצון זר כלל ואדרבה מואס ברע כנ\"ל שלזה לא יהיה לאדם יסורי' כלל ממה שיעשה כל אדם נגד צרכי טבעו ולכך הוא שמח ביסורים ומקבל באהבה גמורה כנ\"ל. והנה שורש ומקור הרצון הזר הוא בחי' חיה יחידה שבנה\"ב המלובשת בגוף החומרי כידוע וכאשר נהפוך הוא ממילא אין לו חפץ כלל בחמדת עוה\"ז כנ\"ל ובזה לא שייך ענין מלחמה כלל דהנה כאשר עדיין מאיר בנה\"ב מבחי' חיה יחידה אז נק' נסיון כאשר מהפך ומבטל הרצון הזה מצד התגברות הרצון אלקי כמו והאלקים נסה את אברהם שישחוט את בנו יחידו"],[2500660225,"בעבור רצון אלקי וכה\"ג וכל כיוצא בזה הוא הבא בדרך נסיון כמו לנסותכם את אשר בלבבכם הישכם אוהבים כו' דמשמע שבנסיון זה יוכל להיות דבר והיפוכו והוא בחי' מלחמה דנה\"א עם נה\"ב מצד בחי' ההתלבשו' בבחי' א\"פ דוקא שהרי לפעמים יגבר הנה\"ב כו' אבל מעלה ומדריגה שלמעל' מבחי' הנסיון הוא ענין דבר מוחלט שאין בו ספק כלל אשר ע\"כ לא יצטרך להביאו לידי נסיון כלל והיינו כאשר נהפך בחי' מקור כל רצון זר שבנה\"ב שאין זה מצד מלחמה כלל וכלל רק מצד עצם ביטולו שנהפך לטבע אחרת כו' כנ\"ל וזה א\"צ נסיון כלל וד\"ל. וז\"ש מיד כלב יחידתי בחי' יחידה שבנה\"א שמהפך לבחי' יחידה שבנה\"ב ולא מצד מלחמה ונצוח כלל אלא ממילא נכלל ובטל (כמ\"ש בע\"ח דבחי' כתר דקליפה בטל יותר כו' ושרש הדברים משום דמ\"ש את זה לעו\"ז עשה כו' היינו רק בבחי' א\"פ לבד אבל בבחי' מקיפים הרי נכלל מקיף דקליפה בהתכללות גמור יותר מבחי' א\"פ שלהם כמ\"ש במ\"א באריכות וד\"ל). וזהו הנק' בחי' ביטול בעצם שאינו בא מצד מלחמה כלל והוא הנק' מס\"נ הבהמית שאין כוונה על הארת הרצון שנמשך ממנה בלבד אלא על מהותה ועצמותה דוק' דהיינו שהמהות והעצם בטל מעצמו בבחי' ביטול עצמי שנק' ביטול לגמרי ולא ביטול הרצון לבד ואין זה תלוי כלל בסיבות התגברות הרצון האלקי שזהו באותה שעה של התפלה לבד כנ\"ל ואח\"כ חוזר וניעור כמקדם אלא ביטול זה להיותו בחי' עצמיות ע\"כ מאליו ומעצמו יבא ולא יפול בו שינוי כלל להשתנות מרצון לרצון אלא הוא תמיד בהשוואה בלי שינוי כלל וזהו הנק' בחי' יחידה שלמעלה מבחי' הארת רצון בפרט אלא היא בחי' העצמי' ההיולית שהוא מקור כל בחי' רצון כנ\"ל שהנפש עצמ' מושללת מבחי' רצון כו' וכאשר עצמו' הנפש מתבטל ביטול עצמי אז ממילא לא יוכל להיות המשכת רצון זה שלא לה' רק לה' לבדו רצון א' פשוט בתכלית שאין בו הרכבה ותמורה ושינוי וזהו הנק' התפעלו' העצמית דהיינו מסירת הנפש עצמה מכל וכל כו' כמ\"ש כלתה נפשי כו' וכן מ\"ש כל"],[2500660226,"עצמותי תאמרנה כו' כל בחי' העצמיות כו' אשר ע\"ז לא שייך בחי' רצון ותשוק' שהרצון והתשוק' הוא דבר נבדל מן העצם כו' אלא הנפש עצמה בטילה ונכללת ונדבקת תמיד באלקים חיים בלתי שינוי לעתים עד שיצטרך לחדש ולקשר א\"ע ברצון ותשוקה מחדש אלא בקשר עצמו הזה מעצמות נפשו קשור' ודבוקה ולא יצטרך להתקשר עוד הפעם מאחר שאין בו נפילה ושינוי להיותו בחי' העצם כו' וכמו שא' רשב\"י בחד קטירא אתקטרנא כו' וכמ\"ש במקום אחר וכך יובן ענין האבות שהן המרכבה בחי' ביטול תמידי דוקא מטעם שהוא בחי' ביטול עצמי מעצם הנפש כו' וכה\"ג היה בשעת מ\"ת כשאמרו נעשה ונשמע דהרצון של השמיע' מסתעף מבחי' התפעלות העצמו' דזהו נעש' כל אשר נשמע כו' וכמ\"ש במ\"א וראי' לזה דכל רצון כלא ממש חשיב לגבי בחי' העצמיו' הנ\"ל מבע\"ת כראב\"ד וכה\"ג בכל עי\"ת דגם קל שבקלי' שעבר על כל התורה כו' מתפעל בתשובה שלימה לבכות בעי\"ת כידוע וזהו מצד בחי' יחידה העצמית שבו שלא הוטמאה בטומאת עונות שלו כי כל עונות וחטאים באין מצד בחי' הרצון והתשוקה דנה\"ב כשגוברין על הרצון דנה\"א כו' אבל כלא ממש חשיבי לגבי העצמו' כו' ולזאת גם לאחר שמושקע בכל רע יש ביכולת בחי' יחידה העצמי להחזירם וזהו התפעלות הבכי' בעי\"ת בלא טעם ודעת כו' (וכידוע בבע\"ת א' שמתו בניו הנולדים מחטאיו באותה השעה שבכה במר נפש עד שנתעלף כו' וגם שנתלבשו בגופים כו' וד\"ל לפי שכל הרצונו' החומריות הן רק האר' בעלמא מעצם הנה\"ב וכאשר עצם נה\"ב עולה עולין גם הם ונכללים עמה כניצוץ בשלהבת כו' וז\"ש מיד כלב יחידתי כנ\"ל וד\"ל). והנה כאשר האדם עובד ה' בבחי' יחידה שהוא בחי' העצמי כנ\"ל אז לא שייך בחי' מלחמ' דהיינו גם לאחר התפל' בהלוכו כל היום בשוק בגיא צלמות לא אירא רע כלל כי לא יגורך רע כתיב וכהמס דונג כו' והוא ענין הטעם של מדריגות הפשטת הגשמיות שבצדיקים גמורים כנ\"ל וזהו ג\"כ ענין שורש בחי' ההשתוות הנ\"ל לפי שנלקח"],[2500660227,"מקור כל רצון זר כו' כנ\"ל שלזה א\"צ להביא בנסיון כלל כנ\"ל ואדם כזה הוא בצלם אלקים ממש מפני שהוא בחי' אלקות ממש שבחי' יחידה שלמעלה מבחי' חיה שבאה בבחי' מקיף לפנימי כו' אלא דבוקה למעלה באלקות בתמידו' וע\"ז א' בזוהר ונפש כי תחטא תווהא כו' משא\"כ בבחי' חיה שבאה בבחי' נסיון כמו והאלקים נסה כו' שיוכל להיות דבר והיפוכו כו' (וכ\"ז מפני שבא\"ז זלע\"ז חסר בחי' יחידה שהוא בחי' מקיף דמקיף שנק' צל צלו והוא מ\"ש בבואה דבבואה לית להו כו' וכמ\"ש סר צילם מעליהם אז כבהמות נדמו והאדם רודף כו' ולכך ירדוף א' אלף שלא כדרך הטבע כמ\"ש במ\"א וזהו ג\"כ טעם הפיכת מהות ועצם דנה\"ב לבטל עצמיו' שלה בבחי' יחידה דנה\"א כו' וממילא נלקח מקור החיות של כל רצון זר כו' וד\"ל) והיינו ענין מעלה ומדריגה דבכל מאודך שלמעלה ממס\"נ דבכל נפשך כנ\"ל דהנה ואהבת הוא לשון אבה שהוא הרצון המאיר בגילוי במוח ולב בבחי' א\"פ הבא בהגבלה בכלי ואח\"כ אמר שאהבה זו תהיה בכל לבבך ובכל נפשך בכל לבבך בשני יצריך לאכפייא לנה\"ב כנ\"ל ובכל נפשך הוא בחי' מקיף דחיה שנק' בלי גבול של הא\"פ הבא בכלי לבד שממנו בא בחי' אתהפכא ביטול המהות אבל לפי שעה רק בשעת התגברות רצון האלקי דבחי' חיה שבנה\"א ואח\"כ יוכל לחזור כנ\"ל וזהו הנק' מלחמ' וניצוח או נסיון כנ\"ל ואח\"כ א' בכל מאדך בלי גבול בעצם דהיינו כמו שהוא בלי גבול בעצם ולא כמו שהוא בלי גבול לגבי בחי' הא\"פ שבכלי בלבד כו' (וזהו ההפרש בין צ' דצלם ללמ\"ד ומ\"ם דצלם וכמ\"ש במ\"א בענין אך בצלם כו' וד\"ל) והוא בחי' יחידה שאינו מאיר גם בבחי' מקיף לפנימי כו' ואין בה שינוי ונפילה לעולם כנ\"ל ובה לא יתכן לומר בחי' מלחמה כלל להיותה בחי' התפעלו' העצמיו' ממש כנ\"ל באריכות וד\"ל:\n(י) <b>ולהבין</b> כל הנ\"ל בתוס' ביאור בענין מסירת הנפש בעצמ' הנ\"ל שלמעלה ממסירת הרצון לבד כו' הנה אנו מוצאין כדוגמ' זאת וכנ\"ל בענין"],[2500660228,"ההשתוות כו' שאין דבר שעושין נגד רצונו נק' בשם יסורי' וצער כלל כו' גם באהבת רעים הנאמנים באהבתם אשר אהבת האוהב הנאמן לא תוכר אלא ביום צרה שמוסר נפשו ממש עבורו כידוע הנה אנו רואי' שישליך נפשו מנגד להצילו מצרתו ולא יחוס על ממונו ולא על נפשו להביא א\"ע בסכנה וגם יקבל יסורי הגוף עד קצה האחרון וכידוע והנה אנו רואים שיש בזה ב' מדריגו' הא' שגם שמשליך נפשו מנגד בממון ובגוף ומקבל באהבה כל יסורי הגוף רק להציל כו' מ\"מ הרי מרגיש הוא מאד בנפשו כל היסורים והסכנות בגוף ובנפש כו' רק שמפני תגבורות אור האה\"ר לרעהו אשר כנפשו הנה גובר זה על אהבת עצמו וגופו וממונו להשליך מנגד בעבורו להצלת נפש רעהו כו' ובזה יש חילוקי מדריגות הרבה הא' שבא רק בדרך סבלנותו שסובל בנפשו כל הצער והיסורים והסכנות כו' שזהו מורה עוצם ההרגשה בנפשו כל היסורים כו' רק שסובל דרך סבלנות למען אהבה כו' ולמעל' מזה הוא אשר אינו בא דרך סבלנות כו' אלא באהבה ורצון שאינו מרגיש כ\"כ הצער והיסורים כו' מצד ביטולם במיעוט בתכלית לגבי אור האה\"ר שבנפשו לנפש רעהו ואהובו הנאמן כו' אך עדיין אין זה רק כמו ביטול המיעוט ברוב ע\"ד הנ\"ל בבחי' התכללות בבחי' המלחמה של ב' רצונות כשא' גובר על זולתו המנגדו כו' דאע\"פ שנהפך המהות מצד ביטולו במיעוטו לגבי הרוב אבל מיד חוזר וניער כשבטל כח הגדול המנגד וגובר כו' (וכנ\"ל בענין ההתכללות אש ומים באריכות) אך אם נפשו קשורה בנפש רעהו בבחי' עצמיות כאהבת דוד ויהונתן שנא' אהבת נפשו אהבו בבחי' עצמו' כאלו הן נפש א' ממש כו' אז לא ירגיש כלל וכלל ביסורים וצער וסכנה שמקבל ע\"ע בעבור הצלת רעהו ומלבד שלא ירגיש אותם בבחי' צער ויסורים אלא אדרב' יעש' הכל דרך אהבה ותענוג ושמחה גדולה (כנ\"ל בענין מס\"נ העצמי שמזה בא בחי' ההשתוות כו' עד שמברך על הרעה כו') וזהו מצד בחי' התקשרות עצמיות בנפש חבירו עד שכל היסורים והצער בנפשו אינם תופסים"],[2500660229,"מקום כלל וכלל דכלא ממש חשיבי לגבי בחי' העצמי' כנ\"ל באריכות בענין הביטול העצמי כו' ולזאת אין היסורים והצער שמקבל בעבור הצלת רעהו נק' יסורי' כלל כי אינו בא בדרך סבלנות או דרך מיעוט ברוב כו' אלא בדרך תענוג ושמחה מפני שאינו תופס מקום כלל וכלל כו' ומצד שכל צער ויסורים אינו שייך רק בבחי' המנגד לרצון ותשוקה הנק' עונג אבל בחי' העצמי' הוא למעלה הרבה מבחי' עונג ורצון כו' כנ\"ל באריכות ומזה יובן בתוס' ביאור ענין הנ\"ל בבחי' בכל מאודך שהוא בבחי' התפעלות עצמי' דכלא חשיב לגבי כל בחי' רצון כו' ולא יתפס מקו' כלל עד שכל ביטול הרצון הזר שכנגד לא נק' יסורי' אלא תענוג ושמחה כי בביטול עצמו לא שייך לומר שיקבל יסורי' וצער מהעדר הרצון והעונג כו' מטעם כל הנ\"ל וד\"ל:\n(יא) <b>ומכל</b> הנ\"ל יובן שורש ענין פדה בשלום נפשי. דהנה נפשי היינו בחי' נפש האלקי' ויש בה ב' מדריגות הא' כאשר נלחמת עם נפש הבהמי' להתגבר עלי' ולהפכה כנ\"ל שזהו הנק' מסירת הרצון לבד שבא דרך מלחמה וניצוח כמו בשעת צלותא שהוא שעת קרבא כו' כנ\"ל באריכות והוא בחי' אהבה דבכל לבבך ובכל נפשך כו' והמדרגה הב' הוא בחי' בכל מאדך הנ\"ל הנק' מס\"נ בעצמה ומהותה שלמעלה מבחי' מלחמה לגמרי כנ\"ל וזהו פדה בשלום נפשי דהיינו שיש מדריגה גבוה בנה\"א והוא בבחי' יחידה שבה בחי' העצמיו' שע\"י יש לה פדיה בשלום בלא מלחמה כלל וכלל וד\"ל. וביאור הדברים מובן ע\"פ כל הנ\"ל בעיקר ההפרש בין מסירת הרצון הבא ע\"י מלחמה למס\"נ בעצם שבמס\"נ ע\"י מלחמה עכ\"פ שייך לומר ל' צער ויסורי' בדבר שנגד רצונו הטבעי רק שמוסר א\"ע מפני התגברות רצון האלקי כו' וא\"כ אין זה נק' שלום שכל הענין שלום הוא היושב בשלוה שאין לו מנגד כלל וכלל שיקבל צער ויסורים וכאשר אין לו יסורים מכל מה שעושין נגד רצונו אז נק' שלום מפני שהרצון הזר בטל בעצם בלי הרגשת יסורים וצער בנפשו על העדר רצונו הזר כו' וזהו בחי'"],[2500660230,"התפעלות העצמיות דבחי' בכל מאודך הנ\"ל שכל ביטול הרצון הזר לא נק' יסורים כלל אלא תענוג ושמחה וא\"כ אין לנה\"א מנגד כלל כי המנגד בטל בעצם מהותו בלי מלחמה כלל (לפי שבבחי' יחידה מאיר אור אלקי ממש שנק' צלם אלקים כנ\"ל ואז ממילא בטל כל בחי' מקור רצון זר דנה\"ב כהמס דונג כו' כנ\"ל דכלא חשיב כו' וזהו בחי' השלום שלמעלה מן המלחמה כדוגמא דלעתיד שיהיה בחי' ביטול בעצם בכל הברואים גם בבחי' הרע דנוג\"ה מצד גילוי אלקות ביותר וכמ\"ש לא ירעו ולא ישחיתו ארי' כבקר יאכל תבן כו' וכן באוה\"ע כתיב ונהרו אליו כל הגוים כו' בבחי' ביטול עצמם שלא ע\"י מלחמה כלל כמ\"ש ובאו במערות צורים מפני פחד ה' כו' ולא כמו בימי דוד ויהושע שכבשו ע\"י מלחמה כו' וזהו לפי שבמשיח יהיה התגלות דבחי' פנימיות ע\"י בחי' ג\"ר כו' הנק' גלגלתא ששם מאיר מעצמיות אור א\"ס והוא למעלה מבחי' הרצון הפשוט מקור כל הרצון דהיינו שלמעלה מבחי' רצון לגמרי כו' וכמ\"ש בדניאל וע\"י יתיב מלכותי' מלכות עלם כו' בלי שינוי כלל וכמ\"ש במ\"א בענין ע' שנין דדוד כו' שזהו עיקר ההפרש בין דוד למלכא משיחא וע\"ז אמר דוד פדה בשלום נפשי נפש דוד כמו שיהיה לע\"ל בבחי' ג\"ר דע\"י וא\"ק כו' כמ\"ש וגבה מאד שהוא בחי' בכל מאודך הנ\"ל וד\"ל) משא\"כ במסירת הרצון ששייך עכ\"פ לשון יסורים לנה\"ב אין זה שלום גם לנה\"א כי גם שנה\"א עצמה מושללת מכל בחי' רצון זר בלי הרגשת יסורים כו' אבל גם טורח מלחמה זאת להפוך גם לנה\"ב בכלל יסורים יחשב לנה\"א כי יש לה מנגד עכ\"פ רק שמהפכו (ועוד שבהתאבקות המלחמה בהכרח נתלכלך הנה\"א קצת בלבושי' צואים דנה\"ב עד שתהפכנה כמשל המתאבק עם המנוול וכן כמו בגדים שמבשל כו' כנ\"ל בענין הבירורים שהמברר מתלכלך בלבושים של המתברר כמ\"ש וכל מלבושי אגאלתי כו' וד\"ל). וזהו ענין הפדיה כמ\"ש פדה בשלום נפשי כו' כמו פודה ומציל שנה\"א ניצלת מבחי' המנגד דנה\"ב בדרך שלום בלא מלחמה כלל כי המנגד בטל בעצם"],[2500660231,"כנ\"ל וכמו\"כ מ\"ש בידך אפקיד רוחי כו' ר\"ת בא\"ר שהוא מס\"נ העצמי כנ\"ל שע\"ז אמר פדית אותי מן החיצונים בדרך שלום בלא מלחמה כי מתבטלים לגמרי (וז\"ש וידעת כי שלום אהלך כו' יהי שלום בחילך שלוה כו' וכה\"ג מ\"ש ורב שלום בניך שת\"ח מרבים שלום וכן ענין עושין שלום בפמליא של מעלה שכ\"ז ע\"י בחי' מס\"נ העצמי שהמנגד בטל בעצם וא\"צ מלחמה כלל וכמ\"כ ע\"י עסק התורה דבחכמה אתברירו בבחי' ביטול הרע בעצם כמו לע\"ל דכתיב וראו כל בשר בחי' ראיה דחכמה כו' וידע כל פעול כו' וכה\"ג היה בימי שלמה שכל חכמי הגוים נתבטלו בעצם לגבי חכמת שלמה שלא ע\"י מלחמה ע\"כ נק' שלמה כי שלום היה בימיו כו' וכמ\"ש במ\"א וד\"ל) משא\"כ ע\"י מלחמה כמ\"ש קומה ה' ויפוצו אויביך בשעת המסעות בנסוע הארון כו' דגם שכהמס דונג כו' כמ\"ש יאבדו כו' אויביך ה' יאבדו כו' הרי עכ\"פ נק' אויבי ה' רק שנכנעו בתכלית בהיפוך המהות כו' אבל דרך שלום הרי נעשים אוהבים גמורים ולא נק' אויבי ה' כלל וא\"צ איבוד כלל אדרבה כתיב אז אהפוך אל עמי' כו' ונהרו אליו כל הגוים כו' ועמדו זרים כו' והיו מלכים אומניך וכה\"ג) ועד\"מ כאשר נפטר אדם משונאו בדרך שלום שנהפך לאוהב מצד עוצם הביטול האמיתי כדוגמא שהיה ביעקב עם עשו כדכתיב וירץ עשו לקראתו וישקהו כו' (ותחלה נאמר ויאבק איש עמו זהו שרו של עשו למעלה ואח\"כ למטה ממילא נהפך לאוהב לכך וישקהו כו' וד\"ל וז\"ש עמשא לדוד לך דוד כו' שלום שלום כו') אך עדיין צריך להבין למה צריך פדיה מאחר שלא יש בחי' מנגד כלל וכן ענין פודה ומציל וכתיב ופדויי ה' ישובון פדיי' זו מה היא אמנם הענין ידוע שמצד שורש האחיזה דקליפה בסיטרא דקדושה צריך ליתן להם פדיון שהוא דבר קטן תמורת גדול כמו ונתנו איש כופר נפשו כו' וכמ\"כ באמה העבריה שנא' ואם לא יעדה והפדה וכידוע דהנ\"א נק' ברתא דמלכא וז\"ש וכי ימכור איש את בתו לאמה להפוך לנה\"ב לא תצא במס\"נ כצאת"],[2500660232,"העבדים בחי' נפש דנוג\"ה אלא ביעוד או פדיי' כמ\"ש פדה בשלום נפשי כו' (ודוגמא לדבר שילוח השעיר לעזאזל כו' וכן כתיב והוא יפדה את ישראל כו') פדיה זו כדי שלא תתחבר הנה\"ב עם הנ\"א בעלותה למעלה כו' משום שנא' שלום שלום לרחוק ולקרוב לרחוק שנעשה קרוב כו' (אך ע\"י השלום שהוא ההתחברות לפי שעה בזאת יפדה לאשתאבא בגופא דמלכא כו' לבדה ואין זר אתה כו' וד\"ל) ודוגמא אמיתי לבחי' מס\"נ בעצם שאין יסורים כלל בהעדר כל חיי נה\"ב כו' הנה אנו מוצאין בי' הרוגי מלוכה כמו ר\"ע שיצא נשמתו בא' הרי גם ביסורים קשים כמסרקות של ברזל לא הרגיש לבחי' יסורים כלל בשעה זו שהיה מאריך באחד שאם היה מרגיש לא הי' נשמתו מארכת באחד עד שתצא ותוכלל באחד כו' וז\"ש ר\"ע מתי יבא לידי ואקיימנו שזהו מס\"נ בעצם כי לא האמין בעצמו באמרו בכל מאדך על בחי' בטול הרצון לגמרי עד שלא ירגיש בכל יסורים שבגוף שזהו הנק' שלום כנ\"ל עד שיבא לידו מס\"נ בפ\"מ דוקא וכך היו כל הרוגי מלוכה שלא הרגישו צער בנה\"ב שלהם מן ההריגה כי מס\"נ שלהם היה בשמחה ותענוג מצד ההעדר תפיסת מקום כל תענוגי עוה\"ז כו' לפי שאין להם רק רצון א' ולא ב' רצונות כו' כנ\"ל וזהו עיקר יתרון מעלת מס\"נ שלהם על כל מס\"נ בפ\"מ של זולתם הגם שכמה צדיקי עולם נהרגו על קידוש השם אך ורק עשרה הרוגי מלכות אין כל ברי' כו' כמ\"ש בע\"ח דמעלין מ\"ן לאו\"א כו' עד ימות המשיח כו' וכמ\"ש במ\"א וזהו פדה בשלום נפשי מקרב לי שלא יהיה קרבא ומלחמה שהמלחמה עושה קירוב לפי שעה כו' כמשל המתאבקים יחד כו' וזהו מקרב לי לשון קירוב ולשון מלחמה ולכך נק' מלחמה קרבא כו' אלא בדרך שלום שהוא בחי' מאדך שהוא בחי' מס\"נ בעצם שנה\"ב ג\"כ תבטל בעצם כנ\"ל ולא שתתחבר עי\"ז עם נה\"א דא\"כ הדרא קושיא לדוכתי' שנעשה קירוב ע\"י השלום הזה יותר מע\"י המלחמה אך הקירוב הזה הוא קירוב אמיתי כאוהבים נאמנים שאחד מתכלל ומתערב בזולתו כו' ואעפ\"כ אחר השלום הזה נפרדת"],[2500660233,"הנ\"א ע\"י פדיה שה' פודה אותה כנ\"ל וכמו שאמר אברהם ללוט הפרד נא מעלי' כו' שבוודאי כשמיכאל כה\"ג מקריב נשמות ע\"ג המזבח לא יתערב דבר זר בהקרבה זו ובפרט שאור כו' :\n(יב) <b>כי</b> ברבים כו' הנה זהו נתינת טעם גדול על תחלת דבריו שאמר פדה בשלום נפשי ומפרש ואזיל ואמר מפני מה פדה בשלום ולא במלחמה כי ברבים כו' פי' ברבים בתוך רבים בחי' המקיף דיחידה שנק' מקיף כללי שכולל לכל מקיפים פרטי' כו' ופי' ברבים מה שגנוז ונעלם בתוך רבים שהוא בחי' היותר כללי שמקיף על כל כללותם בשוה ולא בדרך פרט שיהיה חילוק מדריגות כמו במ\"ת דכתי' ויחן ישראל לשון יחיד וכן ברכנו כולנו כא' כו' והוא בחי' גלגלתא בחי' ג\"ר כח\"ב שכולל כל פרטי פרטיות נש\"י שהן בציור קומה שלימ' והאר' זו מאיר בכל יחידי סגולה שבכל דור ודור כו' שזהו בחי' משה שאמ' ת\"ר אלף רגלי העם אשר אנכי בקרבו כו' ס\"ר דעות כל אחד לפי השגתו וכפי רצונו המאיר מבחי' חי' ואהבה דבכל נפשך אבל בבחי' יחידה מקיף למקיף כולם שוים ונק' איש אחד וכמ\"ש ויחן ישראל בחי' גלגלתא כו' שהוא למעלה מבחי' רצון לגמרי שלכך אמרו נעשה ואח\"כ ונשמע כו' כנ\"ל ובזה לא שייך בחי' מלחמה כלל כנ\"ל ולזה אמר הטעם כי ברבים הכולל כל ס' רבוא היו עמדי שהוא בחי' הארת עצמי' אא\"ס ב\"ה שבגלגלתא שנק' כתר הכללי ע\"כ פדה בשלום נפשי דכללות נש\"י שלא יצטרכו למלחמה כלל וד\"ל. אך לכאורה סותר סיפא לרישא דברבים בתוך רבים דוקא והיה עמדי לשון יחיד דוקא ועוד דברבים מה שגנוז בהעלם בבחי' מקיף והיה עמדי בבחי' גילוי אך הענין הוא משום דאותה הארה הכללי דבחי' יחידה שכולל כל נשמות ישראל דקומת המל' (בבחי' צ' דצלם הנ\"ל) מאיר ביחידי סגולה שבכל דור שנק' ראשי אלפי כו' בחי' כללי' לפרטי' נש\"י ולזאת לא נמצא מעלה ומדריגה גבוה כזאת דמס\"נ בעצם הנ\"ל רק בעיני העדה (כעשרה הרוגי מלוכה"],[2500660234,"הנ\"ל) שהן כללים של כל פרטי ס\"ר דעות שמברכין עליהם ברוך חכם הרזי' וכה\"ג לפי שבחי' מקיף דיחידה הנ\"ל אינו מאיר רק בבחי' ג\"ר דחכמה שנק' ראש ומוחין ובכללות דג\"ר דחכמה יותר מאיר כידוע דפנימיות אבא הוא פנימיות ע\"י שהוא בחי' משה ומשיח כו' כמ\"ש במ\"א וד\"ל וזהו כי ברבים שבהעלם בחי' מקיף הכללי היה עמדי לדוד שהיה ראש דכנ\"י בגילוי כמ\"ש משה אשר אנכי בקרבו כו' וד\"ל. אך אין המקרא יוצא מידי פשוטו דמשמע שמצד שהיה עמו ברבים דוקא לכך פדה בשלום נפשי וזהו מטעם שאמרו אכל בי עשרה כו' ואפי' משה היה צריך להתפלל בעשרה והיה הפרש בתפלתו ביחיד לתפלתו בציבור כו' מטעם הנ\"ל דהנה הטעם דבבחי' ג\"ר דחכמה דוקא מתגלה מה שבתוך רבים בהעלם מקיף הכללי הנ\"ל לפי שנא' ה' בחכמה כו' בחי' פנימיות חכמה שהוא ביטול היש לאין כמו שהוא בבחי' אין ממש ולא כמו שנתפס בהשגה אנושית בשכל וסברא גופניות אלא בבחי' ביטול גמור שהוא אין עוד באמת לאמיתו כו' שאין זה אלא בחי' מס\"נ העצמי' הנ\"ל ולא כמו שהוא בבחי' א\"פ דבנפשם לבד כנ\"ל וע\"כ מי שיש לו מס\"נ הזה גם בבחי' חכמה שבו הוא נבדל בערך והן כמו עיני העדה הכוללם כו' וכללותם הראשון הן ל\"ו צדיקים שבכל דור דחזו אפי שכינתא בכל יומא פי' חזו בראי' דפנימיות החכמה וכמו לעתיד כו' (וטעם מספר ל\"ו משום דחכם הרזים כולל ס\"ר היינו ופ\"ו והן ד' מוחין חו\"ב וחו\"ג שנחלקים לל\"ב חדרים כו' וד\"ל) וכמו לעתיד דכתי' וראו כל בשר כו' בחי' ראי' דחכמה אבל הוא בחי' פנימיות דחכמה שהוא בבחי' אין האמיתי כמו שהוא כו' כנ\"ל ולפי שבחי' מקיף דיחידה הוא העיקר המהוה לכל האורות מקיפים ופנימים וכליהם כו' כידוע ע\"כ גם בהתבוננות נתפס בחי' ביטול היש לאין כמו שהוא כו' מופשט בתכלית מהשגה גופניות כו' משא\"כ באהבה דבכל נפשך שהוא מקיף דחי' לבד כו' וד\"ל:"],[2500660235,"<h3>והיה העטופים ללבן </h3>\n<b>והיה</b> העטופים ללבן והקשורים ליעקב. הנה יש ב' מיני נשמות א' נק' עטופים והב' נק' קשורים כידוע שהנשמות נק' צאן כמו צאן מרעיתי. וכמ\"כ יש ב' מדרגות דעטופים וקשורים במלאכים עליונים וההפרש בין עטופים לקשורים בנשמות יש בזה ב' דברים הא' שמן הנשמות הנק' קשורים יוכל להיות תולדה שהוא בחי' השפעה והריבוי לחוץ ממש ובנשמות שנק' עטופים לא ימצא מהם השפעה וריבוי לבד מה שהוא בעצמו וזהו ובהעטיף הצאן לא ישים והב' מה שמן הקשורים לא יקבלו יניקה החיצונים שבבחי' קליפת נוגה ומן העטופים יסתעף יניקה לק\"נ ומשם לג' קליפות הטמאות לגמרי. ולהבין זה הנה יש להקדים בענין כללות ההשתלשלות הנזכר בע\"ח בענין אבי\"ע שיש בודאי פרטי' רבים בזה שלא העלה בספר ובפרט בענין כללי די\"ס דקדושה וי\"ס דנוגה דמשמע דנוגה סביב לקדושה וסמוך לה מיד כידוע במ\"ש בתקונים בענין להט החרב המתהפכת לשמור דרך עץ החיים שמתהפכת לטוב ולרע דהיינו בחי' נוגה שמעורב טו\"ר חציה טוב כו' והרי היא סמוכה לדרך עץ החיים ממש (וכידוע בפי' נוגה שהוא אור הבולט במקום חושך כאור השמש בענן שהוא הקשת כן מראה הנוגה וכמו וה' יגיה כו') ובאמת זהו כמו דבר פלא ביותר דודאי אין ערך ויחוס כלל בין הקדושה לקליפה ורחוקי' מן הקצה לקצה ממש כידוע ואיך אפשר להיות שבחי' נוגה יהיה בקירוב וסמוך מיד לסט' דקדושה שבהכרח שמקבלת יניקה מהקדושה וזהו דבר שא\"א כלל דהלא ידוע די\"ס דקדוש' הן בחי' אלקות ממש בכל עולם לפי מדרגתו עד י\"ס דעשי' ג\"כ וגם בחיצוניו' דחיצוניות הכלים שלהן מאיר אור האלקי ונחשב בבחי' אלקות ממש (וכידוע בשורש הנשמות שהן בבחי' נר\"נ דבי\"ע הרי גם בחי' הנפש דשרשם בכלים החיצונים דמל' דעשי' נק' חלק אלוה ממעל ממש וכמ\"ש חי ה' אשר עשה לנו הנפש הזאת דגם בבחי' עשיה ה' עשה זאת הנפש וכמ\"ש אף עשיתיו וקאי על הנשמה דוקא לפי ששורש נר\"נ דבי\"ע הוא בבחי' ל' כלים"],[2500660236,"דז\"א פנימי ואמצעי וחיצון הרי מחיצוניות כלים דז\"א הוא בחי' נפש בעשיה בכלל) וא\"כ איך יוכל להיות שיקבל נוגה גם מחיצוני' הכלים דאורות דקדושה האלקי' (מאחר שבחי' האצי' מאיר עד חיצוני' הכלי דמל' דעשי' כנ\"ל) הרי נא' לא יגורך רע טהור עינים כו' וראי' לד\"ז הנה אנו רואים באדם התחתון למטה שכלול מנשמת אלוה דקדושה ומבחי' נוגה כידוע דג' שותפין הן אב ואם ממשיכי' נפש הטבעית שהוא נפש דק\"נ מעורב טו\"ר ולכך הנפש החיונית הטבעית מורכבת מטו\"ר ממש והקב\"ה נותן בו נשמה האלקי' אם מבחי' נפש דעשי' או רוח דיצי' כו' וכמ\"ש וזרעתי את בית ישראל זרע אדם כו'. והנה אנו רואים באדם מאיר בו הנשמה האלקי' במדרגתה בשלימות כמו כאשר מתפלל בכונה שלימה במוחו ולבו במס\"נ באחד וכה\"ג או כשלומד תור' לשמ' ממש וכן בבע\"ת כאשר עושה תשוב' שלימ' בכל לב ונפש (כראב\"ד שיצאתה נשמתו בבכי' וכמו נתן דצוציתא וכה\"ג) אז ודאי לא יוכל לבבו לקבל שום דבר רע אשר שנא ה' ותעב כגזל ועריות וגם לא תאות היתר ותענוגי עוה\"ז המותרי' שבא מק\"נ ולא מג' קליפות הטמאות לגמרי כידוע מאחר שתאות היתר מעורב טו\"ר ויש שרובו רע וגם שכולו היתר יש בו בחי' רע דנוגה כתאות המאכל והמשגל להיתר שאם אינו מקדש עצמו במותר לו ודאי בלי ספק יש בו חום התאוה הרעה ממש הפוגם אור האלקי ומחשיכו (ולא פגם גמור כרע גמור דאיסור ששרשו בג\"ק הטמ' לגמרי) וכמו שבאכילה גסה יתגשם הגוף ויגבה לבו ויבעט ויבא לפריקת עול לחום התאוה הרעה דאיסור ג\"כ כי קרוב זא\"ז בערך ויחוס כידוע וא\"כ ודאי בהכרח מאחר שרע גמור דאיסור מסתעף ממנו יש בתאות היתר זה ג\"כ מבחי' הרע הזה רק שהוא בדקות עדיין וכמ\"כ תאות וחימוד הממון ותאות הכבוד והתנשאות וכל מדה מגונה ככעס וניצוח והתפארות אלא ודאי בעובד ה' בנשמתו בשלימות אמיתתה רחוק לגמרי מתאות היתר בלתי תערובת רע אפי' א' בריבוא רבבות וכמו קדש עצמך במותר בקדוש' יתירה וכמו צדיק אוכל לשובע נפשו"],[2500660237,"וכה\"ג בשא\"ד ואם אין אדם מקדש עצמו כ\"כ ודאי מוכרח שלא האיר אור נשמתו האלקי' לשלימותה ולא היה בו גילוי אלקו' באמת רק מרחוק ה' נראה בנפשו ולבו כו' ולא בתוך תוכו כלל (ואמנם הנה אנו רואים שאדם מתפלל בכונה שלימה בעומק לבו ומוחו או הרהור תשובה בכל לבו כנ\"ל ובמעט רגע ממש הנה לבבו נכון להתפעל ולקבל עונג ולחמוד חמדת תאוה גופנית מתערובת עכ\"פ כמו לכבוד וממון וכהאי גוונא היינו שלא נהפך לבבו כמו בצדיקים גמורים שלבם חלל בקרבם ממש שאין לבבם רק לה' אחד לבדו ובזה יוכל להיות נמשך אח\"כ לקבל דבר זר זולתי אלקות אבל מ\"מ רחוק ממנו חפץ ורצון זר כי לבו ברשותו לאכפייא ולדחות לגמרי כל רצון זר וראי' לזה שהרי יוכל לעמוד על נפשו שלא יחפוץ בכבוד והון וימאסם לגמרי שהרי עומד בנסיון לשמוע חרפתו ולקבל באהבה כל העדר טוב עוה\"ז ולסבול עונו בשמחה כי כלא חשיבי לנגד עומק לבו בקרבת אלקים בתפל' ותשובה וכה\"ג וא\"כ לא יסתעף ממנו בחי' רע לעולם דהנה ודאי זהו דבר שא\"א שיהיה אדם מתפלל בכוונה בלב שיש בזה בחי' גלוי אלקות ממש ובמעט רגע יהיה לבבו נמשך אחר שום דבר רע אפי' בתערובת ואם נמשך לבו לרע כמו שאנו רואים שיוכל אדם להתפעל בכעס ורציחה וגזל או תאות ניאוף ותאות כבוד והשתררות מיד אחר התפלה או מיד שנתעורר לבו בתשובה ודאי שקר גמור עשה בנפשו האלקית והטעה א\"ע וקרוב הוא אל כת הצבועים כו' שעושין במזיד כי מה שמטעה א\"ע בתפלה ותשוב' כמזיד יחשב ממש וד\"ל) אבל מי שלבו ברשותו לאכפיי' כנ\"ל כצ\"ג יחשב אעפ\"י שאין לבו חלל בקרבו בתמידות אבל בעת התפלה ותשובה כמו חלל ממש הוא. והנה מכ\"ז יובן למעלה בשורש הנשמה ושורש נפש הטבעית שבבחי' נוגה דודאי א\"א לומר דמבחי' הקדושה יהי' קירוב ויחוס להסתעפו' ק\"נ מעורב טו\"ר כמו שא\"א להיות באדם שיש בו גילוי אלקות בנפשו ממש שיסתעף לבחי' תערובת רע כנ\"ל וא\"כ ודאי ההכרח לומר דיש בחי' ממוצעים רבים בין בחי'"],[2500660238,"הקדושה לבחי' נוגה דהיינו עד שיסתעף בחי' נוגה מבחי' הקדושה צ\"ל הסתעפות כמה בחי' ומדרגות ממוצעים מהקדושה לפני ק\"נ שמהם וע\"י יסתעף לבחי' נוגה כמו שיש בחי' ממוצע בין ק\"נ לג' קה\"ט לגמרי וכמ\"ש והבדלתם בין הטמא לטהור דנוגה טהור הוא עכ\"פ מרע גמור כך יש בחי' ממוצע בין הקדושה לנוגה (וכמ\"כ גוף ק\"נ ממוצע יחשב בין הקדוש' לקליפה דרע גמור וע\"ז א' והבדלתם בין הטמא ממש לטהור ממש) והוא שמסתעף ומתהוה דבר מהקדושה שהוא בבחי' כולו טוב ולא רע אפי' בתערובת כ\"ש וממנו יסתעף בחי' נוגה שמעורב טו\"ר דהיינו שבחי' הטוב שבנוגה מקבל ממנו ע\"י ממוצעים ואותו הדבר שכולו טוב ודאי רחוק ערכו מערך עצם הקדוש' גם בחי' כלי' החיצונים ומקבל ע\"י ממוצע דוקא וזהו מארז\"ל אין רע יורד מלמעלה כלל גם לא ע\"י ממוצע רק בחי' שכולו טוב שהוא הממוצע הזה שבין הקדושה לבחי' ק\"נ וד\"ל:\n<b>ולהבין</b> ביאור ענין של הממוצע הזה הנה זהו בחי' העטופים הנ\"ל והן נשמות שנק' עטופי' שהן בחי' ממוצעי' בין הקדושה לנוגה והנשמות שנקר' קשורי' הן מבחי' הקדושה ממש דהיינו מבחי' הכלי' דקדושה וכמ\"כ יש במלאכים ב' מדרגות דעטופים וקשורים רק שהמלאכי' הן מחיצוניו' הכלים ונשמות מפנימיות הכלים בכלל כידוע ותחלה י\"ל בבחי' הכלי' דקדושה באדם למטה שיש בו נשמה האלקי' כנ\"ל להיות ידוע בעיקר מהות הנשמה או רוח או נפש שהוא בחי' עצם התפעלות אלקות אם בעונג ורצון או בשכל ומדות הכל הוא בבחי' עצמיות דוקא כמו חוש טבעיות רוח הבהמה דנה\"ט בהתפעלות גשמיות ואמנם במה שנתפס בחי' עצמיו' זאת הן הנה בחי' הכלים מכלים שונים והכלי היא כחומר לצור' לקבל אור האלקי הזה בתוך תוכה ממש בלי שום הבדל ופירוד ביניהן כלל כמו הארת אור האלקי בהתפעלות האלקות במוח הרי המוח בחי' כלי ממש להכילו בתוך תוכו וכן הלב להתפעל באהבה אלקי' ובפחד אלקים וכה\"ג גם בכלי החיצוני' שהוא בחי' המעש' בועשה טוב האלקי הרי כמו טבעיות בכל"],[2500660239,"נפש אלקי מישראל במצות מעשיו' וריחוק מהרע כו' רק שיש בזה מדרגות חלוקות בבחי' נר\"נ כו' אבל בחי' ג' כלים אלה כלליי' לג' מדרגו' נר\"נ בכלל כלי המעשה לבחי' נפש וכלי הלב לבחי' רוח וכלי המוח לבחי' נשמה בכ\"א מישראל שכלול מנר\"נ אם בעשי' או ביצי' או בבריאה כידוע. וכ\"ז נק' בחי' קשורי' שאור האלקי מתקשר ומתקבל בתוך תוכם בג' מיני כלי' אלה (וכמו היכל ה' המה שיש שהן בחי' היכלות) הנק' בחי' קליטה ממש כמו קליטת אור השפע מכל משפיע למקבל כמ\"ש ונתתי משכני בתוככם ממש ודוגמא זו בנשמות העליונות שבג\"ע דיצירה או עשיה בלא גופים שנהנין מזיו האלקי נקר' קשורים שהאור האלקי לבוש ונקלט ונתקשר בתוך תוכם בלתי אמצעי המפסיק כלל וכלל דהיינו שיוכלו כלי השגתם לקבל זיו האלקי ממש בתוך תוכם ולא יתבטלו ממציאותם כלל וכלל אדרבא יעמדו במעמדם ומציאותם דוקא בכל בחי' התפשטות כלים מכלים שונים להכיל ולקבל אור האלקי בגילוי גמור ממש כחומר לצורה ויוכלו בעצמם לקשר אור השפע בתוכם בבחי' קליטה ממש ע\"כ נקר' קשורים כאשה שכורתת ברית לבעלה כו' והן הן עצם הנשמות ששרשם בבחינת כלים די\"ס דקדושה האלקית שאין האור בא בהם במיעוט וצמצום כלל רק כמו שהוא בלי אמצעי כו' וד\"ל. וכמו\"כ יובן במלאכים ששרשם מחיצוניות הכלים דקדושה היינו שנכנס האור האלקי בתוך כלי השגתם ממש בהתקשרות עצמיות ממש בגילוי גמור וכמו שרפים וחיות ואופני הקודש דג' עולמות בי\"ע שהן בבחי' ביטול אמיתי בפנימית נפשם בתמידות לאלקות המהוה אותם כו' והיינו גם עד בחי' היכלות עליונות דקדושה היותר חיצוניות שמשתלשלים מחיצוניות דחיצוניות הכלים דמל' דעשיה או מל' דיצירה שנקרא בתי בראי כו'. אך הנה בחי' העטופים הנ\"ל אין אור האלקי נכנס תוך תוכם כלל ועכ\"ז קרוב בערך לבחי' הקשורים הנ\"ל וכולו טוב ולא רע כלל אפי' בתערובת כ\"ש כנ\"ל. ואנו מוצאים זה בכמה בנ\"א שמייגעים נפשם"],[2500660240,"האלקית בהתבוננות בהשגת אלקות בכל עומק האפשרי גם במופלא ומכוסה מאוד כמו ברזין וסודות בהשתלשלות הפרצופים ולמעלה מעלה לפני ההשתלשלות דקו\"ח כידוע ואינם מתפעלים בנפשם כלל וכלל דהיינו שאין להם כמו חוש טבעי להתפעל בבחי' הרגשה עמוקה בנפשם כלל אע\"פ שהן מבינים ומשיגים בכלי מוחם היטב הדק והוטב בעיניהם תמצית וטעם הענין לתכליתו ולהתאמת אמיתתו לעומקו ותכליתו עכ\"ז אין בהם התפעלות כלל מזה לא במוח ולא בלב כי הענין רחוק מאד מהם בלתי נוגע לעצם מהות נפשם כלל ומרחוק ה' נראה להם בכלי המוח בבחי' הודאת השכל לבד וזהו כמו פלא גדול דודאי מטבע אור הניצוץ האלקי להתפעל באלקות בהרגשה והזזה מקרב נקודת העצמיות כידוע וא\"א לומר שאין להם נשמה אלקית שיש בכ\"א גם בקל שבקלים כידוע בענין המאמר אע\"פ שחטא ישראל הוא וכמ\"ש נשמה שנתת בי וכנ\"ל בענין ג' שותפין כו' אלא צ\"ל שיש חלוקי מדרגות בנשמות ויש נשמות נמוכות שאין בהן התפעלות אלקות בתוך תוכם ממש רק מרחוק לבד כנ\"ל והן הנקר' עטופים והטעם שנקראו בשם עטופים דוקא דהיינו כמו בהתעטף עלי רוחי וכמו תפלה לעני כי יעטוף וכה\"ג דעיטוף זה לשון לבוש כמו המתעטף בדבר שמתכווץ בתוכו להתעלם בו מפני השפלות והבושה בבוא אדם גדול כשר ומלך וכה\"ג והענין הוא מה שאנו רואים באותן נשמות הנמוכות הנ\"ל שאין להם התפעלות חושיים בהשגת אלקות עכ\"ז פועל בהם ההשגה באלקות בחי' השפלות והבושה שהוא הנפילה בעצם שנשפלים מאד בעיניהם (בל\"א ער פאלט אראפ זייער ביי זיך אונ ביהאלט זיך זייער בבחי' הקטנות כו') והיינו מפני שרואים ערך קטנות נפשם שלא יוכלו לקבל ולקלוט אור ההשגה האלקית בתוך נפשם בגילוי גמור אזי נעשה ההשגה האלקית עכ\"פ נפלאה ונשגבה עליהם בבחי' הרוממות והיקר מערכם השפל ונשפלים בעצמם מאד ומתכווצים ומתצמצמים בעצמותם שנק' ביטול עצמיות שלהם ולפי שההשגה האלקית שמשיגים בכלי מוחם"],[2500660241,"נעשה בבחי' מקיף עליהם מלמעלה היינו כמו שמתעטפים בנפשם כמו שמתעלמים בלבוש בבחי' הקטנות וביטול גדול כמו בהתעטף עלי רוחי כו' כאשר תקצר הנפש בעינוי אז תתעטף רוחו עליו ותתעלם בבחי' הקטנות והשפלות וכן תפלה לעני שהוא בשפלו' כי יעטוף רוחו עליו ויקראהו מרחוק בשפלו' והכנעה עצומה וכמו משל תלמיד לפני הרב שמתעטף רוחו בעצמו מפני הבושה והשפלו' כנ\"ל וכ\"ז אינו רק מפני שלא יוכלו לקבל האור האלקי בגילוי גמור בנפשם ע\"כ תתעטף נפשם בעצמם ולכך נק' בשם עטופים וד\"ל. ודוגמא זו מצינו בנשמות עליונות שבג\"ע שיש בהם שמקוצר כלי הקבלה לקבל אור וזיו האלקי בג\"ע בתוך תוכם ממש יתעטפו בנפשם שלא יתבטלו במציאות לגמרי והרי עיטוף זה כמו מסוה דמשה שהי' מצד שלא היה יכול להביט בלתי לבוש כו' כך העיטוף שמתעטף נפשם הוא מצד שלא יוכלו לקבל אלא מרחוק ע\"י עיטוף וזהו כענין לבוש החשמל שמלביש לכל נשמה בג\"ע שלא תתבטל במציאות כמ\"ש במ\"א וכך אותן נשמות השפלות אם היו מקבלים האור האלקי בגילוי בקירוב גמור היו מתבטלין ממציאותן מפני שלא יאיר בהם אור האלקי רק במיעוט אחר מיעוט מאוד עד שא\"א לקבל רק מרחוק מעט מזעיר לבד ואם יתוסף בהן ההארה האלקית לא יתקיימו במעמדם כלל ונמצא שעיקר הטעם שנקר' עטופים היינו מפני שמתעטפים רוחם בעצמותם דוקא מפני בחי' ביטולה בקטנות כלפי מעלה כמו שמתעטף אדם בטלית ומתכסה עצמו בבוא מלך ושר וכמו ברבקה כשראתה ליצחק דכתיב ותקח הצעיף ותתכס וכה\"ג וד\"ל. ויובן זה בתוס' ביאור עד\"מ הידוע בענין א\"פ וא\"מ כמו התלמיד שאינו מבין ומשיג הסברא לתכליתה ועומקה מפני שעמוקה מכלי מוחו שנשאר בבחי' מקיף עליו כידוע. אמנם מפני שאינו מבין עומקה מצד קוצר המשיג תתבטל מחשבתו ונעשה הדבר מרחוק כאילו אינו מבין כלל כי בא לכלל בחי' ביטול וקטנות להתצמצם בעצמו ולהתעלם לגמרי והיינו כענין עיטוף רוח"],[2500660242,"השפלה הנ\"ל בנשמות השפלות שמצד קוצר כלי קבלתם אור אלקי יבא בה בחי' ההתבטלות לגמרי ותהיה בשפלות המדרגה ביותר והוא ענין עוצם ההשפלה וההכנעה אמיתית (בל\"א נישטקייט ער איז גאר נישט בייא זיך מצד אלקות דוקא) לאלקות בבני אדם שמשיגים היטב ואין בהם התפעלות חושיית מצד מיעוט אור האלקי בנפשם וכדוגמא זאת יובן למעלה גם במלאכים העליונים שנקראים עטופים ע\"ד הנ\"ל שאין אור האלקי נכנס תוך תוכם כלל אבל יתעטף רוחם מרחוק בבחי' ביטול ושפלות גדולה והיינו כולו טוב ולא רע אפילו בתערובת כ\"ש דהיינו שתמיד הן בביטול והכנעה זו לאלקות בלי תערובת כלל וכלל וד\"ל. והנה בחי' העטופים הנ\"ל הוא בחי' הממוצע בכלל בין הקדושה לבחי' נוגה שמעורב טו\"ר כנ\"ל להיות שהעטופים הן בבחי' כולו טוב ולא רע כלל מתייחסים אל בחי' הקדושה ומקבלי' מבחי' חיצוניות הכלים דקדושה ומהם יסתעף לבחי' נוגה דוקא. אך י\"ל דמאחר שכולו טוב ולא רע כלל איך יסתעף מזה לבחי' הנוגה שמעורב טו\"ר כמו שא\"א שיסתעף מהקדושה מפני שאין רע יורד מלמעלה כו' כך לא ע\"י הממוצע הזה ג\"כ כנ\"ל. אמנם הנה יש להקדים תחלה ענין ההפרש שיש עוד בין הקשורים לעטופים והוא במה שמן הקשורים יוכל להיות תולדה והשפעה למטה ולא מן העטופים כנ\"ל והענין הוא להיות מבואר למעלה בענין הקשורים שהאור האלקי נכנס תוך תוכם ממש בקשר אמיץ והן נשמות הגבוהות שיש גילוי אלקות בתוכם מקרוב כמו בהתפעלות חושיית כנ\"ל ולא בא בהם האור במיעוט כלל ולא נתבטלו ממציאותם כלל מזה הגילוי אדרבה יעמדו בעמדם כנ\"ל שזהו כמו כל מקבל מן המשפיע בבחי' קליטה דוקא היפך בחי' העטופים הנ\"ל ומאחר שמקבלים בעצמם בבחי' קליטה ודאי שיולידו בבחי' תולדה וריבוי אור ושפע חדשה למטה מהם ולהיות מסתעף מהם מקו' יניקה לתחתוני' תמיד כמשל אשה שמקבל' שפע מ\"ד שתזריע ותוליד או כמו אור הלבנה שתאיר למטה אחר קבלתה אור השמש בעצמה וכה\"ג אבל בחי' עטופים"],[2500660243,"הנ\"ל שאור אלקי בא בהם במיעו' כ\"כ עד שלא יכילוהו כלל וגם במעט שמקבלים מרחוק הוא שזהו בהתעטף רוחם עליהם כנ\"ל א\"כ מאחר שלעצמו לא קיבל כדי שיעור קבלה איך ישפיע לזולתו וק\"ו הוא אם לא נכנס אור האלקי בעצמו מצד בחי' קטנותו שזהו בחי' ביטול כלפי מעלה כנ\"ל איך יוכל להיות בחי' משפיע גם למטה ממדרגתו (וכמשל הנ\"ל בתלמיד שלא הבין לעומק השכל הגם שמבין קצת אבל מצד בחי' ביטולו בעצמו לגמרי כנ\"ל לא יוכל להיות בחי' משפיע כלל וכלל וכמו בעני כי יעטוף רוחו וכה\"ג) ולזאת יוכל להסתעף מעטופים הנ\"ל לבחי' נוגה שמעורב ברע כי כבר נתמעט האור האלקי בהן במיעוט כ\"כ עד שלא יוכלו להיות בחי' משפיע גילוי אלקות כלל וכאשר מסתתר אור האלקי לגמרי אז יוכל לקבל גם בחי' נוגה שמעורב טו\"ר משא\"כ בחי' הקשורים הנ\"ל שאור האלקי בגילוי בהן שיוכלו להיות בחי' משפיעים גילוי אלקות למטה מהם ודאי שלא יוכל להסתעף מהם יניקה לנוגה דאין רע יורד מלמעלה כלל. ויובן כל ענין זה בנה\"א באדם למטה דהנה מבואר למעלה דודאי א\"א להיות באדם שיש גילוי אלקות ממש בנפשו בתפלה בכונה שלימה במוחו ולבו בתוך תוכו ממש שיוכל לקבל שום דבר זר מבחי' הרע דנוגה אפי' בתערובת כתאות היתר שיש בו מבחי' הרע בדקות עכ\"פ וכה\"ג בשאר תענוגי עוה\"ז ימאס בהם בתכלית ורחוק מזה לגמרי ולא יסתעף ממנו בחי' רע לעולם כנ\"ל וזהו בחי' הקשורים ששרשן בבחי' הכלים דקדושה כנ\"ל דהיינו שיוכלו להיות גם בחי' משפיעים גילוי אלקות למטה מהם ע\"כ לא יש מהם צד קירוב להסתעפות רע דנוגה והענין דכלים דקדושה מבואר למעלה שהן בחי' מוחא ולבא ומעשי המצות שהן ג' כלים לנר\"נ שהוא ההתבוננות והתפעלות הלב באלקות והמעשה כו' הכל לא נבדל כלל מאלקות וכמו אחרי ה' תלכו גם במעשה כו' ובכ\"מ שיש גילוי אלקות ממש אין מקום כלל ליניקת החיצונים משם כידוע אבל בחי' העטופים הנ\"ל הן נשמות בנ\"א שאין בהם התפעלות אלקות במוח ולב כלל רק מרחוק מאוד אז בבחי' הכלים שלהם"],[2500660244,"כמו במעשה מוסתר אור האלקי ביותר ע\"כ יכול להיות מהם הסתעפות תערובת טו\"ר דנוגה והוא מה שאנו רואים באותן שנקר' עטופים כנ\"ל דמפני שאין אור אלקי מאיר בגילוי במוחם ולבם בתפלה מיד שיעסוק בהבלי עולם לבבו נמשך להתפעל מכל דבר רע ונעשה קרוב לשם ביותר כאלו לא התפלל כלום ואע\"פ שהוא רק בתאות היתר בלא רע גמור כלל אבל בתערובת רע בדקו' נמשך כולו (וגם מה שהוא מטעה א\"ע בהתפעלות בתפלה נק' תערובת טו\"ר שיש בזה קצת טוב וגם מבחי' הרע שהרי יסתעף מזה לגיאות גמורה וכעס וכו' כידוע) ונמצא שמבחי' הקדושה האלקית גם מחיצוניות הכלי' אין הסתעפות רע כלל אבל מבחי' העטופים יוכל להיות הסתעפות טו\"ר כנ\"ל והוא בחי' הממוצע בין הקדושה לנוגה דהיינו שלפני התהוות בחי' נוגה מתהוה תחלה דבר שכולו טוב ולא רע כלל שהוא העטופים שמשיג אלקות ומתבטל בעצמו בשפלות גדולה כנ\"ל שזהו כולו טוב. אך עכ\"ז מפני שלא נכנס בו גילוי אור האלקי יוכל לימשך אח\"כ לתערובת טו\"ר ובחי' הטוב שבו הוא המקור לבחי' טוב שבנוגה ולא לבחי' רע דנוגה כלל כמו שגם מנוגה לקה\"ט יש ממוצע בודאי כמו שנראה בתאות היתר שא\"א שיבא לידי רע גמור כ\"א ע\"י ממוצע שאינו רע גמור כפריקת עול וכגסות או טמטום החומר וכחום הטבעי הרע כאשר בא בתגבורת תערובת רע שבנוגה אז יסתעף לרע גמור כרציחה וניאוף כו' כענין וישמן ויבעט כו' וגסות הרוח אינו רע גמור וכן תאות היתר בחום רשפי אש ביותר אינו רע גמור ועכ\"ז הן הן המקוריי' לרע גמור כידוע לכל וכך יש ממוצע בין בחי' עטופים שכולו טוב בבושה ושפלות והכנעה יתירה מצד אלקות ממש עד שיוכל להיות נפרד מאלקות בתאות היתר היינו בחי' הקרירות בהעדר חיות אלקי (בל\"א ער איז טויט כו') כמת ממש שנקרא הסתלקות אור אלקי לגמרי אז ממילא יפול הנופל בהיתר עכ\"פ עד פריקת עול והוללות או עצבות ומרה שחור' ביאוש בנפשו כו' ובגסות וטמטום החומר שנקרא ממוצע להסתעפות רע גמור כנ\"ל וד\"ל. והנה"],[2500660245,"עכ\"פ נמצא יובן מכל הנ\"ל בנשמות הנק' קשורים ועטופים למעלה ג\"כ בבחי' השתלשלות העולמות דבי\"ע דאין ק\"נ שבכל עולם מקבל מהקדושה בסמוך לה מיד אלא ע\"י בחי' ממוצע והוא כמשל הנשמה האלקית הנמוכה ושפלה במדרג' שלא תוכל לקלוט אור האלקי רק מעט מזעיר וגם במעט הזה תתבטל ותתעלם בעצמותה עד שתתעטף עליה רוחה כנ\"ל כך בחי' הממוצע הזה הוא שנתמעט גילוי אור אלקי מי\"ס דמל' דקדושה בכל עולם ועולם לפי ערכו במיעוט אחר מיעוט עד שיתהוה דבר שאין בכחו לקבל אור אלקי כ\"א מעט מזעיר מאד וגם זה המעט בריחוק מקום בבחי' ביטול בעצמותו הנקרא בחי' עטופים כנ\"ל והן בחי' מלאכים עליונים שלפני התהות בחי' נוגה שבכל עולם שכולו טוב ולא רע כלל אפי' בתערובת כנ\"ל אבל מהם מסתעף מקור לנוגה והיינו דבחי' הטוב שבמלאכים הללו מקור לבחי' הטוב דנוגה שמעורב ברע כו' שמשם נמשך הסתעפות לרע גמור (כמו הנפילים היו בארץ שנק' בני האלקי' ממש ובנפילתם למטה נתערבו ברע גמור ע\"י שיש מהם הסתעפות לנוגה בתערובת טו\"ר) משא\"כ המלאכים העליונים יותר שמקבלים מכלים די\"ס דקדושה שאור האלקי מתקשר בהן מי\"ס דקדושה תמיד בגילוי גם בהסתעפות מקור לתערובת טו\"ר לא יצא מהם והן כמו השרפים וחיות ואופני הקודש שביטולם תמידי (ולא נקרא נפילים לעולם גם בירידתן למטה מטה בזה העולם בדרך שליחות כידוע) והן הנקר' קשורים שלא נק' ממוצעים כלל בין הקדושה לנוגה כי לא יסתעף מהם מקור לבחי' נוגה כלל דאע\"פ שנק' משפיעים כנ\"ל אבל הכל נמשך מהם רק טוב גמור ולא ימצא מהם שום צד קירוב לתערובת טו\"ר (וכמו בנפש האדם למטה אנו רואים שיש נשמות שנק' נפילים כמו סומך נופלים כידוע שנופלים בתאות היתר ומשם לאיסור כנ\"ל והיינו להיותן בחי' עטופים לבד כנ\"ל אבל אותן שנק' קשורים לא נק' נפילים לעולם גם בירידתן למטה ביותר כמו בטרדת הבלי"],[2500660246,"עולם וברוב תענוגי הזמן או בהגבהה יתירה בגדולה ועושר לא ישמן ויבעט לעולם כי רוח אלקי בקרבו בגילוי שאין משם הסתעפו' לרע כלל וכלל (וראיה לזה מאחר שאמרו דטינא היה בלבו וכה\"ג) אבל באמת הרי גם הרשע ישוב בתשוב' שלימה כראב\"ד וכה\"ג וכן נה\"ט המשוקעת בתאוה רעה יוכל לבא למס\"נ מפני שמתהפך מרע לטוב וזהו ענין הלבוש דנוגה טו\"ר שאב ואם ממשיכים שנק' צלם הנפש האלקי' שמתהפך מטוב לרע ומרע לטוב וד\"ל). וזהו והי' העטופים ללבן והקשורים ליעקב דהנה מבואר למעלה בהפרש היוצא עיקר בין עטופים לקשורים הוא אשר מהקשורים יוכל להיות בחי' תולדה וריבוי שפע למטה משא\"כ מבחי' העטופים שאין שום שפע נמשכת מהם מפני שלא קבלו לעצמן ושורש הענין הוא מטעם הנ\"ל שבחי' י\"ס דקדושה מאיר בקשורים בגילוי גמור בבחי' אור וכלי דוקא וידוע שבבחי' או\"כ די\"ס האלקי' שורה מבחי' אא\"ס שבאצי' דאיהו וחיוהי חד ממש כו' והיינו בכ\"מ שיש יחוד עליון דוקא שזהו בבחי' או\"כ שם יצו ה' את הברכה שהוא בחי' התולדה וריבוי אור ושפע האלקית עד אין שיעור ממש שזהו בחי' הא\"ס וכידוע דכל תולדה הוא בא מבחי' א\"ס ששורה ביחוד משפיע ומקבל שנק' או\"כ כו' והיינו בבחי' הקשורים דוקא שיש ביחוד שלהם יחוד עליון האלקי (בחי' יחוד מ\"ה וב\"ן שנק' יחוד זו\"נ אדם בכלל כללא דדכר ונוק') והוא במה שמתקשר בהן אור האלקי בבחי' קליטה שנק' זיווג יש בזה מבחי' זיווג העליון דזו\"נ קוב\"ה ושכינתיה ויוכלו להוליד בדומה להם עד אין שיעור (וכמארז\"ל ביחוד אדם התחתון איש ואשה זכו שכינה ביניהן כו') משא\"כ העטופים שאין אור א\"ס שורה בהם כ\"א מרחוק לא יוכלו להוליד כלל מפני שמתעטף רוחם עליהם ולא די שלא יולידו אלא שלא מקבלי' בעצמם ע\"כ יוכל להסתעף מהם שפע לק\"נ מעורב טו\"ר כנ\"ל דבחי' נוגה מן העטופים מקבל שנק' ממוצע בין הקדושה לנוגה וד\"ל. וזהו ובהעטיף הצאן"],[2500660247,"לא ישים. פי' הנשמות נק' צאן כנ\"ל והן באין בב' מדרגות דקשורים ועטופים הנ\"ל והנשמות שנק' צאן המקושרות יש בהן כח התולדה והריבוי מטעם הנ\"ל ע\"כ ישים לנגדן המקלות ברהטים בשקתות המים ליחם הצאן במקלות כדי שיולידו וירבו מאד לאין שיעור כמ\"ש ויפרוץ האיש מאד שהוא ע\"י המקלות שהעמיד ברהטים כידוע אך בהעטיף הצאן שהן נשמות שנק' עטופים לא ישים המקלות ברהטים כו' ליחם אותן כי אין בהן כח התולדה והריבוי כלל מטעם הנ\"ל ומלבד זה כדי שלא יומשך מהם שפע זרה שהוא ההסתעפות לק\"נ שמעורב ברע שלא יהיה שורש יניקה לחיצונים מן יחוד העליון דמקלות שברהטים כמ\"ש בזוהר בשורש עובדא זו דמקלות ברהטים ולכך בהעטיף הצאן לא ישים המקלות ברהטים כלל. ולהבין זה בתוס' ביאור הנה תחלה י\"ל בגוף ענין עובדא זו דמקלות ברהטים דהנה לכאורה כמובן מדברי הזוהר ע\"פ ויקח לו יעקב מקל לבנה כו' ויפצל בהן פצלות לבנות כו' העיקר הוא הלבן שבמקלות שהוא בחי' החסד עליון כמ\"ש מחשוף הלבן אשר על המקלות כו' אך א\"כ מה זה שאמ' ויחמו הצאן אל המקלות וכן מ\"ש תחלה ויצג המקלות כו' אשר תבאנה הצאן לשתות לנוכח הצאן ויחמנה בבואן לשתות דמשמע שזהו עיקר המכוון בהעמדת המקלות רק כדי שיחמנה הצאן בראותם המקלות בבואן לשתות ברהטים וכמ\"ש והיה בכל יחם הצאן המקושרות ושם יעקב את המקלות לעיני הצאן ברהטים ליחמנה במקלות כו'. אך הנה שניהם אמת דבחי' הלבן אשר על המקלות הוא אשר נעשה ליחם הצאן כמ\"ש ליחמנה במקלות ויחמו הצאן אל המקלות דהנה אע\"פ שכל חום ודאי שרשו מבחי' הגבורות דוקא היפך החסדים ואיך נמשך חום מבחי' החסדים הענין הוא דיש ב' מיני גבורות א' גבורות שמבחי' קו השמאל לבד והב' בחי' גבורות שמקו הימין שנק' גבורה שבחסד והיינו בחי' גבורו' ממותקות (כמו ארי' גי' גבורה והוא מבחי' הימין דחסד כמ\"ש פני אריה אל הימין) והענין הוא דבחי' קשורים הנ\"ל שנק' צאן המקושרות שנכנס בהן אור"],[2500660248,"האלקי בגילוי גמור כנ\"ל היינו ע\"י בחי' ההתפעלות אלקות באהבה רבה שנמשך כמים שנק' התקשרות והמשכה שהיא דביקות הנפש והתקשרותה באלקים חיים כידוע והוא בחי' החסדים ימין מקרבת כידוע אך כדי שיהיה בזה בחי' תולדה וריבוי א\"א באהבה לבד שהיא נמשכת כמים בבחי' הקרירות כו' אלא דוקא ע\"י בחי' הגבורות שהוא בחי' רשפי אש התשוקה בהתלהבות האהבה שנק' אהבה עזה מאד כמו רשפיה רשפי אש שלהבת יה ואי' בזוהר שהוא בחי' שלהובי דרחימותא שכאשר האהבה בוערת ברשפי אש שלהבת יה כו' הרי העיקר הוא האהבה והדביקות אך שהיא בוערת ברשפי אש שלהבת ממש כמו התשוקה והתאוה באהבת איש ואשתו כמ\"ש ואל אישך תשוקתך וכה\"ג ובחי' הגבור' רשפי אש שבאהבה דוקא הוא הנק' גבורות ממותקות בחסדים שהוא מבחי' קו הימין דחסד שבא בבחי' תגבור' גדולה ביותר כמו כי גבר עלינו חסדו בלי שיעור ומזה יבא התולדה והריבוי לאין שיעור משא\"כ החסדים בעצמם בלי התכללות מגבורות ממותקות בחסדים הנ\"ל שהוא חום רשפי אש האהבה אין בזה ריבוי ותולדה כלל רק כמו שהוא בעצמו בלי תוס' ומגרעות כו' וזהו שכל חום דוקא מוליד תולדה אע\"פ שחום זה בחי' גבורות אבל הוא בחי' גבו' שבחסד שזהו המשכה דטפה שנק' מ\"ד וכך הוא באשה כי תזריע בחי' מ\"ן והוא בבחי' חום התשוקה דוקא וד\"ל. וזהו בכל יחם הצאן המקושרות כאשה שכרתה ברית לבעלה ואל אישה תשוקתה בחום רשפי אש אך כדי שיוכלו להוליד צריך ליחם אותה להוסיף בה תשוקה יתירה בנשמה האלקי' הנק' צאן המקושרו' והיינו ע\"י מחשוף הלבן שעל המקלות ששם ברהטים שיחמנה הצאן בבואן לשתות והענין הוא כידוע שיעקב הוא בחי' קו האמצעי דת\"י דאצי' כמ\"ש אלקי אבי אברהם דחסד דקו ימין ופחד יצחק דקו השמאל הכל כלולים בו וידוע בבחי' הת\"ת שהוא עירוב הגוונין דחוור וסומק וירוק והעיקר דיופי הנקרא ת\"ת הוא במזיגה נכונה בעירוב הגוונין לא כשהלבן יותר מן האדום ולא כשאדום הרבה"],[2500660249,"אלא כ\"א על מקומו ועכ\"ז הלבן עיקר אלא שאין בו יופי כ\"א ע\"י אדום שבאמצעיתו כתפוח היפה כו' וכמ\"ש במ\"א בענין תרין תפוחין שזהו אור פני מלך חיים בהתגברות החסדים על הגבורות שאז נקרא גבורות ממותקות בחסדים שמהם עיקר תגבורת השפע ומשם נמשך ג\"כ התעוררות בתגבורת גדולה לעורר העלאת מ\"ן דנשמות שנקרא צאן המקושרות ליחמנה שיולידו כו' וזהו ענין המקלות שפיצל שהוא בחי' התכללות אורות עליונים דאצילות מבחי' גבורות ממותקות שיהיה האהבה עזה ברשפי אש כנ\"ל במזג נכון שיהיה יחוד עליון דאא\"ס בזה כפי כוונת המאציל כפי הצריך. וזהו שהעמיד המקלות ברהטים שהן בחי' הכלים להשפע' להשקות הצאן כמ\"ש ישקו כל חיתו כו' ובבוא הצאן המקושרות נשמות דאצי' שקשורים באלקות לשתות יחמו אל המקלות שהן יחודים עליונים שבע\"ס דאצי' מחו\"ג ממותקות מפני שנתעורר בהן מבחי' גבורה שבחסד עליון שבמקלות אשר ברהטים ויחמנה הצאן להוליד בדומה דוקא שהן בחי' נקודים וברודים מבחי' התיקון שבבחי' המקלות כו' ותולדה זו אין לה שיעור כלל"],[2500660250,"מצד בחי' אא\"ס שביחוד והתכללות שבפצלו' לבנות כו' אבל נשמות שהן בחי' העטופים לא יחמנה במקלות להיותם רחוקים מאור פ\"מ כו' כנ\"ל ולא יועיל בהן אור החסדים הכלולים מגבו' שבמקלות לעורר בהן תשוקה שלו שיוכלו להוליד מטעמים הנ\"ל ועוד כדי שלא יומשך לחיצונים שנק' צאן לבן הארמי אובד אבי בחי' המנגד לחכמה אלקות דקדושה כמ\"ש אני חכמה שכנתי ערמה כידוע וזהו ובהעטיף הצאן לא ישים המקלות כלל כנ\"ל וד\"ל. וזהו והיה העטופים ללבן להיות שהן בחי' הממוצע בין הקדושה לבחי' נוגה שאין בהן יחוד עליון כלל מטעם הנ\"ל והקשורים ליעקב להיות שבהן יחוד העליון דאצי' שיולידו בדומה לאין שיעור וז\"ש ויפרוץ האיש מאוד מאוד בבחי' א\"ס ממש וד\"ל. והתורה נצחית היא דאבות סימן לבנים שכל נשמות ישראל שנקראי' קשורים יולידו נשמות עד אין שיעור ולעשות פרי למעלה באצילות בי\"ס או\"כ כו' בתורה ומצות שעושין כמו שא' תולדותיהן של צדיקים מע\"ט וכמו אלו דברים שאדם אוכל פירותיהן בעוה\"ז כו' שהן יחודים עליונים שעושין בכל המצות למעלה וד\"ל:"],[2500660251,"<h3>ששים המה מלכות</h3>\n<b>ששים</b> המה מלכות כו' אחת היא יונתי כו' ס' מלכות ס' מסכתות ופ' פלגשים אלו שמונים ברייתות. אחת היא שכנ\"י למעלה מכולן וכמ\"ש רבות בנות כו' ואת עלית על כולנה. וזה פלא דהלא התורה משפיע לכנ\"י שנקרא כלה מאורשה כמ\"ש וארשתיך לי כו' אך באמת יש שורש לכנ\"י למעלה מהתורה שהרי לפעמים נקר' התורה כלה כמ\"ש תורה צוה כו' מאורשה והענין הוא דהנה תחלה י\"ל בטעם קריאת שם אחת לשון נוק' דוקא כידוע שהוא לפי שמקבלת מאחד שכנ\"י היא בחי' בית קיבול לזה לקבל בתוכם בחי' יחו\"ע דאח\"פ בתכלית שהרי ידוע בפי' שמע ישראל ששמע לשון אסיפה וקיבוץ שבית קיבול דמוח ולב מקבל לתוכו כל הארות אור דיחו\"ע דאחד הפשוט כשישראל קורין ק\"ש אפילו הקטן שבהם משום דזהו כמו טבע בנשמתם להיות בית קיבול ממש לזה וראיה לזה ממה שאמרו"],[2500660252,"השבטים ליעקב כשם שאין בלבך אלא א' כך אין בלבנו אלא א' ורבותא קאמר דגם שהשבטים הן בבחי' עולם הבריאה יש מאין כמו אתה בראת כו' אין בלבבם רק אח\"פ שלפני האצילות וכמו שאין בלבו דיעקב שהוא באצילות ממש בשוה דיחו\"ת שוה ממש ליחו\"ע וזה פלא לכאורה מאחר שמסך מפסיק בין אצי' לבריאה אלא צ\"ל שיש שורש לכנ\"י למעלה בעצמות אא\"ס ממש שלפני הקו\"ח שורש האצילות ושם דוקא נקראו אחת שהם בית קיבול לאחה\"פ ממש כמו שהוא בעצמות שאין השתלשלות דקו\"ח תופס מקום כלל וכלל כידוע והאבות סימן לבנים להניח להם טבע זו בירושה שיוכל כ\"א מישראל להיות בית קבול להכיל בלבו אח\"פ ממש וז\"ש אחת היא כו' שאין זה בס' מלכות דתורה כנ\"ל. ולהבין זה הנה לע\"ל ודאי יהיה כן בכנ\"י דכתיב כי תהיו אתם ארץ חפץ וכן יקר' חפצי בה דהנ' פי' חפץ"],[2500660253,"הוא ענין המשכה כללית מעצמות הנפש דהיינו כל פנימית ועצמות רצונו בדבר זה שחפץ שאין נופל ע\"ז ענין רצון שנמשך בפרט שהרצון שנמשך בפרט בא לידי גבול והתחלקות שהרי הרצון יתפשט לפעמים בזה הדבר ולפעמים בדבר אחר זולתו כאדם שיש לו כמה רצונות לכמה דברים כמו שרוצה בכבוד ורוצה גם בממון ויש לכ\"א רצון והמשכה מיוחדת ומוגבלת ועד\"ז יבא הרצון לכמה חלקים פרטים בכמה עניינים פרטים אבל החפץ הוא בחי' המשכת פנימיותו ועצמותו לדבר אחד שכולל כל מיני רצון דהיינו מה שתמיד ירצה בו כשיזכור עליו כוללם יחד טרם שירצה בו בגילוי שא\"א לומר בפנימות זו ענין התפעלות רצון עדיין רק שודאי יתפעל תמיד ברצון עליו כמו כי חפץ בבת יעקב כו'. ונמצא שכל מיני רצון שיש לו הן חלקים מיוחדים וכולם כלא חשיבי ממש לגבי בחי' החפץ בדבר מצד שהוא פנימיותו ממש שכל מה שיבוא לידי רצון הכל כלול בזה כו' וזה שאמר כי תהיו ארץ חפץ ארץ שכלול כל מיני רצון שתמיד ירצה בה כנ\"ל הוא הנקרא ארץ חפץ שכל חפצו בה וכולם כלולים בו וכלא חשיבו כל שארי רצונות הבאים בעניינים זולתה וז\"ש אחת היא דגם שיש ששים מלכות ושמונים פלגשים ולכ\"א יש רצון ואהבה הכל כלא נגד חפץ ורצון עצמו שבכ\"י וכמ\"ש רק באבותיך חשק ה' וידוע דחשוקה ודביקה וחפיצה הכל בשורש וענין א' כנ\"ל וד\"ל:\n<b>ומאחר</b> שכנ\"י נקר' ארץ חפץ הרי כל פנימי' ועצמות רצון הפשוט דעצמות אא\"ס בה והיא בחי' בית קיבול להכיל ה\"ז נקרא אחת בית קיבול לאח\"פ ממש שזהו כולל כל מה שיבא אור הרצון בפרט בס' מסכתות וכנ\"ל בענין החפץ וד\"ל. וירושה זו נמשכת כמו טבע בנפשות ישראל גם בקטן שבקטנים כמ\"ש והנערה אשר חפץ בה המלך היא נשמה האלקית ונקראת בשם להיות בית קיבול להכיל פנימית ועצמות המלך וכמ\"ש בזוה\"ק זכאה ב\"נ דקוב\"ה אתרעי ביה כענין חפץ הנ\"ל וד\"ל. ואמנם הנה בחי' אחת הנ\"ל בכל ניצוץ מישראל הוא בהיכל הרצון באמת ויציב דהיינו אתדבקות רוחא ברוחא"],[2500660254,"כמו וישק יעקב לרחל כו' אבל בק\"ש עדיין הנשמה במדרגה שלמטה מזה והוא ברצון הנמשך ע\"י התבוננות דשמע ישראל ושמע לשון הבנה דוקא ועל ידי היגיעה בהתבוננות דוקא תהיה בית קיבול אח\"כ באמת ויציב שהוא קשורא דנשמתא ברצון עצמו הנ\"ל (ואעפ\"כ בשעה שכ\"א אומר שמע ישראל ה' אחד נעשה נשמתו כלי בית קיבול לאח\"פ כנ\"ל רק שהוא בהעלם) ויש להקדים לזה ענין אחד והוא אשר הנשמות באו למטה בבחי' זריעה דוקא כמו אור זרוע כו' וזרעתי את בית ישראל כו' ואמרו דכלום אדם זורע קב כו' והענין הוא דגם המצות נקראו זריעה כמו זורע צדקות כו' ונשמות בעוה\"ז דוקא כשתעשה המצות ה\"ז כמו שתצמיח הזריעה כידוע. וביאור הדברים הנה פי' נשמה הוא נר האלקי שזהו בטבע ממש ברוח זה שמתפעל ומכיר אלקו' בהכרה שנק' הרגשה בהרגשת חוש הטבעי (וכמו מי שאין לו הרגשה טובה בדבר מה אומרים לו שאין לו חוש בדבר זה כאיש שלא ראה מלחמה אין לו חוש בזה וכן מי שלא שמע כלי שיר אין לו חוש בזה).\n<b>(ולא</b> כמו נה\"ט אע\"פ שיוכל להתפעל בשכל ולב אין זה טבעיו' אצלה רק שנקנה בה ע\"פ ההרגל ביגיעה ומרחוק ה' נראה כו' כאוה\"ע דקרו לי' אלקא דאלקייא ואעפ\"כ גוים גמורים הן לפי שאין זה רק בבחי' הודאה חיצונית ולא נגע הדבר בפנימיו' כלל (אך בנה\"ט יוכל להיות ג\"כ כמו חוש הטבעי בצדיקים שלבם ברשותם וגופם מופשט מגשמי תאות זרות במותר לו וגם בבינוני' יוכל להיות הכרה טובה בלבם לב בשר ממש מצד דקות חומרם שהוא מטוב שבנוגה דאב ואם המשיכו שיתפעל לבו מאלקות בהתפעלו' חושי' כמו הנשמ' ע\"ד דוגמא בהמות וחיות דמרכב' כמשי\"ת) והנה כתיב וזרעתי ב\"י זרע אדם וזרע בהמה ויש להבין בזה דזרע אדם שבח ומעלה הוא אבל זרע בהמה מה זו מעלה כו' וגם אין שייך לומר וזרעתי על זרע בהמה כו' אך הנה ב' זריעות שא' כאן זרע אדם וזרע בהמה קאי הכל על בחי' אור הזרוע לצדיק עליון שנמשך בב' מדרגות הללו וכמ\"ש אדם ובהמה"],[2500660255,"תושיע ה' וכן ואני בהמות הייתי עמך וכמו שהנשמ' האלקי' נק' זרע אדם בבחי' זריע' מלמעלה דוקא כך זרע בהמה שרוח הבהמ' היורדת למטה נק' זרע בהמה בבחי' זריעה מלמעל' דוקא כמ\"ש וזרעתי כו' (והוא בחי' מ\"ה וב\"ן עגולי' ויושר) דאדם גימ' מ\"ה הרי הן נשמות שנולדו מיחוד זו\"ן וב\"ן גימ' בהמה נק' זרע בהמה מבחי' ב\"ן דמל' כשנק' בהמה רבה דרביעא כו' וד\"ל) וראי' לזה שהרי מה שהנשמות שבגופי' נקראים בשם בהמות וחיות הוא מצד שרשם למעל' בודאי וכמו שמצינו בשבטים שנק' ארי' וזאב ושור וחמור כמ\"ש יששכר חמור גרם כחמור למשא ויוסף שור כשור לעול ויהוד' ארי' ובנימין זאב וכה\"ג והרי כאשר אמרו השבטי' נשמות בגופים ליעקב כשם שאין בלבך כו' כולל ב' לבבות לב אדם דהיינו בחי' אור הזרוע מבחי' שם מ\"ה דאדם דאצי' ולב בהמה גי' ב\"ן וכמ\"ש ואני בהמות ועל שניהם אמרו אין בלבנו (מ\"ה וב\"ן דבריאה) אלא אחד לבדו ולא דבר זולתו וכמו ועמך לא חפצתי כלה שארי ולבבי הרי יוכל להיות עכ\"פ גם בלב בהמה כמו בלב אדם ממש א\"כ א\"א שיהיה זה רוח הבהמה הגשמית אלא רוח בהמה עליונה כו' וד\"ל. וביאור הדברים הנה יש להקדים מ\"ש כי רוח האדם העולה היא למעלה דהאדם נברא בקומה זקופה כי רוח האדם העולה היא למעלה ובהמה בריאותה בקומה כפופה ראשה ורגלה במדרגה אחת לפי שרוח הבהמה יורדת למטה. והענין הוא דהאדם נחלק בפרצופו במוח ולב מוח בראש למעלה ולב מקבל ממנו ומן הלב נמשך למטה ובבהמה מוחה ולבה ותנועת האברים הכל א' והיינו ההפרש למעלה בין בחי' עגולי' ויושר שהעגולים סובב הכל כ\"א בלי התחלקות מדרגו' כלל כמו וצבא השמים לך משתחוים בהשתחוא' דאופני' בעיגול מעלה ומטה כ\"א מבלי שימצא ראש וסוף וכמו סיבוב הגלגל בתנוע' א' מתנענע הכל עליונו ותחתיתו מראש נעשה סוף ומסוף ראש וכך חוזר חלילה מתחתיתו לעליונו ומעליונו לתחתיתו וזהו ג\"כ בחי' בהמה דמה שרוצה ברצונה כלול בזה שכל מדות ומעשה בלי חילוק מדרגות"],[2500660256,"כ\"א בפ\"ע כלל וזהו כמו שמתנענע הגלגל כולו בב\"א וכך ציור סופה ראשה ורגלה שוין וכא' הן מתכללים מבלי שימצא ראש וסוף לפעמים המעשה ראש והרצון סוף שלפעמים למטה הוא למעלה ולמעלה מטה ומיד חוזר ממעלה מטה כו' והוא מה שאנו רואים בהתפעלות פשוטה שבלב אדם בטבעית כמו מדות הבהמה גשמית שרצונו פשוט ואינו ניכר בו התחלקו' אופנים שונים כי הוא למטה מן הדעת שהוא למעלה מן הדעת כתאות המאכל בבהמה שתתאוה לעשב כו' וכמ\"כ בהיפוך מפחד המזיק כו' וראש וסוף רצון ומעשה כא' כנ\"ל אבל התפעלות אדם בר דעת יש בה חילוק מדרגות התחלתו ברצון שנמשך במוח ומתפעל בשכל שבמוח תחלה ואז עדיין לא נתפעל רק השכל לבד ומשם יומשך ללב והתפעלות הלב רק כפי השכל ונק' מדות שבשכל שהשכל חייב התפעלותם ומשם למעשה ונמצא במעשה נתמעט הרצון ויש בו ראש וסוף כשהוא בשכל במוח נק' ראש וכשבא במעשה באברי' נק' סוף והסוף מקבל מן הראש (רק שיש התכללות בבחי' התקון דשם מ\"ה דאדם מראש לסוף) כמ\"ש בסמוך ולכך הולך בקומה זקופה כידוע ונמצא שיש בנה\"ט עצמה ב' מדרגות דאדם ובהמה הכל בגשמיות בחי' אדם נק' נפש השכליי' במילי דעלמא במוח ולב בסדר קומת פרצוף אדם כנ\"ל ובחי' בהמה בלב בשר הטבעי כשבא בהתפעלות בהמה גשמית לכל דבר תאות הגוף החומרי (לבד תאות הכבוד להתנשאות ותאות ממון ודירה ולבוש וכה\"ג) והנה לכאור' יש יתרון מעלה בבהמה מבאדם בתוקף התפעלות שלה שכולה כא' בזה משא\"כ באדם תחלה במוח לבד ואם יתחברו כולם הרי בא הרצון במיעוט במעשה אבל בבהמה במעשה דוקא עיקר נקודת הרצון (וכמ\"ש במ\"א בענין אופני' שלמעלה מן השרפים מטעם זה ולכך נק' אופני הקדש בלא וי\"ו) ובאמת הרי ידוע יתרון האדם על הבהמה הרבה שהוא בצלם אלקים ונק' אדם אדמה לעליון ורודה בכל בהמות והכל נברא בשביל האדם שנברא ביום הוי\"ו כידוע בענין אחור וקדם צרתני אחור למע\"ב וקדם"],[2500660257,"למעש\"ב אך הנה ידוע שזהו כל ענין ההפרש שבין עולם התוהו ועולם התקון דבבחי' התוהו היה הכל בבחי' ב\"ן דבהמה וכמ\"ש בזוהר וכן בי' מאמרות בהמות וחיות קדמו לאדם והוא בחי' העיגולי' דתוהו כאשר יהיה האופן בתוך האופן כידוע ובחי' התקון הוא בחי' פרצוף אדם דוקא שהוא בצלם אלקים כולל הכל בעצמו ולכך ויקרא האדם שמות לכל הבהמה כו' שהרי הוא המעלה ומברר לדצ\"ח דמ\"ה מברר לב\"ן וכמ\"ש אדם כי יקריב מן הבהמה כו' וזהו וזרעתי את ב\"י זרע אדם וזרע בהמה בחי' מ\"ה וב\"ן כנ\"ל ומ\"ה דאדם יברר לב\"ן. וביאור הדברים הנה משמעות הפשוט במקרא זה דרוח האדם העול' דעיקר ההפרש בין אדם ובהמה אינו רק בזה דרוח האדם עולה למעלה ורוח הבהמה יורדת למטה ובאמת עיקר ההפרש הוא בשכל ודעת שאין לבהמה דעת והאדם בר דעת לא בעולה ויורד לבד דלכאורה מה יתרון לרוח העולה על היורד אך הנה אנו רואים בצבא השמים שמשתחוים כאופנים וכה\"ג שהעיקר הוא בבחי' הירידה למטה כהשתחואה שהוא מלמעלה למטה דוקא וכמו שמורה ע\"ז ענין הסיבוב דגלגל העגול שמעליונו יורד למטה וחוזר חלילה לירד עוד הפעם ממעלה למטה ואע\"פ שבסיבובו יש עליה מלמטה למעלה שהרי מתעלה חצי כדור הב' מעט מעט כשזה החצי יורד מ\"מ הרי העיקר הוא בכללותו השתחואה שזהו בחי' ירידה מגבוה לנמוך כלפי מי שהוא משתחוה כאדם שמשתחוה לפני אדון ומלך וכה\"ג וצבא השמים לך משתחוים כלפי שכינה שבמערב והיינו בחי' הודאה שמודים ומשתחוים כידוע וזהו רק בחי' נה\"י לבד שהוא בחי' המעשה בסיבוב זה שמשתחוה בפ\"מ ובזה מדרגת האופנים למטה מן השרפים כידוע דאופנים בעשיה כו' ושרפים בבריאה שהוא במוחין ומדות כו' כמו בשתים יכסה פניו בציור חב\"ד חג\"ת ובבחי' נה\"י דהיינו השתחואה בסיבוב שם הן המוחין שהוא בחי' ההשגה שכליי' דגלגלים כלולים כא' וזהו בחי' ב\"ן דעיגולים שזהו כמו בחי' בהמה למטה שראשה ורגלה כא' כנ\"ל דרוח הבהמה ג\"כ עד\"ז שהוא רק בחי' הירידה"],[2500660258,"למטה ולא העלא' למעלה וז\"ש כי רוח הבהמה יורדת למטה שלזה הבהמה בקומה כפופה ראשה למטה בשוה לרגלה ממש והוא מה שנראה המשכת רוח הבהמה רק למטה ולא למעלה כלל שאין לה השגה במה שלמעלה הימנה רק להתמשך למטה לצרכי טרף מזונה לעשב וכה\"ג אבל טבע רוח האדם הוא העולה למעלה ולא למטה וכמו שמורה ציור קומתו בקומה זקופה כלפי מעלה דוקא והוא מצד בחי' החכמה שבמוחו שנק' כח מ\"ה בחי' ביטול לאין וכמ\"ש והחכמה מאין שמפני שמאין דוקא תמצא ע\"כ נק' כח מ\"ה כידוע והוא עיקר בחי' אדם גי' מ\"ה ולכך טבעיות רוח האדם שעולה למעלה להשיג למעלה השופע ממקור חוצבו בבחי' אין שלמעלה הימנו ליכלל שם ועולה ואינו יורד היפך רוח הבהמה ממש וזהו עיקר יתרון מעלת האדם על הבהמה כמובן בפסוק הזה. ולהבין זה דלכאורה הרי גם מלאכים כאופנים וחיות הקדש שאינם בבחי' אדם משיגים לבחי' האין האלקי' המהוה אות' שלזה משתחוים כידוע ומה יתרון לאדם להכיר בוראו ע\"י החכמ' שבו יותר מהמלאכי'. אך הנה ידוע דהמלאכים וכל הברואים נבראו מבחי' אותיות הדבור לבד שהוא בחי' חיצוניות והנשמות דאדם שרשם מבחי' פנימיות ועצמות דהיינו מבחי' כח מ\"ה העצמי כמשל הולד ממוח האב כידוע שע\"ז א' והחכמה מאין תמצא בחי' כח מ\"ה בעצם שנק' אדם שם מ\"ה למעלה וע\"ז נק' אדם אדמה לעליון שהוא בצלם אלקים בבחי' העצמות ממש וזהו דוקא ע\"י בחי' החכמה שמאין בעצם הוא שיכול להכיר ולעלות במה שלמעלה הימנו וזהו כי רוח האדם עולה למעלה בעצמות ממש (וזהו עיקר טעם בחי' התיקון דאדם שלמעלה מבחי' התוהו כידוע בענין שם מ\"ה מלגאו דאיהו כו' והוא מטעם בחי' ההתכללות שלאחר ההתחלקות דוקא שזהו עיקר יתרון מעלת האדם על בחי' התכללות דבהמה וכגלגלים ואופנים וד\"ל) וכמאמר הזוהר לאשתאבא בגופא דמלכא ממש שאין זה במלאכים שאין שרשם רק מבחי' חיצוניות ואדרבה בחי' בהמות וחיות דמלאכים רוח הבהמה יורדת למטה בבחי'"],[2500660259,"הצמצום דשם ב\"ן שמשם שרשם והוא בחי' המל' כשיורדת למטה להחיות מאין ליש ונק' בהמה רבה דרביעא כו' וכמ\"ש בזוהר ע\"פ מצמיח חציר לבהמה שהן מלאכים שנק' חציר כו'. ובכ\"ז יובן ענין אדם ובהמה שהוא מ\"ה וב\"ן עד רום המעלות שהן עגולים ויושר תוהו ותקון כידוע עד שגם בישראל שהן רק בבחי' אדם בצלם אלקים א' ג\"כ וזרעתי את בית ישראל זרע אדם וזרע בהמה והיינו רבותא דקא' והענין הוא בהיות דשורש הנשמות כמו שהן למעלה בעצמות ממש נק' קדושים כידוע ונק' אור עליון אור המאיר בעצם להיותם בבחי' כח מ\"ה בעצם בעצמות המאציל ואור הזרוע משם למטה נק' זרע אדם וכמ\"כ יש שם נשמות שהן מבחי' ב\"ן דשם ב\"ן גי' בהמה וזרע בהמה הן כמו בחי' בהמות וחיות שנזכר בשבטים אריה וזאב שור וחמור דודאי קראם בשמות הללו ע\"ש שרשם למעלה שנקראו נשמותיהם למעלה בצורות הללו דאריה ושור כו' ואע\"פ שהן נשמות נק' ע\"ש חיות ובהמות הרי מוכרח מזה לומר דגם למעלה בשורש הנשמות יש נשמות מבחי' ב\"ן וכאשר באו למטה נק' זרע בהמה כו' ויובן זה במה שאנו רואים בנשמות ישראל שבאו בגופים שיש הרבה צדיקים שעבודתם באוי\"ר שכלי' דוקא ונקראו ראשי אלפי כו' בחי' מוחי' חב\"ד דכנ\"י ויש צדיקים ותמימי' הרבה שעבודתם בתמימות הלב במעשה המצות ובעבודה שבלב בהתפעלות פשוטה בלי התבוננות והשגות אלקות כלל ודמיון התפעלותם כמדות הבהמה ממש שהכל כלול כא' כנ\"ל בסיבוב דאופני' כו' וכמ\"ש ואני בהמות הייתי עמך ונשמות אלה ודאי הן בצלם אדם העליון בפרצוף מוחי' כו' ועכ\"ז עבודתם בלב בבחי' בהמה כפני אריה ושור שבמרכבה. וזהו ראיה שבנשמות יש ג\"כ מבחי' ב\"ן ונק' זרע בהמה וכמו שבנה\"ט הנק' נפש החיוני' יש ב' מדרגות הללו במילי דעלמא בצרכי גופו בשכל ודעת ובלא דעת כבהמה ממש והכל נפש אחת היא כך יובן בנשמות האלקי' שבאו דרך זריעה מלמעלה למטה בגופים שיש בהן ב' מדרגות הללו להתפעל באלקות בבחי' רוח האדם העולה"],[2500660260,"בכח מ\"ה העצמי הנ\"ל וגם להתפעל בלב טבעי כבהמה כמו לבי ובשרי ירננו אל אל חי שזהו כמו בטבעית ממש ואיך לב בשר החומרי יהיה לו טבעיי' לרנן בהתפעלות אמיתית מקרב הלב אל אל חי ממש שהרי לב החומרי נמשך בטבעו לתאות חומריות כידוע שהוא רוח הבהמה בגשמיות אך זהו מבחי' רוח בהמה עליונה שזהו כמו רוח האדם ממש רק שבא למטה בבחי' זרע בהמה כנ\"ל ולכך התפעלותו בלב בשר לרנן אל אל חי בטבעיות מצד שרשה למעלה כמו רוח האדם שמתפעל בהשגות אלקות בטבעיות כמו חוש הטבעי כנ\"ל וז\"ש וזרעתי את ב\"י זרע בהמה וד\"ל. ומעתה הנה יש להבין בגוף ענין הזריעה של הנשמות מהו להיות הנשמות נק' נר ה' נמשל אורה לאור הנר שיש בה ב' גוונין גוון לובן אור המאיר וגוון לבן זה הוא עצם האור והנמשך ממנו אחר הפתילה הוא אור שחור שסמוך לפתילה שהוא נה\"ט והוא נק' אור זרוע כמו החטה הזרועה בעפר החומרי שהחטה גשמי' היא כך בחי' אור הזרוע הזה ממש וכמו שאמרו ג' שותפין אב ואם ממשיכי' נה\"ט החומריות וה' נותן נשמה אלקי' בנה\"ט הזאת ה\"ז בחי' אור זרוע ממש וכמ\"ש חי ה' אשר עשה לי את הנפש הזאת שבאה בבחי' עשי' גשמי' כחטה הזרועה כו' וכמ\"ש אף עשיתיו נפש דעשי' והוא מה שאנו רואים בחי' התפעלות אלקות ממש במוח ולב הגשמי שודאי אין זה מצד עצמה שהן חומריים כשכל האנושי ולב החומרי שמלא בתאות זרות אלא הוא בחי' אור הנשמה הזרוע שמתלבשת בנה\"ט החומריים כידוע ויש בזה ב' מדריגות דאדם ובהמה כנ\"ל ושניהם נק' רוח אלקי ממש (בל\"א געטליך כמו בני האלקי' דמלאכים כידוע) ואמנם הנה אנו רואים בחוש נפש הטבעי' גם במוח ולב החומריי' שנמשך ע\"י אב ואם מתאות' כמ\"ש ע\"ז ובחטא יחמתני אמי מחימום התאוה כמו האודם דאשה שממנו בשר ודם זהו מזרע הנוק' שבאה בתאות בהמה וכן לובן דאיש שממנו עצמות ונפש זאת היא נפש החיוני' הטבעי' הרי גם היא מתפעל' במוח בשכל אנושי ובלב בחלל השמאלי דוקא בהתפעלות"],[2500660261,"אלקות בצדיקים גמורים מאיר בנפשם הטבעית אור האלקי ממש בהיותם מתפעלי' בכל לבם ונפשם החומריי' דוקא כמ\"ש בכל לבבך בשני יצריך עד שלבם חלל בקרבם שלא לחפוץ בשום דבר זר וכמ\"ש לבי ובשרי ירננו לבי ובשרי ממש וכמו כלה שארי ולבבי כלה לגמרי וראי' ממס\"נ על קה\"ש שמוסר הגוף החומרי וכמ\"ש ר\"ע מתי יבא לידי ואקיימנו שזהו מס\"נ בפ\"מ וגם בבינוני' יכול להיות התפעלות אלקי' אמיתית במוח ולב הגשמי' דוקא וכנראה בחוש במצות וידעת והשבות אל לבבך שיקיים כל איש מישראל כפום שיעורא דילי' בעבודה שבלב ומוח בתפלה שזהו ע\"י היגיעה בהתבוננות באותו שכל שבמוח שמשיג צרכי גופו בטבעו באותו שכל אנושי מייגע א\"ע להשיג אלקות ולהתפעל בשכל כמו שמתפעל בו במילי דעלמא ויותר מזה יפעל בהתפעלות הלב גשמי שבלב החומרי הזה שיתפעל בלב זה עצמו דוקא בהתפעלות אלקות ממש וכך בכל הכחות דנה\"ט אין זה רק מצד אור אלקי דנשמה שמתלבשת בשכל ומדות דנה\"ט ופועלת בהם התפעלות זאת ולא מצד עצמה כלל שהרי מי שנפגם נשמתו וכמו אוה\"ע וכה\"ג אין לו חוש התפעלות זאת רק מודה מרחוק כנ\"ל וזהו ענין עיקר הזריעה של הנשמות שבאו בגופים חומריי' דנה\"ט להביא בהן אור אלקי בשכל ומדות שבהן ובמעשה ע\"י המצות שנעשי' ג\"כ בבחי' נוגה דעשיי' דצ\"ח גשמיי' וע\"כ נק' המצות בשם זריעה ג\"כ כידוע וכמו עד\"מ האור של גווני השמש שמאיר בענן שנעשה בו גוונין האלו ממש רק שהן מגושמין ובולטים שם ביותר ובשינוי המהות כאור בוקע במסך וזהו הנק' נוגה כמו כאשר הוגה לשון בליטה כידוע וזהו כי אתה תאיר נרי שהוא אור הנשמה אלקית הזרוע ואז ממילא וה' יגיה חשכי דנה\"ט וד\"ל. והנה הזריעה הזאת דנשמות בעוה\"ז בגופי' כמ\"ש וזרעתי את ב\"י הוא בשביל הצמיחה שתהיה הרבה יותר וכמאמרם כלום אדם זורע קב אלא להוציא כמה כורים דודאי הנשמה אלקי' טרם בואה בנה\"ט היתה במדרגת אלקות ממש ובנה\"ט באה בהתלבשות בשכל ומדות דנה\"ט כנ\"ל"],[2500660262,"אך ירידה זו צורך עליי' היא כידוע ולהבין זה הנה תחלה י\"ל במשל הזריעה שא\"א שתוקלט בעפר הארץ כ\"א ע\"י חרישה תחלה ויש בזה עבודה רבה לעבוד האדמה לזרוק כל אבן ואח\"כ לעשות העפר תיחוח ע\"י החרישה דמרפי ארעא כידוע ואז יורקב הגרעין ולאחר רקיבתו דוקא יוקלט בארץ ויצמיח לעשות פרי עד ק' פעמים כמותו כמו ויזרע יצחק וימצא מאה שערים והדוגמא מכ\"ז למעלה באור נשמה האלקי' ענין החרישה בעפר הוא נה\"ט הנק' עפר חומרי שלא יהיה קשה כאבן הנק' טמטום הלב וטמטום המוח וטמטום זה יש שקשה כאבן ממש וע\"ז נא' והסירותי את לב האבן כמו שבעפר קשה כסלע לא יזרע שם מאומה וצריך זריקה לחוץ והוא תשובה על קושי הלב שלא יהיה ערל לב וכמ\"ש ומלתם את ערלת לבבכם ומלתם דוקא ומילה זו לערלת הלב כוללת החרישה ג\"כ דמרפי ארעא והוא כמו ענין הפריעה כמ\"ש במ\"א והוא להיות לב בשר שהוא רך ביותר היפך הקושי ובלא חרישה דמרפי הגם שאינו קשה כאבן לא יוקלט בו אור האלקי כו' וענין הרקבון של זרע אור הזרוע היא בחי' המרירות העצום שיתבאר. והנה תחלה יש להבין ענין חרישה זו בהיות שאמרו לעולם יהא אדם רך כקנה ואל יהא קשה כארז וזהו מדבר במילי דעלמא שיהא רך כקנה נגד כל אדם וכמעשה דר\"א בר\"ש שא' כמה מכוער כו' ושורש הענין הוא שיהא לו לב רך בטבעיו' להשפיל א\"ע לפני הכל כמו ונפשי כעפר כו' כעפר תיחוח שידרוס עליו כל אדם ואל יהא קשה כארז לעמוד בתוקף ועזות בלי יזיזוהו ממקומו כלל ולא יפול לבו מכל כו' וזהו תוקף הלב וקשיותו ביותר או רכותו וקטנותו ביותר כמארז\"ל על דהמע\"ה שבלימודו בתורה הי' רך כתולעת ובמלחמה הי' קשה כארז כו' והכל הוא במדות טבעיו' דנפש החיונית במילי דעלמא. ולכאורה מעלת ענין זה במילי דעלמא אינו ענין מעלה ומדרגה כלל למילי דשמיא דמה נפקא מינה יש אם יהי' רך במילי דעלמא או קשה כו' אך הנה כתיב והסירותי את לב האבן מבשרכם ונתתי לכם לב בשר וקאי זה לע\"ל"],[2500660263,"דוקא כידוע וגם בזה יש להבין כנ\"ל דמה נ\"מ אם יהי' הלב רך ולא קשה כאבן בטבעיו' והלא לעבודת ה' צריך להיות בגבורת הלב כמ\"ש הוי עז כנמר וגבור כארי כו' אלא הענין הוא דמה שהוא רך ולא קשה כאבן בטבעי' זהו בחי' כלי בית קיבול להכיל אור האלקי דנשמה האלקי' בנפשו הטבעית כמשל החרישה דמרפי ארעא הנ\"ל דבעפר תיחוח ורך דוקא יוקלט הזריעה ולא בקש' כך בלב רך כקנה יוקלט אור האלקי ולא בקש' כאבן וכמ\"ש זבחי אלקים רוח נשברה שהוא רוח נמוכה ונפש שפלה להיות לבו רך כקנה להטותו כל מי שירצה. וביאור הענין הזה הוא מ\"ש והסירותי את לב האבן דלכאורה יש להבין אם הדבר תלוי בבחירה מה יועיל לב בשר שגם אם הוא רך יוכל להיות חוטא וגם הקשה כארז יוכל להיות צדיק ויועיל לו תוקף לבו כנ\"ל אך הנה באמת לב בשר ולב האבן הזה קאי במילי דשמיא דכמו שישנם במילי דעלמא כך הן ממש במילי דשמיא דהנה אנו רואים בטבע העולם יש מי שלבבו רך בטבע שיפול לבו מפחד כ\"ש כמו במלחמה שיפחד הירא ורך הלבב וימס לבב אחיו כלבבו וכן יפול לב הרך מפני איש גדול כשר ומלך וממילא יטו לבבו בקל ויזיזוהו ממקומו מיד והסימן הוא הביישן שמתבייש ונופל ממעמדו (בל\"א איין וייחער מענטש ער פאלט אראפ מכל וכל כו') ולהיפך לב קשה כארז לא יפול לבו מכל פחד ולא יזוז ממקומו ומעמדו מפני כל איש גדול (בל\"א איין שטארקי הארץ ער פאלט גאר ניט אראפ פון קיין זאך) גם לא מאיזה צער וצרה בנפשו יסבול ולא יפול ויכנע לבבו כפרעה שהכביד לבו וזהו כמשל קשה כארז שכל הרוחות שבעולם לא יזיזוהו וקנה הרך שגם רוח קל יזיזוהו ויטהו לכל צד כו' וכך הוא במילי דשמיא דהנה אנו רואים בחוש שמחולקים טבע בנ\"א בעבודה שבלב בתפלה יש אדם שנופל לבו הטבעית דנה\"ט ויתעורר בתשובה לבכות על חטאיו ועכ\"פ יהיה לו בושה גדולה ונפילה בלבבו (ער פאלט אראפ זייער פר אלקות) וזהו מפני שלבו רך להכניע לפני אלקים חיים בהזכירו גם שאינו משיג"],[2500660264,"בהשגת אלקות רק שנזכר עליו בכלל יש לו בושה מקמי קוב\"ה ושכינתיה ונקרא ירא בושת בלבו הטבעית כמו שהוא רך בלבו בטבעיות ליפול לפני אדם גדול ביותר זהו הוראה שאין נפשו הטבעית מרע שבנוגה כ\"כ אלא מבחי' הטוב שבנוגה שאינו נפרד כ\"כ ע\"כ בקל יפול לבו לשוב בתשובה רק מצד אלקות שהוא מפחד פחד אלקים וכן הבושה מקמי קוב\"ה כו' (וכנ\"ל בפי' נוגה כמו שאור השמש מאיר בענן כו') ויש חלוקי מדרגות בזה עד שיכול להיות גוף טוב שהוא נמשך מאב ואם צד\"ג שיותר טוב מנשמה אלקית נמוכה שבזולתו כו' ויש בנ\"א שטבע לבם קשה שלא יפול לבו מכל השגת אלקות ג\"כ ולא יהרהר בתשובה גם בשעה שיש גילוי אלקות בנשמתו כי הוא לב האבן ממש שלא יאיר בו אור אלקי' וכמו בחי' רע דנוגה שנקרא רוח גסה ביותר ע\"כ הן בחי' נפרד גמור כמו ס\"מ ונוקביה דלית לון בושה מקמי קוב\"ה ושכינתיה כמ\"ש בתיקונים מתכווין למרוד בחוצפא כו' ואלה הנקראים אבירי לב הרחוקים מצדקה שהוא בחי' המ\"ל כמו מי שבטבע העולם הוא תקיפא לבא שנקרא עז פנים שאין לו בושה מכל כו' וע\"ז א' והסירותי לב האבן דלב האבן הזה מאוד רחוק לקבל אור אלקית וזהו עיקר סיבת מניעת גילוי אלקות גם בעובדי ה' בתפלה בהתבוננות שאין לבו ניזוז כלל גם ששכלו מתפעל ביותר (בל\"א ער הערט זייער אין מוח) שזהו מצד חומר נה\"ט דאביו ואמו שהמשיכו לו ממדרגות תחתונות דנוגה ויש להיפך שנשמתו שפלה בהתפעלות השכל (ער הערט גאר ניט אין מוח) ובלבו הטבעי יתפעל בקל מאוד ממעט גילוי אלקו' והוא בחי' לב בשר בהתפעלו' אלקות וזהו בחי' רך כקנה כמ\"ש תוכן לבות ה' תוכן חומר טוב דלב הטבעי לפי אופן רוחו שהוא הנשמה שמשכנה במוח שזהו ענין הגלגולים בסוד ה' יבואו לפי אופן הצריך בברורים דרפ\"ח שנפל בנוגה כן יזרעו נשמות בגופים יש נשמות גבוהות בגופים רעים (כצדיק בן רשע) ויש נשמות נמוכות בגופים טובים ועכ\"פ בחי' לב בשר בכלל הוא כלי בית קיבול לעצמות אלקות דוקא"],[2500660265,"(כמו לע\"ל דכנ\"י נקרא ארץ חפץ כנ\"ל וד\"ל) ומעתה יש להבין ענין הזריעה בשביל הצמיחה בריבוי יותר כנ\"ל דהנה מבואר למעלה ענין החרישה שהוא בחי' לב בשר רך כקנה ליפול מחמת גדולת ה' ואמנם בחי' חרישה זו אינה רק הכנה לקבלת אור האלקי בלבד אבל ענין הקליטה היינו שיכנס האור בתוך תוכו ממש כמו לבי ובשרי ירננו אל אל חי הנ\"ל הנה זה א\"א כ\"א ע\"י רקבון הזריעה תחלה כנ\"ל וענין הרקבון לכאורה הוא מיעוט וכליון אור הזרוע שהוא הנשמה אלקית ובזה דוקא תצמיח אח\"כ בריבוי גדול הענין הוא מה שאנו רואים שיש כמו בחוש טבעית באדם הישראלי שירע לבבו מאוד ויתמרמר ביותר על עוצם ריחוק נפשו מאלקים חיים ונקרא מרת נפש כמו מר נפש בגשמיות כשירע לבבו בצר לו מאוד בחסרון פרנסה או צער בנים וכה\"ג שרוחו מאוד נשבר כך ממש יוכל אדם להיות רוח לבבו נשבר על אשר נפשו ריקן מכל אור וחיות אלקית כמו שמיצר מהעדר חיי גופני ממש וזה פלא גדול לכאורה דמאין לו מרירות זו שמצד אלקות בלב בשר החומרי שאין טבעו להצטער רק מהעדר חיי גשמיות ואיך ירגיש בצער זה שאינו רק מצד אלקות אלא צריך לומר דודאי זהו מבחי' אור הנשמה האלקי' הנזרע בלב זה וכאשר היא בתענוג באלקו' יומשך בלב הטבעי ג\"כ תענוג וחדוה ולהיפך במרת הנפש האלקי' מריחוקה משרשה יבא עצב ומרירות גם בלב הטבעי עד שנחשב כמ\"ש טבעי' בהאי עלמא כנ\"ל וזהו הנק' רקבון אור אלקי הזרוע דהנה הנשמות בג\"ע וכה\"ג ודאי היתה דבוקה וחשוקה באהבה בתענוגי' להתענג על ה' כנשמות שנהנין מזיו בג\"ע ובבואה בלבוש חומר גופני נתרחקה ובאה במיעוט האור ולכך באה לכלל מרירות זאת והוא שנק' רקבון כמו בנפש הטבעית שתתמרמר מאיזה צער תבא לידי גרעון וחולי ואמנם רקבון זה יועיל לענין הצמיחה אח\"כ שתצמח הרבה והוא מצד השפלות והמרירות ממה שאינו יכול להתקרב לקבל אור אלקי' בהתבוננות והתפעלות הלב כלל אזי יבא לבחי' אין שבו שורה אין האלקי' שלמעלה"],[2500660266,"משורש נשמתו שהיתה קודם בואה לגוף ולכך תצמיח לעשות פרי למעלה בתענוג נפלא יותר מכמו שנהנין מזיו בג\"ע ודבר זה הוא פלא גדול לכאורה דהנה ידוע שאין ערך כלל וכלל לתענוג האלקית שבנשמה אשר מלובשת בחומר גופני לתענוג האלקי' שבנשמה בלא גוף בהיותה צרורה ודבוקה ממש באור פני מלך חיים כמו שאין ערך לתענוג גשמי שבנה\"ט בגופה במאכל וכה\"ג לתענוג הרוחני שבנפש הזאת כמו שהיא בבחי' הרוחניו' בלא צמצום בחיי בשר ודם החומרי ואין לדמות ביניהן ערך ויחוס כלל שהרי א\"א לומר בנפש הרוחנית שתתפעל בתענוג או צער מתענוגי הנפש בגוף במאכל ומהעדרה תצטער ותגרע אורה ואנו רואי' שעכ\"ז הא בהא תליא דמה שתתפעל הנפש בגוף בעונג וצער הכל הוא בא ונמשך מעונג וצער הרוחנית שבנפש הרוחנית רק שבא דרך דילוג בהתלבשות כידוע וכך יובן בנשמה האלקי' בענין עונג או צער שבעצמה הוא נבדל בערך ויחוס מעונג וצער שלה בהיותה בלבוש חומרי דנה\"ט ועכ\"ז יורד הוא ונמשך ומתחבר מרוחניות לגשמיות והיינו מה שירד אור הנשמה מתענוגה העליון שלמעלה להתענג על ה' בהיותה בנה\"ט בעונג גשמי בשכל והתבוננות ולב הטבעי וכן להתפעל בצער ומרירות על העדר העונג שהוא ענין הריחוק כנ\"ל וא\"כ איך אפשר לומר דמה שתתפעל הנשמה אלקי' בתענוג בלב גופני הוא במדרגה גבוה יותר מכמו שהיתה בתענוג אלקי הרוחני בג\"ע וכה\"ג אך הענין הוא כידוע במ\"ש הלך לך ובכה נושא משך הזרע דקאי זה על בחי' אור הזרוע לצדיק עליון שילך ובכה (כמו ויבך יוסף על צוארי בנימין אחיו כמ\"ש במ\"א) נושא משך אור זרוע דנשמות למטה פן יבואו לידי הפסד ורקבון לגמרי כמשל נושא משך הזרע גשמי' שילך ובכה בשעה שזורע פן ירקב הגרעין ויופסד גם הקרן לבד שלא ירויח בצמיחה כו' וא\"כ הרי יוכל להיות הפסד וכליון באור אלקי דנשמ' הזרוע בגוף ויוכל להיות להיפך שתצמיח הרב' כנ\"ל וזהו תלוי רק באם תקלוט או לא תקלוט דאם לא תקלוט תאבד ותפסיד צורתה והי' כלא הי' ואם תקלוט"],[2500660267,"בארץ תצמיח אח\"כ הגם שבקליט' ודאי יופסד צורתה יותר ותהי' כעפר ממש והוא עיקר הרקבון כידוע אך הפרש גדול יש בזה דרקבון זה שבארץ הרי בזה נכלל ויוצא כל כח רוחני שבה ונבלע בארץ בכח הצומח שבה לכך יומשך בה כח המצמיח להצמיחה בתו' וריבוי גדול משא\"כ כאשר נשארה בישותה וגסותה ולא נקלטה ונכלל' בארץ הרי העפר שעליה הרקיבה להפסידה לגמרי כו' וטעם הפרש ברקבון העפר על ידי קליטה לרקבון העפר שמרקיבה בלא קליטה עד שיש ביניהן מן הקצה לקצה זה ילך לאיבוד לגמרי וזה יצמיח בתוס' גדול הנה אין זה רק מה שבקליטה יבא לבחי' ביטול הישות לאין דכח הצומח משא\"כ בלא קליט' שגסותה קיימת ואז נהפוך הוא שגשם עפר הארץ המכסה עליה מרקיבה באופן ההפסד וכליון לגמרי מכל וכל והדוגמא מזה יובן במ\"ש הלך ילך ובכה דאם לא תקלט אור הזרוע בגוף יבא לכלל הפסד לגמרי ואם תקלט תצמיח הרבה. והענין הוא תלוי בזה רק בבחי' ישות וגסות הרוח או שפלות הרוח וביטולה לבחי' אין האלקי שזהו הפרש בין רקבון שבקליטה לרקבון והפסד סתם דהנה אנו רואים בכמה בני אדם שאין התעוררות בלבם כלל לעבודת ה' ואעפ\"י שבודאי יש להם נשמה אלקית גם ברשעים כו' אלא צ\"ל שלא נקלט האור אלקי בלבם והוא שאין לו מ\"ש הטבעי' הנ\"ל הנק' רקבון שאינו בא לבחי' אין וביטול לאלקות כלל אלא הוא בשלימותו הנקרא ישות וגסות (בל\"א גאנצקייט) ודוקא במילי דשמיא במה ששייך לענין אלקות שהוא כשר וזך בעניני דרכיו ואינו רואה בעצמו שום פחיתות ואז גם אם יעשה טוב ולא רע כו' יהיה הדבר בולט בישותו לומר הוא העושה טוב כידוע וכמו למען שמי יכבד וגם התפעלותו בלב בהתלהבות לפרקים אינו רק שחפץ למעלת הדבקות לחמם לבו בהתגלות כמ\"ש לא יחפוץ כסיל בתבונה כ\"א בהתגלו' לבו וזהו העושה גבהות הלב וגסותו ביותר ממילי דעלמא והוא היפך בחי' הביטול לאין הנ\"ל כמו ויגבה לבו בדרכי ה' הרי ודאי זהו מצד הנשמה אך להיותה בהגשמת יש ביותר"]]});
